import React, {useState, useCallback, useMemo, useEffect} from 'react';
import {StyleSheet, StyleProp, ViewStyle, NativeSyntheticEvent, ImageLoadEventData} from 'react-native';
import Animated, {useSharedValue, useAnimatedStyle, withTiming} from 'react-native-reanimated';
import View from '../../components/view';
import Image, {ImageProps} from '../../components/image';
import {useDidUpdate} from '../../hooks';
import Constants from '../../commons/Constants';

const UIAnimatedImage = Animated.createAnimatedComponent<ImageProps>(Image);

export interface AnimatedImageProps extends ImageProps {
  /**
   * Additional spacing styles for the container
   */
  containerStyle?: StyleProp<ViewStyle>;
  /**
   * Duration for the fade animation when the image is loaded
   */
  animationDuration?: number;
  /**
   * A component to render while the image is loading
   */
  loader?: React.ReactElement<any>;
}

/**
 * @description: Image component that fades-in the image with animation once it's loaded
 * @extends: Animated.Image
 * @gif: https://media.giphy.com/media/l0HU7jj0ivEFyZIA0/giphy.gif
 * @example: https://github.com/wix/react-native-ui-lib/blob/master/demo/src/screens/componentScreens/AnimatedImageScreen.js
 */
const AnimatedImage = (props: AnimatedImageProps) => {
  const {
    containerStyle,
    source,
    loader,
    style,
    onLoad: propsOnLoad,
    onLoadStart: propsOnLoadStart,
    animationDuration = 300,
    testID,
    ...others
  } = props;

  const [isLoading, setIsLoading] = useState(false);
  const opacity = useSharedValue(0);

  useDidUpdate(() => {
    if (!loader) {
      opacity.value = 1;
    }
  }, [loader]);

  useEffect(() => {
    if (Constants.isIOS) {
      setIsLoading(true);
      propsOnLoadStart?.();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [source]);

  const onLoad = useCallback((event: NativeSyntheticEvent<ImageLoadEventData>) => {
    setIsLoading(false);
    propsOnLoad?.(event);
    // did not start the animation already
    if (opacity.value === 0) {
      opacity.value = withTiming(1, {duration: animationDuration});
    }
  },
  // eslint-disable-next-line react-hooks/exhaustive-deps
  [setIsLoading, propsOnLoad, animationDuration]);

  // TODO: RN 77 - revert to this solution when iOS is fixed in future RN releases
  const onLoadStart = useCallback(() => {
    setIsLoading(true);
    propsOnLoadStart?.();
  }, [setIsLoading, propsOnLoadStart, animationDuration]);

  const fadeInStyle = useAnimatedStyle(() => {
    return {opacity: opacity.value};
  });

  // eslint-disable-next-line react-hooks/exhaustive-deps
  const _style = useMemo(() => [style, fadeInStyle], [style]);

  return (
    <View style={containerStyle}>
      <UIAnimatedImage
        {...others}
        style={_style}
        source={source}
        onLoad={onLoad}
        onLoadStart={Constants.isAndroid ? onLoadStart : undefined}
        testID={testID}
        imageStyle={undefined}
      />
      {isLoading && loader && <View style={styles.loader}>{loader}</View>}
    </View>
  );
};

AnimatedImage.displayName = 'AnimatedImage';

export default AnimatedImage;

const styles = StyleSheet.create({
  loader: {
    ...StyleSheet.absoluteFillObject,
    justifyContent: 'center'
  }
});

import _ from 'lodash';
import React from 'react';
import {StyleSheet, Animated} from 'react-native';
import {Colors} from '../../style';
import {BaseComponent} from '../../commons';
import View from '../../components/view';

// TODO: add finisher animation (check icon animation or something)
/**
 * @description: Scanner component for progress indication
 * @extends: Animated.View
 * @gif: https://media.giphy.com/media/l49JVcxoclUXbryiA/giphy.gif
 * @example: https://github.com/wix/react-native-ui-lib/blob/master/demo/src/screens/componentScreens/CardScannerScreen.js
 */
export default class AnimatedScanner extends BaseComponent {
  static displayName = 'AnimatedScanner';

  static defaultProps = {
    progress: 0,
    duration: 1000
  };

  constructor(props) {
    super(props);

    this.state = {
      animatedProgress: new Animated.Value(0),
      isDone: false
    };
  }

  componentDidMount() {
    const {progress, duration} = this.props;

    if (progress > 0) {
      this.animate(progress, duration);
    }
  }

  generateStyles() {
    this.styles = createStyles(this.props);
  }

  componentDidUpdate(prevProps) {
    const {progress, duration} = this.props;

    if (prevProps.progress !== progress) {
      this.animate(progress, duration);
    }
  }

  componentWillUnmount() {
    this.state.animatedProgress.stopAnimation();
  }

  animate(toValue, duration) {
    const {animatedProgress} = this.state;

    Animated.timing(animatedProgress, {
      toValue,
      duration,
      useNativeDriver: false
    }).start(({finished}) => {
      if (finished) {
        const isDone = toValue >= 100;
        this.setState({isDone});
        _.invoke(this.props, 'onBreakpoint', {progress: toValue, isDone});
      }
    });
  }

  render() {
    const {opacity, backgroundColor, hideScannerLine, style, containerStyle, testID} = this.props;
    const {isDone, animatedProgress} = this.state;

    return (
      <View style={[{...StyleSheet.absoluteFillObject}, containerStyle]}>
        <Animated.View
          style={[
            this.styles.container,
            style,
            opacity && {opacity},
            backgroundColor && {backgroundColor},
            {
              left: animatedProgress.interpolate({
                inputRange: [0, 100],
                outputRange: ['0%', '100%']
              })
            }
          ]}
          testID={testID}
        >
          {isDone && !hideScannerLine && <View style={this.styles.scanner}/>}
        </Animated.View>
      </View>
    );
  }
}

function createStyles() {
  return StyleSheet.create({
    container: {
      ...StyleSheet.absoluteFillObject,
      backgroundColor: Colors.white,
      opacity: 0.9
    },
    scanner: {
      ...StyleSheet.absoluteFillObject,
      borderWidth: StyleSheet.hairlineWidth,
      borderColor: Colors.grey50
    }
  });
}

import _ from 'lodash';
import React, {PropsWithChildren, useMemo, forwardRef, type JSX} from 'react';
import {
  StyleSheet,
  StyleProp,
  ViewStyle,
  TouchableOpacity,
  ImagePropsBase,
  ImageStyle,
  TextStyle,
  TextProps,
  AccessibilityProps
} from 'react-native';
import {Colors, BorderRadiuses} from '../../style';
import {extractAccessibilityProps} from '../../commons/modifiers';
import Badge, {BadgeProps} from '../badge';
import View from '../view';
import Text from '../text';
import Image, {ImageProps} from '../image';
// @ts-ignore
import AnimatedImage, {AnimatedImageProps} from '../animatedImage';
import * as AvatarHelper from '../../helpers/AvatarHelper';
import {useThemeProps} from '../../hooks';
import {isSvg} from '../../utils/imageUtils';
import Constants from '../../commons/Constants';

export enum BadgePosition {
  TOP_RIGHT = 'TOP_RIGHT',
  TOP_LEFT = 'TOP_LEFT',
  BOTTOM_RIGHT = 'BOTTOM_RIGHT',
  BOTTOM_LEFT = 'BOTTOM_LEFT'
}

const DEFAULT_BADGE_SIZE = 10;

export type AutoColorsProps = {
  /**
   * Avatar colors to be used when useAutoColors is true
   */
  avatarColors?: string[];
  /**
   * Replace the default hashing function (name -> number)
   */
  hashFunction?: (name?: string) => number;
  /**
   * Background color in cases where the getBackgroundColor returns undefined.
   */
  defaultColor?: string;
};

export type AvatarProps = Pick<AccessibilityProps, 'accessibilityLabel'> &
  PropsWithChildren<{
    /**
     * Adds fade in animation when Avatar image loads
     */
    animate?: boolean;
    /**
     * Background color for Avatar
     */
    backgroundColor?: string;
    /**
     * Badge location on Avatar
     */
    badgePosition?: `${BadgePosition}` | BadgePosition;
    /**
     * Badge props passed down to Badge component
     */
    badgeProps?: BadgeProps;
    /**
     * Additional spacing styles for the container
     */
    containerStyle?: StyleProp<ViewStyle>;
    /**
     * The image source (external or assets)
     */
    source?: ImageProps['source'];
    /**
     * Image props object
     */
    imageProps?: Partial<ImageProps & AnimatedImageProps>;
    /**
     * Image style object used to pass additional style props
     * by components which render image
     */
    imageStyle?: ImageStyle;
    /**
     * Listener-callback for when an image's (uri) loading
     * starts (equiv. to Image.onLoadStart()).
     */
    onImageLoadStart?: ImagePropsBase['onLoadStart'];
    /**
     * Listener-callback for when an image's (uri) loading
     * either succeeds or fails (equiv. to Image.onLoadEnd()).
     */
    onImageLoadEnd?: ImagePropsBase['onLoadEnd'];
    /**
     * Listener-callback for when an image's (uri) loading
     * fails (equiv. to Image.onError()).
     */
    onImageLoadError?: ImagePropsBase['onError'];
    /**
     * The name of the avatar user.
     * If no label is provided, the initials will be generated from the name.
     * autoColorsConfig will use the name to create the background color of the Avatar.
     */
    name?: string;
    /**
     * Hash the name (or label) to get a color, so each name will have a specific color.
     * Default is false.
     */
    useAutoColors?: boolean;
    /**
     * Send this to use the name to infer a backgroundColor
     */
    autoColorsConfig?: AutoColorsProps;
    /**
     * Label that can represent initials
     */
    label?: string;
    /**
     * The label color
     */
    labelColor?: string;
    /*
     * The ellipsize mode for the label, default is clip
     */
    labelEllipsizeMode?: TextProps['ellipsizeMode'];
    /**
     * ribbon label to display on the avatar
     */
    ribbonLabel?: string;
    /**
     * ribbon custom style
     */
    ribbonStyle?: StyleProp<ViewStyle>;
    /**
     * ribbon label custom style
     */
    ribbonLabelStyle?: StyleProp<TextStyle>;
    /**
     * Custom ribbon
     */
    customRibbon?: JSX.Element;
    /**
     * Custom size for the Avatar
     */
    size?: number;
    /**
     * Press handler
     */
    onPress?: (props: any) => void;
    /**
     * Used as a testing identifier
     */
    testID?: string;
  }>;

interface Statics {
  badgePosition: typeof BadgePosition;
}

/**
 * @description: Avatar component for displaying user profile images
 * @extends: TouchableOpacity, Image
 * @image: https://github.com/wix/react-native-ui-lib/blob/master/demo/showcase/Avatar/Avarat_1.png?raw=true, https://github.com/wix/react-native-ui-lib/blob/master/demo/showcase/Avatar/Avarat_2.png?raw=true
 * @example: https://github.com/wix/react-native-ui-lib/blob/master/demo/src/screens/componentScreens/AvatarsScreen.tsx
 */
const Avatar = forwardRef<any, AvatarProps>((props: AvatarProps, ref: React.ForwardedRef<any>) => {
  const themeProps = useThemeProps(props, 'Avatar');
  const {
    source,
    size = 50,
    labelColor = Colors.$textDefault,
    badgeProps = {},
    badgePosition = BadgePosition.TOP_RIGHT,
    testID,
    ribbonLabel,
    customRibbon,
    ribbonStyle,
    ribbonLabelStyle,
    animate = false,
    imageStyle,
    onImageLoadStart,
    onImageLoadEnd,
    onImageLoadError,
    imageProps,
    label,
    name,
    backgroundColor,
    useAutoColors,
    autoColorsConfig,
    containerStyle,
    labelEllipsizeMode = 'clip',
    onPress,
    children
  } = themeProps;

  const hitTargetPadding = Math.max(0, (48 - size) / 2);
  const {size: _badgeSize, borderWidth: badgeBorderWidth = 0} = badgeProps;
  const badgeSize = _badgeSize || DEFAULT_BADGE_SIZE;

  const _baseContainerStyle: StyleProp<ImageStyle> = useMemo(() => {
    return {
      width: size,
      height: size,
      alignItems: 'center',
      justifyContent: 'center',
      borderRadius: BorderRadiuses.br100
    };
  }, [size]);

  const initialsStyle = useMemo(() => {
    return {
      color: labelColor,
      backgroundColor: 'transparent',
      lineHeight: undefined
    };
  }, [labelColor]);

  const _baseRibbonStyle: StyleProp<ViewStyle> = useMemo(() => {
    return {
      position: 'absolute',
      top: '10%',
      left: size / 1.7,
      borderRadius: size / 2
    };
  }, [size]);

  const _ribbonStyle: StyleProp<ViewStyle> = useMemo(() => {
    return [_baseRibbonStyle, styles.ribbon, ribbonStyle];
  }, [_baseRibbonStyle, ribbonStyle]);

  const _badgePosition: StyleProp<ViewStyle> = useMemo(() => {
    const radius = size / 2;
    const x = Math.sqrt(radius ** 2 * 2);
    const y = x - radius;
    const shift = Math.sqrt(y ** 2 / 2) - (badgeSize + badgeBorderWidth * 2) / 2;
    const badgeLocation = _.split(_.toLower(badgePosition), '_', 2);
    return {position: 'absolute', [badgeLocation[0]]: shift, [badgeLocation[1]]: shift};
  }, [size, badgeBorderWidth, badgeSize, badgePosition]);

  const text = useMemo(() => {
    let text = label;
    if (_.isNil(label) && !_.isNil(name)) {
      text = AvatarHelper.getInitials(name);
    }

    return text;
  }, [label, name]);

  const _backgroundColor = useMemo(() => {
    if (backgroundColor) {
      return backgroundColor;
    }

    const {
      avatarColors = AvatarHelper.getAvatarColors(),
      hashFunction = AvatarHelper.hashStringToNumber,
      defaultColor = Colors.$backgroundNeutralLight
    } = autoColorsConfig || {};
    if (useAutoColors) {
      return AvatarHelper.getBackgroundColor(name, avatarColors, hashFunction, defaultColor);
    } else {
      return defaultColor;
    }
  }, [backgroundColor, autoColorsConfig, useAutoColors, name]);

  const _containerStyle: StyleProp<ViewStyle> = useMemo(() => {
    return [_baseContainerStyle, containerStyle];
  }, [_baseContainerStyle, containerStyle]);

  const textStyle = useMemo(() => {
    const typography = AvatarHelper.getInitialsTypography(size);
    return [typography, initialsStyle, {color: labelColor}];
  }, [size, initialsStyle, labelColor]);

  const textContainerStyle = useMemo(() => {
    const hasImage = !_.isUndefined(source);
    return [
      styles.initialsContainer,
      {backgroundColor: _backgroundColor},
      hasImage && styles.initialsContainerWithInset
    ];
  }, [source, _backgroundColor]);

  const accessibilityProps = useMemo(() => {
    return extractAccessibilityProps(props);
  }, [props]);

  const _imageStyle = useMemo(() => {
    return [_baseContainerStyle, StyleSheet.absoluteFillObject, imageStyle];
  }, [_baseContainerStyle, imageStyle]);

  const renderImage = () => {
    if (source !== undefined) {
      // Looks like reanimated does not support SVG
      const ImageContainer = animate && !isSvg(source) && !Constants.isWeb ? AnimatedImage : Image;
      return (
        <ImageContainer
          style={_imageStyle}
          source={source}
          onLoadStart={onImageLoadStart}
          onLoadEnd={onImageLoadEnd}
          onError={onImageLoadError}
          testID={`${testID}.image`}
          width={size}
          height={size}
          containerStyle={_baseContainerStyle}
          {...imageProps}
        />
      );
    }
  };

  const renderBadge = () => {
    if (!_.isEmpty(badgeProps)) {
      return (
        <Badge
          testID={`${testID}.onlineBadge`}
          iconProps={{tintColor: null}}
          {...badgeProps}
          size={badgeSize}
          containerStyle={_badgePosition}
        />
      );
    }
  };

  const renderRibbon = () => {
    if (!customRibbon && ribbonLabel) {
      return (
        <View style={_ribbonStyle}>
          <Text numberOfLines={1} text100 $textDefaultLight style={ribbonLabelStyle}>
            {ribbonLabel}
          </Text>
        </View>
      );
    }
  };

  const renderCustomRibbon = () => {
    if (customRibbon) {
      return <View style={_baseRibbonStyle}>{customRibbon}</View>;
    }
  };

  const Container = onPress ? TouchableOpacity : View;

  return (
    <Container
      style={_containerStyle}
      ref={ref}
      testID={testID}
      onPress={onPress}
      accessible={!_.isUndefined(onPress)}
      accessibilityLabel={'Avatar'}
      accessibilityRole={onPress ? 'button' : 'image'}
      hitSlop={onPress ? hitTargetPadding : undefined}
      {...accessibilityProps}
    >
      <View testID={`${testID}.container`} style={textContainerStyle}>
        {!_.isUndefined(text) && (
          <Text
            numberOfLines={1}
            ellipsizeMode={labelEllipsizeMode}
            style={textStyle}
            testID={`${testID}.label`}
            accessibilityLabel={accessibilityProps?.accessibilityLabel}
          >
            {text}
          </Text>
        )}
      </View>
      {renderImage()}
      {renderBadge()}
      {renderCustomRibbon()}
      {renderRibbon()}
      {children}
    </Container>
  );
});

