import _ from 'lodash';
import React, {PureComponent, type JSX} from 'react';
import {
  ImageSourcePropType,
  ImageStyle,
  StyleProp,
  StyleSheet,
  TextStyle,
  TouchableOpacityProps,
  ViewStyle,
  ViewProps
} from 'react-native';
import {extractAccessibilityProps} from '../../commons/modifiers';
import {asBaseComponent} from '../../commons/new';
import {BorderRadiuses, Colors, Spacings, Typography} from '../../style';
import TouchableOpacity from '../touchableOpacity';
import Image from '../image';
import View from '../view';
import Text from '../text';

const LABEL_FORMATTER_VALUES = [1, 2, 3, 4] as const;
const DEFAULT_PIMPLE_SIZE = 10;
const DEFAULT_BADGE_SIZE = 20;

type LabelFormatterValues = typeof LABEL_FORMATTER_VALUES[number];

export type BadgeProps = ViewProps &
  TouchableOpacityProps & {
    /**
     * Text to show inside the badge.
     * Not passing a label (undefined) will present a pimple badge.
     */
    label?: string;
    /**
     * Color of the badge background
     */
    backgroundColor?: string;
    /**
     * the badge size
     */
    size?: number;
    /**
     * Press handler
     */
    onPress?: (props: any) => void;
    /**
     * Defines how far a touch event can start away from the badge.
     */
    hitSlop?: ViewProps['hitSlop'];
    /**
     * width of border around the badge
     */
    borderWidth?: number;
    /**
     * radius of border around the badge
     */
    borderRadius?: number;
    /**
     * color of border around the badge
     */
    borderColor?: ImageStyle['borderColor'];
    /**
     * Additional styles for the top container
     */
    containerStyle?: StyleProp<ViewStyle>;
    /**
     * Additional styles for the badge label
     */
    labelStyle?: StyleProp<TextStyle>;
    /**
     * Receives a number from 1 to 4, representing the label's max digit length.
     * Beyond the max number for that digit length, a "+" will show at the end.
     * If set to a value not included in LABEL_FORMATTER_VALUES, no formatting will occur.
     * Example: labelLengthFormater={2}, label={124}, label will present "99+".
     */
    labelFormatterLimit?: LabelFormatterValues;
    /**
     * Renders an icon badge
     */
    icon?: ImageSourcePropType;
    /**
     * Additional styling to badge icon
     */
    iconStyle?: object;
    /**
     * Additional props passed to icon
     */
    iconProps?: object;
    /**
     * Custom element to render instead of an icon
     */
    customElement?: JSX.Element;
    key?: string | number;
  };

/**
 * @description: Round colored badge, typically used to show a number
 * @extends: View
 * @image: https://user-images.githubusercontent.com/33805983/34480753-df7a868a-efb6-11e7-9072-80f5c110a4f3.png
 * @example: https://github.com/wix/react-native-ui-lib/blob/master/demo/src/screens/componentScreens/BadgesScreen.tsx
 */
class Badge extends PureComponent<BadgeProps> {
  static displayName = 'Badge';

  styles: ReturnType<typeof createStyles>;

  constructor(props: BadgeProps) {
    super(props);

    this.styles = createStyles(props);
  }

  getAccessibilityProps() {
    const {onPress, icon, label, accessibilityLabel} = this.props;

    return {
      accessibilityLabel: accessibilityLabel || label ? `${label} new items` : 'badge',
      ...extractAccessibilityProps(this.props),
      accessible: !_.isUndefined(label),
      accessibilityRole: onPress ? 'button' : icon ? 'image' : 'text'
    };
  }

  get size() {
    const {size, label} = this.props;
    if (size !== undefined) {
      return size;
    }
    return label === undefined ? DEFAULT_PIMPLE_SIZE : DEFAULT_BADGE_SIZE;
  }

  isSmallBadge() {
    return this.size <= 16;
  }

  getBadgeSizeStyle() {
    const {borderWidth, icon, customElement} = this.props;
    const label = this.getFormattedLabel();

    const style: any = {
      paddingHorizontal: this.isSmallBadge() ? 4 : 6,
      height: this.size,
      minWidth: this.size
    };
    if (icon && label) {
      style.paddingRight = 6;
      style.paddingLeft = 4;
      style.height = Spacings.s5;
      if (borderWidth) {
        style.height += borderWidth * 2;
      }
      return style;
    }
    if (customElement) {
      return style;
    }
    const isPimple = label === undefined;
    if (isPimple || icon) {
      style.paddingHorizontal = 0;
      style.minWidth = undefined;
      style.width = style.height;
      if (borderWidth) {
        style.height += borderWidth * 2;
        style.width += borderWidth * 2;
      }
      return style;
    }

    if (borderWidth) {
      style.height += borderWidth * 2;
      style.minWidth += borderWidth * 2;
    }
    return style;
  }

  getFormattedLabel() {
    const {labelFormatterLimit, label} = this.props;

    if (_.isNaN(label)) {
      return label;
    }

    if (LABEL_FORMATTER_VALUES.includes(labelFormatterLimit!)) {
      const maxLabelNumber: any = 10 ** labelFormatterLimit! - 1;
      let formattedLabel: any = label;
      if (formattedLabel > maxLabelNumber) {
        formattedLabel = `${maxLabelNumber}+`;
      }
      return formattedLabel;
    } else {
      return label;
    }
  }

  getBorderStyling() {
    const {borderWidth, borderColor, borderRadius} = this.props;
    const style: ViewStyle = {};
    if (borderWidth) {
      style.borderWidth = borderWidth;
      style.borderColor = borderColor;
    }
    if (borderRadius) {
      style.borderRadius = borderRadius;
    }
    return style;
  }

  renderLabel() {
    const {labelStyle, label} = this.props;

    if (label) {
      return (
        <Text
          style={[this.styles.label, this.isSmallBadge() && this.styles.labelSmall, labelStyle]}
          allowFontScaling={false}
          numberOfLines={1}
          testID="badge"
          recorderTag={'unmask'}
        >
          {this.getFormattedLabel()}
        </Text>
      );
    }
  }

  renderCustomElement() {
    const {customElement} = this.props;
    return customElement;
  }

  renderIcon() {
    const {icon, iconStyle, iconProps, borderColor, label} = this.props;
    const flex = label ? 0 : 1;
    return (
      icon && (
        <Image
          source={icon!}
          resizeMode="contain"
          tintColor={Colors.$iconDefaultLight}
          //@ts-ignore
          borderColor={borderColor}
          {...iconProps}
          style={{
            flex,
            ...iconStyle
          }}
        />
      )
    );
  }

  render() {
    const {activeOpacity, backgroundColor, containerStyle, hitSlop, onPress, testID, ...others} = this.props;
    const backgroundStyle = backgroundColor && {backgroundColor};
    const sizeStyle = this.getBadgeSizeStyle();
    const borderStyle = this.getBorderStyling();
    const Container = onPress ? TouchableOpacity : View;

    return (
      // The extra View wrapper is to break badge's flex-ness
      // @ts-ignore
      <View
        style={containerStyle}
        {...others}
        backgroundColor={undefined}
        // @ts-expect-error
        borderWidth={undefined}
        {...this.getAccessibilityProps()}
      >
        <Container
          testID={testID}
          pointerEvents={'none'}
          style={[sizeStyle, this.styles.badge, borderStyle, backgroundStyle]}
          onPress={onPress}
          activeOpacity={activeOpacity}
          hitSlop={hitSlop}
          row
        >
          {this.renderCustomElement()}
          {this.renderIcon()}
          {this.renderLabel()}
        </Container>
      </View>
    );
  }
}

function createStyles(props: BadgeProps) {
  const styles = StyleSheet.create({
    badge: {
      alignSelf: 'flex-start',
      borderRadius: BorderRadiuses.br100,
      backgroundColor: !props.icon || props.customElement ? Colors.$backgroundGeneralHeavy : undefined,
      alignItems: 'center',
      justifyContent: 'center',
      overflow: 'hidden'
    },
    label: {
      ...Typography.text90,
      color: Colors.$textDefaultLight,
      backgroundColor: 'transparent'
    },
    labelSmall: {
      ...Typography.text100,
      lineHeight: undefined
    }
  });

  return styles;
}
export {Badge}; // For tests

export default asBaseComponent<BadgeProps, typeof Badge>(Badge);

import {StyleSheet} from 'react-native';
import {useComponentDriver, ComponentProps, usePressableDriver, TextDriver, ImageDriver} from '../../testkit';

export const ButtonDriver = (props: ComponentProps) => {
  const driver = usePressableDriver(useComponentDriver(props));

  const labelDriver = TextDriver({
    renderTree: props.renderTree,
    testID: `${props.testID}.label`
  });

  const iconDriver = ImageDriver({
    renderTree: props.renderTree,
    testID: `${props.testID}.icon`
  });

  const getLabel = () => {
    return labelDriver;
  };

  const getLabelStyle = () => {
    return labelDriver?.getStyle();
  };

  const getIcon = () => {
    return iconDriver;
  };

  const getIconStyle = () => {
    return StyleSheet.flatten(iconDriver?.getElement().props.style);
  };

  const getStyle = () => {
    return StyleSheet.flatten(driver.getElement().props.style);
  };

  const isDisabled = () => {
    return !!driver.getElement().props.accessibilityState?.disabled;
  };

  return {getStyle, getLabel, getLabelStyle, getIconStyle, getIcon, isDisabled, ...driver};
};

import _ from 'lodash';
import React, {PureComponent} from 'react';
import {Platform, StyleSheet, LayoutAnimation, LayoutChangeEvent, ImageStyle, TextStyle, StyleProp} from 'react-native';
import {asBaseComponent, forwardRef, Constants} from '../../commons/new';
import {Colors, Typography, BorderRadiuses} from 'style';
import TouchableOpacity from '../touchableOpacity';
import View from '../view';
import type {Dictionary, ComponentStatics} from '../../typings/common';
import Text from '../text';
import Icon from '../icon';
import {
  ButtonSize,
  ButtonAnimationDirection,
  ButtonProps,
  ButtonState,
  Props,
  DEFAULT_PROPS,
  ButtonSizeProp
} from './types';
import {PADDINGS, HORIZONTAL_PADDINGS, MIN_WIDTH, DEFAULT_SIZE, SIZE_TO_VERTICAL_HITSLOP} from './ButtonConstants';

export {ButtonSize, ButtonAnimationDirection, ButtonProps};

class Button extends PureComponent<Props, ButtonState> {
  static displayName = 'Button';

  static defaultProps = DEFAULT_PROPS;

  static sizes = ButtonSize;

  static animationDirection = ButtonAnimationDirection;

  // This redundant constructor for some reason fix tests :/
  // eslint-disable-next-line
  constructor(props: Props) {
    super(props);
  }

  state: ButtonState = {
    size: undefined,
    measuredSize: undefined,
    borderRadius: undefined
  };
  styles = createStyles();

  componentDidUpdate(prevProps: Props) {
    if (this.props.animateLayout && !_.isEqual(prevProps, this.props)) {
      LayoutAnimation.configureNext(LayoutAnimation.Presets.easeInEaseOut);
    }
  }

  // This method will be called more than once in case of layout change!
  onLayout = (event: LayoutChangeEvent) => {
    const {width, height} = event.nativeEvent.layout;

    if (this.props.round) {
      const size = height >= width ? height : width;
      this.setState({size});
    }
    if (this.needsHitslopMeasurement()) {
      this.setState({measuredSize: {width, height}});
    }

    if (Constants.isAndroid && (Platform.Version as number) <= 17) {
      this.setState({borderRadius: height / 2});
    }
  };

  needsHitslopMeasurement() {
    const {avoidMinWidth, avoidInnerPadding, round} = this.props;
    return this.isLink || (this.isIconButton && !round) || avoidMinWidth || avoidInnerPadding;
  }

  get isLink() {
    const {link, hyperlink} = this.props;
    return link || hyperlink;
  }

  get isFilled() {
    return this.getBackgroundColor() !== 'transparent';
  }

  get isIconButton() {
    const {iconSource, label} = this.props;
    return iconSource && !label;
  }

  getBackgroundColor() {
    const {disabled, outline, disabledBackgroundColor, backgroundColor, modifiers} = this.props;
    const {backgroundColor: modifiersBackgroundColor} = modifiers;

    if (!outline && !this.isLink) {
      if (disabled) {
        return disabledBackgroundColor || Colors.$backgroundDisabled;
      }

      return backgroundColor || modifiersBackgroundColor || Colors.$backgroundPrimaryHeavy;
    }
    return 'transparent';
  }

  getActiveBackgroundColor() {
    const {getActiveBackgroundColor} = this.props;

    if (getActiveBackgroundColor) {
      return getActiveBackgroundColor(this.getBackgroundColor(), this.props);
    }
  }

  getLabelColor() {
    const {linkColor, outline, outlineColor, disabled, color: propsColor, backgroundColor, modifiers} = this.props;
    const {color: modifiersColor} = modifiers;
    const isLink = this.isLink;

    let color: string | undefined = Colors.$textDefaultLight;
    if (isLink) {
      color = linkColor || Colors.$textPrimary;
    } else if (outline) {
      color = outlineColor || Colors.$textPrimary;
    } else if (this.isIconButton) {
      color = backgroundColor === 'transparent' ? undefined : Colors.$iconDefaultLight;
    }

    if (disabled && !this.isFilled) {
      return Colors.$textDisabled;
    }

    color = propsColor || modifiersColor || color;
    return color;
  }

  getIconColor(): string | undefined {
    const {disabled} = this.props;
    let tintColor = this.getLabelColor();

    if (disabled && !this.isFilled) {
      tintColor = Colors.$iconDisabled;
    }

    return tintColor;
  }

  getLabelSizeStyle() {
    const size = this.props.size || DEFAULT_SIZE;

    const LABEL_STYLE_BY_SIZE: Dictionary<TextStyle | undefined> = {};
    LABEL_STYLE_BY_SIZE[Button.sizes.xSmall] = Typography.text80;
    LABEL_STYLE_BY_SIZE[Button.sizes.small] = Typography.text80;
    LABEL_STYLE_BY_SIZE[Button.sizes.medium] = Typography.text80;
    LABEL_STYLE_BY_SIZE[Button.sizes.large] = undefined;

    const labelSizeStyle = LABEL_STYLE_BY_SIZE[size];
    return labelSizeStyle;
  }

  getContainerSizeStyle() {
    const {avoidMinWidth, avoidInnerPadding, round, size: propsSize} = this.props;
    const size = propsSize || DEFAULT_SIZE;

    const CONTAINER_STYLE_BY_SIZE: Record<
      string,
      Partial<{
        height: number;
        width: number;
        padding: number;
        paddingVertical: number;
        paddingHorizontal: number;
        minWidth: number;
      }>
    > = {};
    CONTAINER_STYLE_BY_SIZE[Button.sizes.xSmall] = round
      ? {height: this.state.size, width: this.state.size, padding: PADDINGS.XSMALL}
      : {
        paddingVertical: PADDINGS.XSMALL,
        paddingHorizontal: HORIZONTAL_PADDINGS.XSMALL,
        minWidth: MIN_WIDTH.XSMALL
      };
    CONTAINER_STYLE_BY_SIZE[Button.sizes.small] = round
      ? {height: this.state.size, width: this.state.size, padding: PADDINGS.SMALL}
      : {
        paddingVertical: PADDINGS.SMALL,
        paddingHorizontal: HORIZONTAL_PADDINGS.SMALL,
        minWidth: MIN_WIDTH.SMALL
      };
    CONTAINER_STYLE_BY_SIZE[Button.sizes.medium] = round
      ? {height: this.state.size, width: this.state.size, padding: PADDINGS.MEDIUM}
      : {
        paddingVertical: PADDINGS.MEDIUM,
        paddingHorizontal: HORIZONTAL_PADDINGS.MEDIUM,
        minWidth: MIN_WIDTH.MEDIUM
      };
    CONTAINER_STYLE_BY_SIZE[Button.sizes.large] = round
      ? {height: this.state.size, width: this.state.size, padding: PADDINGS.LARGE}
      : {
        paddingVertical: PADDINGS.LARGE,
        paddingHorizontal: HORIZONTAL_PADDINGS.LARGE,
        minWidth: MIN_WIDTH.LARGE
      };

    const containerSizeStyle = CONTAINER_STYLE_BY_SIZE[size];

    if (this.isLink || (this.isIconButton && !round)) {
      containerSizeStyle.paddingVertical = undefined;
      containerSizeStyle.paddingHorizontal = undefined;
      containerSizeStyle.minWidth = undefined;
    }

    if (avoidMinWidth) {
      containerSizeStyle.minWidth = undefined;
    }

    if (avoidInnerPadding) {
      containerSizeStyle.paddingVertical = undefined;
      containerSizeStyle.paddingHorizontal = undefined;
    }

    return containerSizeStyle;
  }

  getOutlineStyle() {
    const {outline, outlineColor, outlineWidth, disabled} = this.props;

    let outlineStyle;
    if ((outline || outlineColor) && !this.isLink) {
      outlineStyle = {
        borderWidth: outlineWidth ?? 1,
        borderColor: outlineColor || Colors.$outlinePrimary
      };

      if (disabled) {
        outlineStyle.borderColor = Colors.$outlineDisabled;
      }
    }
    return outlineStyle;
  }

  getBorderRadiusStyle() {
    const {fullWidth, borderRadius: propsBorderRadius, modifiers} = this.props;
    const {borderRadius: modifiersBorderRadius} = modifiers;

    if (this.isLink || fullWidth || propsBorderRadius === 0) {
      return {borderRadius: 0};
    }

    const borderRadius = propsBorderRadius || modifiersBorderRadius || BorderRadiuses.br100;
    return {borderRadius};
  }

  getShadowStyle() {
    const backgroundColor = this.getBackgroundColor();
    const {enableShadow} = this.props;

    if (enableShadow) {
      return [this.styles.shadowStyle, {shadowColor: backgroundColor}];
    }
  }

  getIconStyle(): [ImageStyle, StyleProp<ImageStyle>] {
    const {iconStyle: propsIconStyle, iconOnRight, size: propsSize, link} = this.props;
    const size = propsSize || DEFAULT_SIZE;
    const iconStyle: ImageStyle = {};
    const marginSide = link
      ? 4
      : ([Button.sizes.large, Button.sizes.medium] as ButtonSizeProp[]).includes(size)
        ? 8
        : 4;

    if (!this.isIconButton) {
      if (iconOnRight) {
        iconStyle.marginLeft = marginSide;
      } else {
        iconStyle.marginRight = marginSide;
      }
    }

    return [iconStyle, propsIconStyle];
  }

  getAnimationDirectionStyle() {
    const {animateTo} = this.props;

    let style;
    switch (animateTo) {
      case 'left':
        style = {alignSelf: 'flex-start'} as const;
        break;
      case 'right':
        style = {alignSelf: 'flex-end'} as const;
        break;
      default:
        // 'center' is the default
        break;
    }
    return style;
  }

  renderIcon() {
    const {iconSource, supportRTL, testID, iconProps} = this.props;

    if (iconSource) {
      const iconColor = this.getIconColor();
      const iconStyle = this.getIconStyle();

      if (typeof iconSource === 'function') {
        return iconSource([{tintColor: iconColor}, this.getIconStyle()]);
      } else {
        // if (Constants.isWeb) {
        return (
          <Icon
            style={iconStyle}
            source={iconSource}
            supportRTL={supportRTL}
            testID={`${testID}.icon`}
            // Note: Passing tintColor as prop is required for Web
            tintColor={iconColor}
            {...iconProps}
          />
        );
        // }
        // return (
        //   <Image
        //     source={iconSource}
        //     supportRTL={supportRTL}
        //     style={iconStyle}
        //     testID={`${testID}.icon`}
        //     {...iconProps}
        //   />
        // );
      }
    }
    return null;
  }

  renderLabel() {
    const {label, labelStyle, labelProps, hyperlink, testID, modifiers} = this.props;
    const color = this.getLabelColor();
    const labelSizeStyle = this.getLabelSizeStyle();
    const {typography} = modifiers;

    if (label) {
      return (
        <Text
          style={[this.styles.text, !!color && {color}, labelSizeStyle, typography, labelStyle]}
          underline={hyperlink}
          numberOfLines={1}
          testID={`${testID}.label`}
          recorderTag={'unmask'}
          {...labelProps}
        >
          {label}
        </Text>
      );
    }
    return null;
  }

  getAccessibleHitSlop() {
    const {measuredSize} = this.state;
    const containerStyle = this.getContainerSizeStyle();

    const buttonWidth = measuredSize?.width ?? containerStyle.width ?? containerStyle.minWidth ?? 0;
    const buttonHeight = measuredSize?.height ?? containerStyle.height ?? 0;

    const horizontalHitslop = Math.max(0, (48 - buttonWidth) / 2);
    const verticalHitslop = buttonHeight
      ? Math.max(0, (48 - buttonHeight) / 2)
      : SIZE_TO_VERTICAL_HITSLOP[this.props.size || DEFAULT_SIZE] / 2;

    return {
      top: verticalHitslop,
      bottom: verticalHitslop,
      left: horizontalHitslop,
      right: horizontalHitslop
    };
  }

  renderCustomBackground() {
    const {customBackground} = this.props;

    if (customBackground) {
      const borderRadiusStyle = this.getBorderRadiusStyle();
      return (
        <View absF style={[this.styles.backgroundElement, borderRadiusStyle]}>
          {customBackground}
        </View>
      );
    }
  }

  render() {
    const {
      onPress,
      disabled,
      style,
      testID,
      animateLayout,
      modifiers,
      forwardedRef,
      hitSlop: hitSlopProp,
      customBackground,
      ...others
    } = this.props;
    const shadowStyle = this.getShadowStyle();
    const {margins, paddings} = modifiers;
    const backgroundColor = customBackground ? undefined : this.getBackgroundColor();
    const outlineStyle = this.getOutlineStyle();
    const containerSizeStyle = this.getContainerSizeStyle();
    const borderRadiusStyle = this.getBorderRadiusStyle();

    return (
      <TouchableOpacity
        row
        centerV
        style={[
          this.styles.container,
          animateLayout && this.getAnimationDirectionStyle(),
          containerSizeStyle,
          this.isLink && this.styles.innerContainerLink,
          shadowStyle,
          margins,
          paddings,
          {backgroundColor},
          borderRadiusStyle,
          outlineStyle,
          style
        ]}
        activeOpacity={0.6}
        activeBackgroundColor={this.getActiveBackgroundColor()}
        onLayout={this.onLayout}
        onPress={onPress}
        disabled={disabled}
        testID={testID}
        hitSlop={hitSlopProp ?? this.getAccessibleHitSlop()}
        {...others}
        ref={forwardedRef}
      >
        {this.renderCustomBackground()}
        {this.props.children}
        {this.props.iconOnRight ? this.renderLabel() : this.renderIcon()}
        {this.props.iconOnRight ? this.renderIcon() : this.renderLabel()}
      </TouchableOpacity>
    );
  }
}

function createStyles() {
  return StyleSheet.create({
    container: {
      backgroundColor: 'transparent',
      justifyContent: 'center',
      alignItems: 'center'
    },
    innerContainerLink: {
      minWidth: undefined,
      paddingHorizontal: undefined,
      paddingVertical: undefined,
      borderRadius: BorderRadiuses.br0,
      backgroundColor: undefined
    },
    shadowStyle: {
      shadowOffset: {height: 5, width: 0},
      shadowOpacity: 0.35,
      shadowRadius: 9.5,
      elevation: 2
    },
    text: {
      backgroundColor: 'transparent',
      flexDirection: 'row',
      ...Typography.text70
    },
    backgroundElement: {
      overflow: 'hidden'
    }
  });
}

