import Icon, {IconProps} from '../icon';

export type ChipProps = ViewProps &
  TouchableOpacityProps & {
    //GENERAL
    /**
     * Chip's size. Number or a width and height object.
     */
    size?: number | Partial<{width: number; height: number}>;
    /**
     * On Chip press callback
     */
    onPress?: (props: any) => void;
    /**
     * Chip's background color
     */
    backgroundColor?: string;
    /**
     * The Chip borderRadius
     */
    borderRadius?: number;
    /**
     * Chip's container style
     */
    containerStyle?: StyleProp<ViewStyle>;
    /**
     * Uses size as minWidth and minHeight - default is true
     */
    useSizeAsMinimum?: boolean;
    /**
     * Disables all internal elements default spacings. Helps reach a custom design
     */
    resetSpacings?: boolean;
    /**
     * Used as testing identifier
     */
    testID?: string;

    //LABEL
    /**
     * Main Chip text
     */
    label?: string;
    /**
     * Label's style
     */
    labelStyle?: StyleProp<TextStyle>;

    //BADGE
    /**
     * Badge props object
     */
    badgeProps?: BadgeProps;
    /**
     * Display badge as counter (no background)
     */
    useCounter?: boolean;
    //AVATAR
    /**
     * Avatar props object
     */
    avatarProps?: AvatarProps;

    //ICON GENERAL
    /**
     * Additional icon props
     */
    iconProps?: Omit<IconProps, 'source'>;
    /**
     * Icon style
     */
    iconStyle?: StyleProp<ImageStyle>;

    //LEFT ICON
    /**
     * Left icon's source
     */
    iconSource?: ImageSourcePropType;

    //RIGHT ICON
    /**
     * Right icon's source
     */
    rightIconSource?: ImageSourcePropType;

    //LEFT ELEMENT
    /**
     * Left custom element
     */
    leftElement?: JSX.Element;

    //RIGHT ELEMENT
    /**
     * Right custom element
     */
    rightElement?: JSX.Element;

    //DISMISS ('x' button)
    /**
     * Adds a dismiss button and serves as its callback
     */
    onDismiss?: (props: any) => void;
    /**
     * Dismiss color
     */
    dismissColor?: string;
    /**
     * Dismiss asset
     */
    dismissIcon?: ImageSourcePropType;
    /**
     * Dismiss style
     */
    dismissIconStyle?: StyleProp<ImageStyle>;
    /**
     * Dismiss container style
     */
    dismissContainerStyle?: StyleProp<ImageStyle>;
  };

const DEFAULT_SIZE = 26;

/**
 * @description: Chip component
 * @extends: TouchableOpacity
 * @example: https://github.com/wix/react-native-ui-lib/blob/master/demo/src/screens/componentScreens/ChipScreen.tsx
 * @image: https://user-images.githubusercontent.com/1780255/119636022-e9743180-be1c-11eb-8f02-22eeab6558cd.png
 */
const Chip = ({
  avatarProps,
  backgroundColor,
  badgeProps,
  useCounter,
  borderRadius = BorderRadiuses.br100,
  containerStyle,
  onDismiss,
  dismissColor = Colors.$iconDefault,
  dismissIcon = Assets.internal.icons.x,
  dismissIconStyle,
  dismissContainerStyle,
  iconProps,
  iconSource,
  iconStyle,
  rightIconSource,
  leftElement,
  rightElement,
  label,
  labelStyle,
  onPress,
  resetSpacings,
  size = DEFAULT_SIZE,
  useSizeAsMinimum = true,
  recorderTag,
  testID,
  ...others
}: ChipProps) => {
  const renderIcon = useCallback((iconPosition: 'left' | 'right') => {
    const isLeftIcon = iconPosition === 'left';

    return (
      <Icon
        source={isLeftIcon ? iconSource : rightIconSource}
        testID={`${testID}.icon`}
        tintColor={Colors.$iconDefault}
        {...iconProps}
        style={[getMargins('iconSource'), iconStyle]}
      />
    );
  },
  [iconSource, rightIconSource, iconStyle, iconProps]);

  const renderBadge = useCallback(() => {
    return (
      <Badge
        size={20}
        testID={`${testID}.counter`}
        backgroundColor={useCounter ? 'transparent' : undefined}
        {...badgeProps}
        // @ts-ignore
        containerStyle={[getMargins('badge'), badgeProps.containerStyle]}
      />
    );
  }, [badgeProps]);

  const renderOnDismiss = useCallback(() => {
    return (
      <TouchableOpacity
        style={[getMargins('dismiss'), dismissContainerStyle]}
        onPress={onDismiss}
        hitSlop={{top: 16, bottom: 16, left: 10, right: 10}}
        testID={`${testID}.dismiss`}
      >
        <Icon
          source={dismissIcon}
          tintColor={dismissColor}
          style={[dismissIconStyle]}
          accessibilityLabel="dismiss"
          testID={`${testID}.dismissIcon`}
        />
      </TouchableOpacity>
    );
  }, [dismissContainerStyle, onDismiss, dismissIcon, dismissIconStyle]);

  const renderAvatar = useCallback(() => {
    return (
      <Avatar
        size={20}
        testID={`${testID}.avatar`}
        {...avatarProps}
        // @ts-ignore
        containerStyle={[getMargins('avatar'), avatarProps.containerStyle]}
      />
    );
  }, [avatarProps]);

  const renderLabel = useCallback(() => {
    return (
      <Text
        text90M
        numberOfLines={1}
        $textDefault
        style={[styles.label, getMargins('label'), labelStyle]}
        testID={`${testID}.label`}
        recorderTag={recorderTag}
      >
        {!!label && label}
      </Text>
    );
  }, [label, labelStyle]);

  const getMargins = useCallback((element: string): object | undefined => {
    if (!resetSpacings) {
      switch (element) {
        case 'label':
          if (avatarProps) {
            return {
              marginRight: Spacings.s2,
              marginLeft: Spacings.s1
            };
          }
          if (badgeProps) {
            return {
              marginLeft: Spacings.s3,
              marginRight: Spacings.s1
            };
          }
          if (iconSource || leftElement || rightIconSource || rightElement) {
            const addMarginLeft = !!(iconSource || leftElement);
            const addMarginRight = !!(rightIconSource || rightElement);
            const marginFromElement = Spacings.s1;
            if (addMarginLeft && addMarginRight) {
              return {
                marginHorizontal: marginFromElement
              };
            }
            if (addMarginLeft) {
              return {
                marginLeft: marginFromElement,
                marginRight: Spacings.s3
              };
            }
            if (addMarginRight) {
              return {
                marginLeft: Spacings.s3,
                marginRight: marginFromElement
              };
            }
          }
          if (onDismiss) {
            return {
              marginLeft: Spacings.s3,
              marginRight: Spacings.s2
            };
          } else {
            return {paddingHorizontal: Spacings.s3};
          }
        case 'avatar':
          return {
            marginLeft: 2
          };
        case 'badge':
          return {
            marginRight: Spacings.s1
          };
        case 'dismiss':
          return {
            marginRight: Spacings.s2
          };
      }
    }
  },
  [avatarProps, badgeProps, iconSource, rightIconSource, onDismiss]);

  const chipSize = useMemo(() => {
    const width = typeof size === 'object' ? size.width : size;
    const height = typeof size === 'object' ? size.height : size;
    return {width, height};
  }, [size]);

  const containerSizeStyle = useMemo(() => {
    const {width, height} = chipSize;
    return useSizeAsMinimum ? {minWidth: width, minHeight: height} : {width, height};
  }, [chipSize]);

  const Container = onPress ? TouchableOpacity : View;
  const hitSlop = useMemo(() => {
    const {width = 48, height = 48} = chipSize;
    const verticalHitSlop = Math.max(0, (48 - height) / 2);
    const horizontalHitSlop = Math.max(0, (48 - width) / 2);
    return {
      top: verticalHitSlop,
      bottom: verticalHitSlop,
      left: horizontalHitSlop,
      right: horizontalHitSlop
    };
  }, [chipSize]);

  return (
    <Container
      activeOpacity={1}
      onPress={onPress}
      style={[styles.container, {backgroundColor}, {borderRadius}, containerStyle, containerSizeStyle]}
      testID={testID}
      hitSlop={hitSlop}
      {...others}
    >
      {avatarProps && renderAvatar()}
      {iconSource && renderIcon('left')}
      {leftElement}
      {label && renderLabel()}
      {rightElement}
      {rightIconSource && renderIcon('right')}
      {badgeProps && renderBadge()}
      {onDismiss && renderOnDismiss()}
    </Container>
  );
};

Chip.displayName = 'Chip';

const styles = StyleSheet.create({
  container: {
    alignItems: 'center',
    justifyContent: 'center',
    flexDirection: 'row',
    borderWidth: 1,
    borderColor: Colors.$backgroundInverted,
    borderRadius: BorderRadiuses.br100
  },
  label: {
    alignItems: 'center',
    justifyContent: 'center'
  }
});

export default asBaseComponent<ChipProps>(Chip);

import React, {useCallback, useMemo, useRef, useState, forwardRef} from 'react';
import {StyleSheet, NativeSyntheticEvent, TextInputKeyPressEventData} from 'react-native';
import {isUndefined, map} from 'lodash';
import {Constants} from '../../commons/new';
import {useCombinedRefs, useDidUpdate} from '../../hooks';
import TextField, {TextFieldProps} from '../textField';
import Assets from '../../assets';
import Chip, {ChipProps} from '../chip';

export enum ChipsInputChangeReason {
  Added = 'added',
  Removed = 'removed'
}

type ChipsInputChangeReasonUnion = `${ChipsInputChangeReason}`;
export type ChipsInputChangeReasonProps = ChipsInputChangeReasonUnion | ChipsInputChangeReason;

type RenderChip = {index: number; chip: ChipsInputChipProps; isMarkedForRemoval: boolean};

export type ChipsInputChipProps = ChipProps & {invalid?: boolean};

export type ChipsInputProps = Omit<TextFieldProps, 'ref'> & {
  /**
   * Chip items to render in the input
   */
  chips?: ChipsInputChipProps[];
  /**
   * A default set of chip props to pass to all chips
   */
  defaultChipProps?: ChipProps;
  /**
   * A default set of chip props to pass to all invalid chips
   */
  invalidChipProps?: ChipProps;
  /**
   * Change callback for when chips changed (either added or removed)
   */
  onChange?: (chips: ChipsInputChipProps[], changeReason: ChipsInputChangeReason, updatedChip: ChipProps) => void;
  /**
   * Maximum chips
   */
  maxChips?: number;
};

const ChipsInput = forwardRef((props: ChipsInputProps, refToForward: React.Ref<any>) => {
  const fieldRef = useCombinedRefs(refToForward);
  const {
    chips = [],
    defaultChipProps,
    invalidChipProps,
    leadingAccessory,
    onChange,
    fieldStyle,
    maxChips,
    validate,
    ...others
  } = props;
  const [markedForRemoval, setMarkedForRemoval] = useState<number | undefined>(undefined);
  const fieldValue = useRef(others.value);

  const addChip = useCallback(() => {
    const reachedMaximum = maxChips && chips?.length >= maxChips;
    if (fieldValue.current && !reachedMaximum) {
      const newChip = {label: fieldValue.current};
      setMarkedForRemoval(undefined);
      // @ts-expect-error
      fieldRef.current.clear();
      fieldValue.current = '';
      /* NOTE: Delay change event to give clear field time to complete and avoid a flickering */
      setTimeout(() => {
        onChange?.([...chips, newChip], ChipsInputChangeReason.Added, newChip);
      }, 0);
    }
  }, [onChange, chips, maxChips]);

  const removeMarkedChip = useCallback(() => {
    if (!isUndefined(markedForRemoval)) {
      const removedChip = chips?.splice(markedForRemoval, 1);
      onChange?.([...chips], ChipsInputChangeReason.Removed, removedChip?.[0]);
      setMarkedForRemoval(undefined);
    }
  }, [chips, markedForRemoval, onChange]);

  const onChipPress = useCallback(({customValue: index}: {customValue: number}) => {
    const selectedChip = chips[index];
    selectedChip?.onPress?.();

    setMarkedForRemoval(index);
  },
  [chips]);

  const onChangeText = useCallback((value: string) => {
    fieldValue.current = value;
    props.onChangeText?.(value);

    if (!isUndefined(markedForRemoval)) {
      setMarkedForRemoval(undefined);
    }
  },
  [props.onChangeText, markedForRemoval]);

  const onKeyPress = useCallback((event: NativeSyntheticEvent<TextInputKeyPressEventData>) => {
    props.onKeyPress?.(event);
    const keyCode = event?.nativeEvent?.key;
    const pressedBackspace = keyCode === Constants.backspaceKey;

    if (pressedBackspace && !fieldValue.current && chips.length > 0) {
      if (isUndefined(markedForRemoval) || markedForRemoval !== chips.length - 1) {
        setMarkedForRemoval(chips.length - 1);
      } else {
        removeMarkedChip();
      }
    }
  },
  [chips, props.onKeyPress, markedForRemoval, removeMarkedChip]);

  const renderChip = (props: RenderChip) => {
    const {index, chip, isMarkedForRemoval} = props;
    return (
      <Chip
        key={index}
        customValue={index}
        // resetSpacings
        // paddingH-s2
        marginR-s2
        marginB-s2
        dismissIcon={Assets.internal.icons.xSmall}
        recorderTag={'mask'}
        {...defaultChipProps}
        {...(chip.invalid ? invalidChipProps : undefined)}
        {...chip}
        onPress={onChipPress}
        onDismiss={isMarkedForRemoval ? removeMarkedChip : undefined}
      />
    );
  };

  const chipList = useMemo(() => {
    return (
      <>
        {leadingAccessory}
        {map(chips, (chip, index) => {
          const isMarkedForRemoval = index === markedForRemoval;
          if (!maxChips || index < maxChips) {
            return renderChip({index, chip, isMarkedForRemoval});
          }
        })}
      </>
    );
  }, [chips, leadingAccessory, defaultChipProps, removeMarkedChip, markedForRemoval, maxChips]);

  const isRequired = useMemo(() => {
    if (!validate) {
      return false;
    }

    const inputValidators = Array.isArray(validate) ? validate : [validate];
    return inputValidators.includes('required');
  }, [validate]);

  const requiredValidator = useCallback(() => {
    return !isRequired || (chips?.length ?? 0) > 0;
  }, [isRequired, chips]);

  const _validate = useMemo(() => {
    if (!validate) {
      return undefined;
    } else if (isRequired) {
      const inputValidators = Array.isArray(validate) ? validate : [validate];
      return inputValidators.map(validator => (validator === 'required' ? requiredValidator : validator));
    } else {
      return validate;
    }
  }, [validate, isRequired, requiredValidator]);

  useDidUpdate(() => {
    if (others.validateOnChange) {
      // @ts-expect-error
      fieldRef.current?.validate();
    }
  }, [chips, others.validateOnChange]);

  return (
    <TextField
      // @ts-expect-error
      ref={fieldRef}
      leadingAccessory={chipList}
      blurOnSubmit={false}
      style={styles.input}
      {...others}
      onChangeText={onChangeText}
      onSubmitEditing={addChip}
      fieldStyle={[fieldStyle, styles.fieldStyle]}
      onKeyPress={onKeyPress}
      accessibilityHint={props.editable ? 'press keyboard delete button to remove last tag' : undefined}
      validate={_validate}
    />
  );
});

const styles = StyleSheet.create({
  fieldStyle: {
    flexWrap: 'wrap'
  },
  input: {
    flexGrow: undefined
  }
});
// @ts-expect-error
ChipsInput.changeReasons = {
  ADDED: 'added',
  REMOVED: 'removed'
};

export default ChipsInput;

import _ from 'lodash';
import memoize from 'memoize-one';
import React, {PureComponent} from 'react';
import {StyleSheet, StyleProp, ViewStyle} from 'react-native';
import {Colors} from '../../style';
import {Constants} from '../../commons/new';
import View from '../view';
import Carousel from '../carousel';
import ScrollBar from '../scrollBar';
import PageControl from '../pageControl';
import ColorSwatch, {ColorSwatchProps, ColorInfo, SWATCH_SIZE, SWATCH_MARGIN} from '../colorSwatch';

interface Props {
  /**
   * Array of colors to render in the palette
   */
  colors: string[];
  /**
   * Style to pass the palette container
   */
  containerStyle?: StyleProp<ViewStyle>;
  /**
   * The container margins
   */
  containerWidth?: number;
  /**
   * Whether to use pagination when number of colors exceeds the number of rows
   */
  usePagination?: boolean;
  /**
   * Whether the colors pagination scrolls in a loop
   */
  loop?: boolean;
  /**
   * The number of color rows from 2 to 5
   */
  numberOfRows?: number;
  /**
   * Style to pass all the ColorSwatches in the palette
   */
  swatchStyle?: StyleProp<ViewStyle>;
  /**
   * The value of the selected swatch
   */
  value?: string;
  /**
   * The index of the item to animate at first render (default is last)
   */
  animatedIndex?: number;
  /**
   * Invoked once when value changes by selecting one of the swatches in the palette
   */
  onValueChange?: ColorSwatchProps['onPress'];
  style?: StyleProp<ViewStyle>;
  testID?: string;
  /**
   * The ColorPalette's background color
   */
  backgroundColor?: string;
}
export type ColorPaletteProps = Props;

interface State {
  currentPage: number;
  scrollable: boolean;
  orientation?: string;
  contentWidth?: number;
}

const VERTICAL_PADDING = 16;
const HORIZONTAL_PADDING = 20;
const MINIMUM_MARGIN = 16;
const SCROLLABLE_HEIGHT = 92;
const DEFAULT_NUMBER_OF_ROWS = 3;

/**
 * @description: A color palette component
 * @example: https://github.com/wix/react-native-ui-lib/blob/master/demo/src/screens/componentScreens/ColorPickerScreen.tsx
 * @notes: This is a screen width component
 * @gif: https://github.com/wix/react-native-ui-lib/blob/master/demo/showcase/ColorPalette/ColorPalette.gif?raw=true
 */
class ColorPalette extends PureComponent<Props, State> {
  static displayName = 'ColorPalette';

  static defaultProps = {
    numberOfRows: DEFAULT_NUMBER_OF_ROWS,
    usePagination: true,
    loop: true,
    backgroundColor: Colors.$backgroundDefault
  };

  constructor(props: Props) {
    super(props);

    this.state = {
      currentPage: 0,
      scrollable: false,
      orientation: undefined,
      contentWidth: undefined
    };

    this.initLocalVariables();
  }

  carousel: React.RefObject<typeof Carousel | null> = React.createRef();
  scrollBar: React.RefObject<any> = React.createRef();
  itemsRefs?: any = React.createRef();
  selectedColorIndex?: number = undefined;
  selectedPage?: number = undefined;
  currentColorsCount?: number = undefined;
  itemsPerRow = 0;
  itemsPerPage = 0;
  usePagination?: boolean = undefined;
  innerMargin?: number = undefined;
  swatchStyles?: StyleProp<ViewStyle>[] = undefined;
  private dimensionsChangeListener: any;

  componentDidMount() {
    this.dimensionsChangeListener = Constants.addDimensionsEventListener(this.onOrientationChanged);
    _.times(this.props.colors.length, i => {
      this.itemsRefs.current[i] = React.createRef();
    });
    this.scrollToSelected();
  }

  componentDidUpdate(prevProps: Props) {
    if (this.props.colors !== prevProps.colors) {
      const newIndex = this.itemsRefs.current.length;
      this.itemsRefs.current[newIndex] = React.createRef();
      this.scrollToSelected();
    }
  }

  componentWillUnmount() {
    Constants.removeDimensionsEventListener(this.dimensionsChangeListener || this.onOrientationChanged);
  }

  onOrientationChanged = () => {
    if (this.state.orientation !== Constants.orientation) {
      this.initLocalVariables();
      this.setState({orientation: Constants.orientation}); // only to trigger render
    }
  };

  initLocalVariables() {
    this.itemsRefs.current = [];
    this.selectedColorIndex = undefined;
    this.selectedPage = undefined;
    this.currentColorsCount = this.colors.length;
    this.itemsPerRow = this.getItemsPerRow();
    this.itemsPerPage = this.itemsPerRow * this.getNumberOfRows();
    this.usePagination = this.shouldUsePagination();
    this.innerMargin = this.getInnerMargin();
    this.swatchStyles = [];
  }

  get value() {
    const {value} = this.props;

    if (Colors.isTransparent(value)) {
      return value;
    }
    return _.toUpper(value);
  }

  get colors() {
    return this.getUniqueColors(this.props.colors);
  }

  get containerWidth() {
    const {containerWidth} = this.props;
    return containerWidth || Constants.windowWidth;
  }

  getUniqueColors = memoize(colors => {
    const c = _.map(colors, color => {
      if (Colors.isTransparent(color)) {
        return color;
      }
      return _.toUpper(color);
    });
    return _.uniq(c);
  });

  getNumberOfRows() {
    const {numberOfRows = DEFAULT_NUMBER_OF_ROWS} = this.props;

    if (!_.inRange(numberOfRows, 2, 6)) {
      console.warn(`${numberOfRows} is not within valid range of color rows (2 to 5);
        defaulting to ${DEFAULT_NUMBER_OF_ROWS}.`);
      return DEFAULT_NUMBER_OF_ROWS;
    }
    return numberOfRows;
  }

  getItemsPerRow() {
    let itemsPerRow = 1;
    // first item has the page's padding around it
    const firstItemWidth = 2 * HORIZONTAL_PADDING + SWATCH_SIZE;
    // additional items have the minimum width of the margin between them and the previous item's width
    const additionalItemMinimumWidth = SWATCH_SIZE + MINIMUM_MARGIN;
    // floor(space left / size of additional items)
    itemsPerRow += Math.floor((this.containerWidth - firstItemWidth) / additionalItemMinimumWidth);

    return itemsPerRow;
  }

  shouldUsePagination() {
    const {usePagination} = this.props;
    return usePagination && this.colors.length > this.itemsPerPage;
  }

  getInnerMargin() {
    if (!this.usePagination) {
      return HORIZONTAL_PADDING / 2;
    }

    // Now that we have the itemsPerRow set, we can calculate the actual innerMargin
    const remainingSpace = this.containerWidth - this.itemsPerRow * SWATCH_SIZE - 2 * HORIZONTAL_PADDING;
    // With pagination - there's 1 less space than the number of items
    const numberOfMargins = this.itemsPerRow - 1;
    const margin = remainingSpace / numberOfMargins;
    // We have to subtract something since otherwise some Android devices will overflow into the next line
    return (margin - 0.001) / 2;
  }

  scrollToSelected = () =>
    setTimeout(() => {
      const {scrollable, currentPage} = this.state;

      if (scrollable && this.selectedColorIndex !== undefined && this.itemsRefs.current) {
        // The this.selectedColorIndex layout doesn't update on time
        // so we use this.selectedColorIndex - 1 and add an offset of 1 Swatch
        const childRef: any = this.itemsRefs.current[this.selectedColorIndex - 1]?.current;

        if (childRef) {
          const childLayout = childRef.getLayout();
          const leftMargins = this.getHorizontalMargins(this.selectedColorIndex).marginLeft;
          const childX = childLayout.x + childLayout.width + SWATCH_MARGIN + leftMargins + SWATCH_SIZE;
          if (childX > this.containerWidth) {
            this.scrollBar?.current?.scrollTo({
              x: childX + HORIZONTAL_PADDING - this.containerWidth,
              y: 0,
              animated: false
            });
          }
        } else if (this.usePagination) {
          this.carousel?.current?.goToPage(this.selectedPage || currentPage, false);
        }
      }
    }, 100);

  onContentSizeChange = (contentWidth: number) => {
    this.setState({
      scrollable: contentWidth > this.containerWidth,
      contentWidth
    });
  };

  onChangePage = (index: number) => {
    this.setState({currentPage: index});
  };

  onValueChange = (value: string, colorInfo: ColorInfo) => {
    this.props.onValueChange?.(value, colorInfo);
  };

  getHorizontalMargins = (index: number) => {
    const isFirst = index === 0;
    const isOnLeft = isFirst || index % this.itemsPerRow === 0;
    const isOnRight = index % this.itemsPerRow === this.itemsPerRow - 1;

    let marginLeft;
    let marginRight;

    if (this.usePagination) {
      marginLeft = isOnLeft ? 0 : this.innerMargin;
      marginRight = isOnRight ? 0 : this.innerMargin;
    } else {
      const isLast = index === this.colors.length - 1;
      marginLeft = isFirst ? 8 : this.innerMargin;
      marginRight = isLast ? 20 : this.innerMargin;
    }

    return {marginLeft, marginRight};
  };

  getSwatchStyle = (index: number) => {
    const sizeHasChanged = this.colors.length !== this.currentColorsCount;
    const isNextToLastIndex = index === this.colors.length - 2;

    // Need to update the next to last item because it's margin needs to changed
    if (!_.isUndefined(this.swatchStyles)) {
      if (_.isUndefined(this.swatchStyles[index]) || (!this.usePagination && sizeHasChanged && isNextToLastIndex)) {
        this.swatchStyles[index] = [this.getHorizontalMargins(index), this.props.swatchStyle];
        if (sizeHasChanged && isNextToLastIndex) {
          this.currentColorsCount = this.colors.length;
        }
      }
      return this.swatchStyles[index];
    }
  };

  renderColorSwatch(color: string, index: number) {
    const {animatedIndex, testID} = this.props;

    return (
      <ColorSwatch
        style={this.getSwatchStyle(index)}
        index={index}
        key={color}
        color={color}
        value={color}
        selected={this.value === color}
        animated={index === animatedIndex}
        onPress={this.onValueChange}
        ref={this.itemsRefs.current[index]}
        testID={`${testID}-${color}`}
      />
    );
  }

  renderPalette(props: Props, contentStyle: StyleProp<ViewStyle>, colors: string[], pageIndex: number) {
    const {style, ...others} = props;

    return (
      <View key={pageIndex} {...others} style={[styles.paletteContainer, contentStyle, style]}>
        {_.map(colors, (color, i) => {
          if (color === this.value) {
            this.selectedColorIndex = i;
            this.selectedPage = pageIndex;
          }
          return this.renderColorSwatch(color, i);
        })}
      </View>
    );
  }

  renderScrollableContent() {
    const {containerStyle, backgroundColor, ...others} = this.props;
    const {scrollable, contentWidth} = this.state;

    return (
      <ScrollBar
        ref={this.scrollBar}
        style={[containerStyle, {backgroundColor}]}
        scrollEnabled={scrollable}
        onContentSizeChange={this.onContentSizeChange}
        height={SCROLLABLE_HEIGHT}
        containerProps={{width: !scrollable ? contentWidth : undefined}}
        gradientHeight={SCROLLABLE_HEIGHT - 12}
        gradientColor={backgroundColor}
      >
        {this.renderPalette(others, styles.scrollContent, this.colors, 0)}
      </ScrollBar>
    );
  }

  renderPaginationContent() {
    const {containerStyle, loop, backgroundColor, ...others} = this.props;
    const {currentPage} = this.state;
    const colorGroups = _.chunk(this.colors, this.itemsPerPage);

    return (
      <View center style={[containerStyle, styles.paginationContainer, {backgroundColor}]}>
        <Carousel loop={loop} onChangePage={this.onChangePage} ref={this.carousel}>
          {_.map(colorGroups, (colorsPerPage, index) => {
            return this.renderPalette(others, {...styles.page, width: this.containerWidth}, colorsPerPage, index);
          })}
        </Carousel>
        <PageControl
          size={6}
          color={Colors.$backgroundInverted}
          inactiveColor={Colors.$backgroundDisabled}
          spacing={8}
          numOfPages={colorGroups.length}
          currentPage={currentPage}
        />
      </View>
    );
  }

  render() {
    return this.usePagination ? this.renderPaginationContent() : this.renderScrollableContent();
  }
}

export default ColorPalette;

