const DialogHeader = (props: DialogHeaderProps = {}) => {
  const {
    title,
    titleStyle,
    titleProps,
    subtitle,
    subtitleStyle,
    subtitleProps,
    showKnob = true,
    showDivider = true,
    leadingAccessory,
    trailingAccessory,
    topAccessory,
    bottomAccessory,
    contentContainerStyle,
    onPress,
    style,
    ...others
  } = props;

  const knob = useMemo(() => {
    if (showKnob) {
      return <View style={[styles.knob, {backgroundColor: Colors.$outlineDefault}]}/>;
    }
  }, [showKnob]);

  const headerContent = useMemo(() => {
    const Container = onPress ? TouchableOpacity : View;
    if (!isEmpty(title) || !isEmpty(subtitle)) {
      return (
        <Container onPress={onPress} center flex>
          {!isEmpty(title) && (
            <Text $textDefault {...titleProps} marginB-s3 style={titleStyle}>
              {title}
            </Text>
          )}
          {!isEmpty(subtitle) && (
            <Text $textDefault {...subtitleProps} marginB-s3 style={subtitleStyle}>
              {subtitle}
            </Text>
          )}
        </Container>
      );
    }

    return null;
  }, [title, titleStyle, titleProps, subtitle, subtitleStyle, subtitleProps, onPress]);

  const content = useMemo(() => {
    if (headerContent || leadingAccessory || trailingAccessory) {
      return (
        <View marginH-s5 marginV-s1 style={contentContainerStyle} row spread>
          {leadingAccessory}
          {headerContent}
          {trailingAccessory}
        </View>
      );
    }

    return null;
  }, [headerContent, leadingAccessory, trailingAccessory, contentContainerStyle]);

  const divider = useMemo(() => {
    if (showDivider) {
      return <View style={Dividers.d10}/>;
    }
  }, [showDivider]);

  if (knob || content || topAccessory || bottomAccessory || divider) {
    return (
      <View {...others} style={style}>
        {knob}
        {topAccessory}
        {content}
        {bottomAccessory}
        {divider}
      </View>
    );
  }

  return null;
};

