type DialogDirections = PanningDirections;
const DialogDirectionsEnum = PanningDirectionsEnum;
export {DialogDirections, DialogDirectionsEnum};

export interface DialogHeaderProps extends ViewProps {
  /**
   * Title
   */
  title?: string;
  /**
   * Title text style
   */
  titleStyle?: StyleProp<TextStyle>;
  /**
   * Title extra props
   */
  titleProps?: TextProps;
  /**
   * Subtitle
   */
  subtitle?: string;
  /**
   * Subtitle text style
   */
  subtitleStyle?: StyleProp<TextStyle>;
  /**
   * Subtitle extra props
   */
  subtitleProps?: TextProps;
  /**
   * Show the header's knob (default is true)
   */
  showKnob?: boolean;
  /**
   * Show the header's divider (default is true)
   */
  showDivider?: boolean;
  /**
   * Pass to render a leading element
   */
  leadingAccessory?: ReactElement<any>;
  /**
   * Pass to render a trailing element
   */
  trailingAccessory?: ReactElement<any>;
  /**
   * Pass to render a top element above the title
   */
  topAccessory?: ReactElement<any>;
  /**
   * Pass to render a bottom element below the subtitle
   */
  bottomAccessory?: ReactElement<any>;
  /**
   * Style for the leading + content + trailing components (without the topAccessory\bottomAccessory)
   */
  contentContainerStyle?: ViewProps['style'];
  /**
   * onPress callback for the inner content
   */
  onPress?: () => void;
}

export interface DialogCloseButtonProps {
  /**
   * The Dialog's header (title, subtitle etc)
   */
  headerProps?: DialogHeaderProps;
  /**
   * The Dialog`s container style (it is set to {position: 'absolute'})
   */
  containerStyle?: StyleProp<ViewStyle>;
  /**
   * Extra props for the container
   */
  containerProps?: Omit<ViewProps, 'reanimated' | 'animated' | 'style' | 'onLayout' | 'ref' | 'testID'>;
  /**
   * Whether to show the close button or not
   */
  showCloseButton?: boolean;
  /**
   * The close button props
   */
  closeButtonProps?: Pick<ButtonProps, 'label' | 'labelProps' | 'iconProps'>;
}

export interface _DialogProps extends AlignmentModifiers, Pick<ViewProps, 'useSafeArea'>, DialogCloseButtonProps {
  /**
   * The visibility of the dialog.
   */
  visible?: boolean;
  /**
   * The dialog width.
   */
  width?: DimensionValue;
  /**
   * The dialog height.
   */
  height?: DimensionValue;
  /**
   * Callback that is called after the dialog's dismiss (after the animation has ended).
   */
  onDismiss?: () => void;
  /**
   * The direction from which and to which the dialog is animating \ panning (default down).
   */
  direction?: DialogDirections;
  /**
   * Whether or not to ignore background press.
   */
  ignoreBackgroundPress?: boolean;
  /**
   * Additional props for the modal.
   */
  modalProps?: ModalProps;
  /**
   * Disable animation (default is false)
   * In some cases you might want to disable the animation (probably for Android only), this is when the dialog is scrollable and has touchable items in the scrollable area.
   * This is a temporary solution for a reanimated + RN77\8 bug.
   * See https://github.com/software-mansion/react-native-reanimated/issues/6659 and https://github.com/facebook/react-native/issues/49694
   */
  disableAnimation?: boolean;
  /**
   * Used to locate this view in end-to-end tests
   * The container has the unchanged id.
   * Currently supported inner IDs:
   * TODO: add missing <TestID>(s?)
   * <TestID>.modal - the Modal's id.
   * <TestID>.overlayFadingBackground - the fading background id.
   */
  testID?: string;
}

export type DialogProps = PropsWithChildren<_DialogProps>;

import React, {PropsWithChildren, useMemo} from 'react';
import {BorderRadiuses, Colors} from '../../style';
import {DialogCloseButtonProps} from './types';
import {StyleSheet} from 'react-native';
import Assets from '../../assets';
import DialogHeader from './DialogHeader';
import Icon from '../../components/icon';
import Text from '../../components/text';
import TouchableOpacity from '../../components/touchableOpacity';
import View from '../../components/view';

interface InternalDialogCloseButtonProps extends PropsWithChildren<DialogCloseButtonProps> {
  close: () => void;
}

const useDialogContent = (props: InternalDialogCloseButtonProps) => {
  const {
    showCloseButton,
    close,
    closeButtonProps,
    containerStyle: propsContainerStyle,
    containerProps: propsContainerProps,
    headerProps,
    children
  } = props;

  const DialogCloseButton = useMemo(() => {
    if (!showCloseButton) {
      return null;
    }

    return (
      <View left centerV pointerEvents={'box-none'}>
        <TouchableOpacity paddingB-s2 row onPress={close}>
          <Icon source={Assets.internal.icons.xMedium} tintColor={Colors.white} {...closeButtonProps?.iconProps}/>
          <Text recorderTag={'unmask'} text70BO white {...closeButtonProps?.labelProps}>
            {closeButtonProps?.label || 'Close'}
          </Text>
        </TouchableOpacity>
      </View>
    );
  }, [showCloseButton, close, closeButtonProps]);

  const containerProps = useMemo((): DialogCloseButtonProps['containerProps'] => {
    return showCloseButton ? {...propsContainerProps, pointerEvents: 'box-none'} : propsContainerProps;
  }, [showCloseButton, propsContainerProps]);

  const containerStyle = useMemo(() => {
    return showCloseButton ? [propsContainerStyle, styles.transparent] : propsContainerStyle;
  }, [showCloseButton, propsContainerStyle]);

  const renderDialogContent = () => {
    const DialogContent = (
      <>
        {headerProps && <DialogHeader {...headerProps}/>}
        {children}
      </>
    );

    if (DialogCloseButton) {
      return (
        <>
          {DialogCloseButton}
          <View style={styles.dialogContentContainer}>{DialogContent}</View>
        </>
      );
    } else {
      return DialogContent;
    }
  };

  return {renderDialogContent, containerStyle, containerProps};
};

export default useDialogContent;

const styles = StyleSheet.create({
  transparent: {
    backgroundColor: Colors.transparent
  },
  dialogContentContainer: {
    flexShrink: 1,
    backgroundColor: Colors.$backgroundDefault,
    overflow: 'hidden',
    borderRadius: BorderRadiuses.br60
  }
});

// @ts-nocheck
// @flow
// Similarly to the DrawerLayout component this deserves to be put in a
// separate repo. Although, keeping it here for the time being will allow us
// to move faster and fix possible issues quicker

// TODO: use Swipeable from react-native-gesture-handler once they support RTL

/* eslint-disable */
import React, {Component} from 'react';
import {Animated, StyleSheet, View, I18nManager} from 'react-native';
import {PanGestureHandler, TapGestureHandler, State} from 'react-native-gesture-handler';
import {Constants} from '../../commons/new';
import {HapticService, HapticType} from '../../services';


const DRAG_TOSS = 0.05;
const LEFT_TOGGLE_THRESHOLD = 0.6;

// Math.sign polyfill for iOS 8.x
if (!Math.sign) {
  Math.sign = function (x) {
    return Number(x > 0) - Number(x < 0) || +x;
  };
}

type Props = {
  children: any,
  friction: number,
  leftThreshold?: number,
  rightThreshold?: number,
  fullLeftThreshold?: number,
  fullSwipeLeft?: boolean,
  fullRightThreshold?: number,
  fullSwipeRight?: boolean,
  overshootLeft?: boolean,
  overshootRight?: boolean,
  overshootFriction?: number,
  onSwipeableLeftOpen?: Function,
  onSwipeableRightOpen?: Function,
  onSwipeableOpen?: Function,
  onSwipeableClose?: Function,
  onSwipeableLeftWillOpen?: Function,
  onSwipeableRightWillOpen?: Function,
  onSwipeableWillOpen?: Function,
  onSwipeableWillClose?: Function,
  onFullSwipeLeft?: Function,
  onToggleSwipeLeft?: Function,
  onWillFullSwipeLeft?: Function,
  onFullSwipeRight?: Function,
  onWillFullSwipeRight?: Function,
  onDragStart?: Function,
  renderLeftActions?: (progressAnimatedValue: any, dragAnimatedValue: any) => any,
  renderRightActions?: (progressAnimatedValue: any, dragAnimatedValue: any) => any,
  leftActionsContainerStyle: any,
  rightActionsContainerStyle: any,
  useNativeAnimations: boolean,
  animationOptions?: Object,
  containerStyle?: Object,
  childrenContainerStyle?: Object,
  disableHaptic?: boolean
};

type State = {
  dragX: Animated.Value,
  rowTranslation: Animated.Value,
  leftWidth: number | typeof undefined,
  rightOffset: number | typeof undefined,
  rowWidth: number | typeof undefined
};

export type SwipeableProps = Props;

class Swipeable extends Component<Props, State> {
  static displayName = 'IGNORE';
  static defaultProps = {
    friction: 1,
    overshootFriction: 1,
    useNativeAnimations: true,
    fullLeftThreshold: 0.45,
    fullRightThreshold: 0.45
  };

  // _onGestureEvent: ?Animated.Event;
  // _transX: ?Animated.Interpolation;
  // _showLeftAction: ?Animated.Interpolation | ?Animated.Value;
  // _leftActionTranslate: ?Animated.Interpolation;
  // _showRightAction: ?Animated.Interpolation | ?Animated.Value;
  // _rightActionTranslate: ?Animated.Interpolation;

  constructor(props: Props) {
    super(props);

    const dragX = new Animated.Value(0);
    // 0 -> open from either left/right,
    // 1 -> closing to the left
    // -1 -> closing to the right
    this.rowState = 0;
    this.dragThresholdReached = false;

    this.state = {
      dragX,
      rowTranslation: new Animated.Value(0),
      rowWidth: Constants.screenWidth,
      leftWidth: undefined,
      rightOffset: undefined,
      measureCompleted: false
    };

    this._onGestureEvent = Animated.event([{nativeEvent: {translationX: dragX}}], {
      useNativeDriver: props.useNativeAnimations,
      listener: this._handleDrag
    });
  }

  _triggerHaptic = () => {
    return !this.props.disableHaptic && HapticService.triggerHaptic(HapticType.impactMedium, 'Drawer');
  }

  _handleDrag = (e) => {
    const {onToggleSwipeLeft} = this.props;

    if (onToggleSwipeLeft) {
      // Drag left toggle
      const {rowWidth, leftWidth} = this.state;
      const x = e.nativeEvent.translationX;
      const threshold = rowWidth * LEFT_TOGGLE_THRESHOLD;

      if (!this.dragThresholdReached && x >= threshold && x < threshold + 10) {
        // move item right
        this.dragThresholdReached = true;
        this._triggerHaptic();
        onToggleSwipeLeft({rowWidth, leftWidth, dragX: x});
      }
      if (this.dragThresholdReached && x < threshold - 10) {
        // move item left
        this.dragThresholdReached = false;
        onToggleSwipeLeft({rowWidth, leftWidth, dragX: x, resetItemPosition: true});
      }
    }
  }

  getTransX = () => {
    const {friction, overshootFriction} = this.props;
    const {dragX, rowTranslation, leftWidth = 0, rowWidth = 0} = this.state;
    const {rightOffset = rowWidth} = this.state;
    const rightWidth = Math.max(0, rowWidth - rightOffset);
    const {overshootLeft = leftWidth > 0, overshootRight = rightWidth > 0} = this.props;

    const transX = Animated.add(
      rowTranslation,
      dragX.interpolate({
        inputRange: [0, friction],
        outputRange: [0, 1]
      }),
    ).interpolate({
      inputRange: [
        -rightWidth - (overshootRight ? 1 : overshootFriction),
        -rightWidth,
        leftWidth,
        leftWidth + (overshootLeft ? 1 : overshootFriction)
      ],
      outputRange: [
        -rightWidth - (overshootRight || overshootFriction > 1 ? 1 : 0),
        -rightWidth,
        leftWidth,
        leftWidth + (overshootLeft || overshootFriction > 1 ? 1 : 0)
      ],
    });
    return transX;
  }

  getShowLeftAction = () => {
    const transX = this.getTransX();
    const {leftWidth = 0} = this.state;

    const showLeftAction = leftWidth > 0 ?
      transX.interpolate({
          inputRange: [-1, 0, leftWidth],
          outputRange: [0, 0, 1]
        })
      : new Animated.Value(0);

    return showLeftAction;
  }

  getLeftActionTranslate = () => {
    const showLeftAction = this.getShowLeftAction();

    const leftActionTranslate = showLeftAction.interpolate({
      inputRange: [0, Number.MIN_VALUE],
      outputRange: [-10000, 0],
      extrapolate: 'clamp'
    });

    return leftActionTranslate;
  }

  getShowRightAction = () => {
    const transX = this.getTransX();
    const {rowWidth = 0} = this.state;
    const {rightOffset = rowWidth} = this.state;
    const rightWidth = Math.max(0, rowWidth - rightOffset);

    const showRightAction = rightWidth > 0 ?
      transX.interpolate({
          inputRange: [-rightWidth, 0, 1],
          outputRange: [1, 0, 0]
        })
      : new Animated.Value(0);

    return showRightAction;
  }

  getRightActionTranslate = () => {
    const showRightAction = this.getShowRightAction();

    const rightActionTranslate = showRightAction.interpolate({
      inputRange: [0, Number.MIN_VALUE],
      outputRange: [-10000, 0],
      extrapolate: 'clamp'
    });

    return rightActionTranslate;
  }

  _onTapHandlerStateChange = ({nativeEvent}) => {
    if (this.rowState !== 0) {
      if (nativeEvent.oldState === State.ACTIVE) {
        this.close();
      }
    }
  };

  _onHandlerStateChange = ({nativeEvent}) => {
    if (nativeEvent.oldState === State.ACTIVE) {
      this._handleRelease(nativeEvent);
    }

    if (nativeEvent.state === State.ACTIVE) {
      this.props.onDragStart && this.props.onDragStart(this.props);
    }
  };

  _hasLeftActions = this.props.renderLeftActions !== undefined;

  _hasRightActions = this.props.renderRightActions !== undefined;

  _handleRelease = nativeEvent => {
    const {velocityX, translationX: dragX} = nativeEvent;
    const {leftWidth = 0, rowWidth = 0} = this.state;
    const {rightOffset = rowWidth} = this.state;
    const rightWidth = rowWidth - rightOffset;
    const {
      fullSwipeLeft,
      fullSwipeRight,
      friction,
      leftThreshold = leftWidth / 2,
      rightThreshold = rightWidth / 2,
      fullLeftThreshold,
      fullRightThreshold,
      onToggleSwipeLeft
    } = this.props;
    const startOffsetX = this._currentOffset() + dragX / friction;
    const translationX = (dragX + DRAG_TOSS * velocityX) / friction;

    let toValue = 0;
    if (this.rowState === 0) {
      if (Constants.isRTL && this._hasLeftActions && onToggleSwipeLeft && translationX < -(rowWidth * LEFT_TOGGLE_THRESHOLD) && !this.dragThresholdReached) {
        // Swipe left toggle RTL
        toValue = -(rowWidth * LEFT_TOGGLE_THRESHOLD);
      } else if (this._hasLeftActions && onToggleSwipeLeft && translationX > rowWidth * LEFT_TOGGLE_THRESHOLD && !this.dragThresholdReached) {
        // Swipe left toggle
        toValue = rowWidth * LEFT_TOGGLE_THRESHOLD;
      } else if (!onToggleSwipeLeft && fullSwipeLeft && translationX > rowWidth * fullLeftThreshold) {
        // Full left swipe
        this._triggerHaptic();
        toValue = rowWidth;
      } else if (this._hasRightActions && fullSwipeRight && translationX < -rowWidth * fullRightThreshold) {
        // Full right swipe
        this._triggerHaptic();
        toValue = -rowWidth;
      } else if (this._hasLeftActions && translationX > leftThreshold) {
        // left swipe
        if (!onToggleSwipeLeft || onToggleSwipeLeft && translationX < rowWidth * LEFT_TOGGLE_THRESHOLD) {
          // left swipe with toggle
          toValue = leftWidth;
        }
      } else if (this._hasRightActions && translationX < -rightThreshold) {
        // right swipe
        toValue = -rightWidth;
      }
    } else if (this.rowState === 1) {
      // swiped to the right (left swipe)
      if (translationX > -leftThreshold) {
        toValue = leftWidth;
      }
    } else {
      // swiped to the left (right swipe)
      if (translationX < rightThreshold) {
        toValue = -rightWidth;
      }
    }

    this._animateRow(startOffsetX, toValue, velocityX / friction);
  };

  _animateRow = (fromValue, toValue, velocityX) => {
    const {dragX, rowTranslation, rowWidth, leftWidth} = this.state;
    const {
      useNativeAnimations,
      animationOptions,
      onSwipeableLeftOpen,
      onSwipeableRightOpen,
      onSwipeableClose,
      onSwipeableOpen,
      onSwipeableLeftWillOpen,
      onSwipeableRightWillOpen,
      onSwipeableWillClose,
      onSwipeableWillOpen,
      onFullSwipeLeft,
      onToggleSwipeLeft,
      onWillFullSwipeLeft,
      onFullSwipeRight,
      onWillFullSwipeRight
    } = this.props;

    dragX.setValue(0);
    rowTranslation.setValue(fromValue);
    this.rowState = Math.sign(toValue);

    Animated.spring(rowTranslation, {
      toValue,
      restSpeedThreshold: 1.7,
      restDisplacementThreshold: 0.4,
      velocity: velocityX,
      bounciness: 0,
      useNativeDriver: useNativeAnimations,
      ...animationOptions
    }).start(({finished}) => {
      if (finished) {
        // Final Callbacks
        if (toValue === rowWidth && onFullSwipeLeft) {
          onFullSwipeLeft();
        } else if (toValue === -rowWidth && onFullSwipeRight) {
          onFullSwipeRight();
        } else if (toValue > 0 && onSwipeableLeftOpen) {
          onSwipeableLeftOpen();
        } else if (toValue < 0 && onSwipeableRightOpen) {
          onSwipeableRightOpen();
        }

        if (toValue === 0) {
          onSwipeableClose && onSwipeableClose();
        } else {
          onSwipeableOpen && onSwipeableOpen();
        }
      }
    });

    // Transition Callbacks
    if (Constants.isRTL && this._hasLeftActions && onToggleSwipeLeft && (toValue === -(rowWidth * LEFT_TOGGLE_THRESHOLD) || this.dragThresholdReached)) {
      // left toggle RTL
      onToggleSwipeLeft({rowWidth, leftWidth, released: true, triggerHaptic: !this.dragThresholdReached});
    } else if (this._hasLeftActions && onToggleSwipeLeft && (toValue === rowWidth * LEFT_TOGGLE_THRESHOLD || this.dragThresholdReached)) {
      // left toggle
      onToggleSwipeLeft({rowWidth, leftWidth, released: true, triggerHaptic: !this.dragThresholdReached});
      this.dragThresholdReached = false;
    } else if (toValue === rowWidth && onWillFullSwipeLeft) {
      onWillFullSwipeLeft()
    } else if (toValue === -rowWidth && onWillFullSwipeRight) {
      onWillFullSwipeRight()
    } else if (toValue > 0 && onSwipeableLeftWillOpen) {
      onSwipeableLeftWillOpen();
    } else if (toValue < 0 && onSwipeableRightWillOpen) {
      onSwipeableRightWillOpen();
    }

    if (toValue === 0) {
      onSwipeableWillClose && onSwipeableWillClose();
    } else {
      onSwipeableWillOpen && onSwipeableWillOpen();
    }
  };

  _currentOffset = () => {
    const {leftWidth = 0, rowWidth = 0} = this.state;
    const {rightOffset = rowWidth} = this.state;
    const rightWidth = rowWidth - rightOffset;

    if (this.rowState === 1) {
      return leftWidth;
    } else if (this.rowState === -1) {
      return -rightWidth;
    }
    return 0;
  };

  close = () => {
    this._animateRow(this._currentOffset(), 0);
  };

  openLeft = () => {
    const {leftWidth = 0} = this.state;
    this._animateRow(this._currentOffset(), leftWidth);
  };

  openLeftFull = () => {
    if (this._hasLeftActions) {
      const {rowWidth} = this.state;
      this._animateRow(this._currentOffset(), rowWidth);
    }
  };

  toggleLeft = () => {
    // Programmatically left toggle
    const shouldAnimate = Constants.isRTL ? this._hasRightActions : this._hasLeftActions;
    if (shouldAnimate) {
      const {rowWidth} = this.state;
      this._animateRow(this._currentOffset(), (rowWidth * LEFT_TOGGLE_THRESHOLD) * (Constants.isRTL ? -1 : 1));
    }
  };

  openRight = () => {
    const {rowWidth = 0} = this.state;
    const {rightOffset = rowWidth} = this.state;
    const rightWidth = rowWidth - rightOffset;
    this._animateRow(this._currentOffset(), -rightWidth);
  };

  openRightFull = () => {
    if (this._hasRightActions) {
      const {rowWidth} = this.state;
      this._animateRow(this._currentOffset(), -rowWidth);
    }
  };

  _onRowLayout = ({nativeEvent}) => this.handleMeasure('rowWidth', nativeEvent);
  _onLeftLayout = ({nativeEvent}) => this.handleMeasure('leftWidth', nativeEvent);
  _onRightLayout = ({nativeEvent}) => this.handleMeasure('rightOffset', nativeEvent);

  handleMeasure = (name, nativeEvent) => {
    const {width, x} = nativeEvent.layout;

    switch (name) {
      case 'rowWidth':
        this.rowWidth = width;
        break;
      case 'leftWidth':
        this.leftWidth = x;
        break;
      case 'rightOffset':
        this.rightOffset = x;
        break;
      default:
        break;
    }

    const leftRender = this._hasLeftActions ? this.leftWidth : true;
    const rightRender = this._hasRightActions ? this.rightOffset : true;

    if (this.rowWidth && leftRender && rightRender) {
      this.setState({
        rowWidth: this.rowWidth,
        leftWidth: this.leftWidth,
        rightOffset: this.rightOffset,
        measureCompleted: true
      });
    }
  };

  render() {
    const {
      children,
      renderLeftActions,
      renderRightActions,
      leftActionsContainerStyle,
      rightActionsContainerStyle,
      containerStyle,
      childrenContainerStyle,
      testID
    } = this.props;

    const left = this._hasLeftActions && (
      <Animated.View
        style={[
          styles.leftActions,
          leftActionsContainerStyle,
          {transform: [{translateX: this.getLeftActionTranslate()}]}
        ]}
      >
        {renderLeftActions(this.getShowLeftAction(), this.getTransX())}
        <View onLayout={this._onLeftLayout}/>
      </Animated.View>
    );

    const right = this._hasRightActions && (
      <Animated.View
        style={[
          styles.rightActions,
          rightActionsContainerStyle,
          {transform: [{translateX: this.getRightActionTranslate()}]}
        ]}
      >
        {renderRightActions(this.getShowRightAction(), this.getTransX())}
        <View onLayout={this._onRightLayout}/>
      </Animated.View>
    );

    return (
      <PanGestureHandler
        {...this.props}
        // minDeltaX={10}
        activeOffsetX={[-44, 44]}
        onGestureEvent={this._onGestureEvent}
        onHandlerStateChange={this._onHandlerStateChange}
      >
        <Animated.View onLayout={this._onRowLayout} style={[styles.container, containerStyle]}>
          {left}
          {right}
          <TapGestureHandler onHandlerStateChange={this._onTapHandlerStateChange}>
            <Animated.View
              style={[
                {transform: [{translateX: this.getTransX()}]},
                childrenContainerStyle
              ]}
            >
              {children}
            </Animated.View>
          </TapGestureHandler>
        </Animated.View>
      </PanGestureHandler>
    );
  }
}

export default Swipeable;

const styles = StyleSheet.create({
  container: {
    overflow: 'hidden'
  },
  leftActions: {
    ...StyleSheet.absoluteFillObject,
    flexDirection: I18nManager.isRTL ? 'row-reverse' : 'row'
  },
  rightActions: {
    ...StyleSheet.absoluteFillObject,
    flexDirection: I18nManager.isRTL ? 'row' : 'row-reverse'
  }
});

import _ from 'lodash';
import React, {PureComponent, ReactNode, RefObject} from 'react';
import memoize from 'memoize-one';
import {Animated, Easing, StyleSheet, ViewStyle, TextStyle, AccessibilityActionEvent} from 'react-native';
import {RectButton, GestureHandlerRootView} from 'react-native-gesture-handler';
import {Constants, asBaseComponent} from '../../commons/new';
import {extractAccessibilityProps} from '../../commons/modifiers';
import {Colors} from '../../style';
import View from '../view';
import Swipeable, {SwipeableProps} from './Swipeable';

const DEFAULT_BG = Colors.$backgroundPrimaryHeavy;
const DEFAULT_BOUNCINESS = 0;

interface DrawerItemProps {
  width?: number;
  background?: string;
  text?: string;
  textColor?: string;
  icon?: number;
  iconColor?: string;
  onPress?: Function;
  keepOpen?: boolean;
  style?: ViewStyle;
  testID?: string;
  customElement?: ReactNode;
}

interface DrawerProps {
  /**
   * The drawer animation bounciness
   */
  bounciness?: number;
  /**
   * OnDragStart handler
   */
  onDragStart?: Function;
  /**
   * The bottom layer's items to appear when opened from the right
   */
  rightItems?: DrawerItemProps[];
  /**
   * The bottom layer's item to appear when opened from the left (a single item)
   */
  leftItem?: DrawerItemProps;
  /**
   * Set a different minimum width
   */
  itemsMinWidth?: number;
  /**
   * The color for the text and icon tint of the items
   */
  itemsTintColor?: string;
  /**
   * The items' icon size
   */
  itemsIconSize?: number;
  /**
   * The items' text style
   */
  itemsTextStyle?: TextStyle;
  /**
   * Perform the animation in natively
   */
  useNativeAnimations?: boolean;
  /**
   * Whether to allow a full left swipe
   */
  fullSwipeLeft?: boolean;
  /**
   * Threshold for a left full swipe (0-1)
   */
  fullLeftThreshold?: number;
  /**
   * Callback for left item full swipe
   */
  onFullSwipeLeft?: Function;
  /**
   * Callback for left item toggle swipe
   */
  onToggleSwipeLeft?: Function;
  /**
   * Callback for just before left item full swipe
   */
  onWillFullSwipeLeft?: Function;
  /**
   * Whether to allow a full right swipe
   */
  fullSwipeRight?: boolean;
  /**
   * Threshold for a right full swipe (0-1)
   */
  fullRightThreshold?: number;
  /**
   * Callback for right item full swipe
   */
  onFullSwipeRight?: Function;
  /**
   * Callback for just before right item full swipe
   */
  onWillFullSwipeRight?: Function;
  /**
   * Whether to disable the haptic
   */
  disableHaptic?: boolean;
  /**
   * Style
   */
  style?: ViewStyle;
  /**
   * Callback for open action
   */
  onSwipeableWillOpen?: Function;
  /**
   * Callback for close action
   */
  onSwipeableWillClose?: Function;
  /**
   * Custom value of any type to pass on to the component and receive back in the action callbacks
   */
  customValue?: any;
  /**
   * Used as testing identifier
   */
  testID?: string;
  children?: React.ReactNode;
}

/**
 * @description: Drawer Component
 * @importantLink: https://docs.swmansion.com/react-native-gesture-handler/docs/installation/
 * @gif: https://github.com/wix/react-native-ui-lib/blob/master/demo/showcase/Drawer/Drawer.gif?raw=true
 */
class Drawer extends PureComponent<DrawerProps> {
  static displayName = 'Drawer';

  static defaultProps = {
    itemsTintColor: Colors.white,
    itemsIconSize: 24
  };

  leftRender: SwipeableProps['renderLeftActions'];
  rightRender: SwipeableProps['renderLeftActions'];
  _swipeableRow: RefObject<Swipeable | null> = React.createRef();
  animationOptions: SwipeableProps['animationOptions'] = {bounciness: this.props.bounciness || DEFAULT_BOUNCINESS};
  leftActionX: Animated.Value = new Animated.Value(0);

  constructor(props: DrawerProps) {
    super(props);

    this.leftRender = Constants.isRTL
      ? props.rightItems && this.renderRightActions
      : props.leftItem && this.renderLeftActions;
    this.rightRender = Constants.isRTL
      ? props.leftItem && this.renderLeftActions
      : props.rightItems && this.renderRightActions;
  }

  private getLeftActionsContainerStyle = memoize((leftItem, rightItems) => {
    return this.getActionsContainerStyle(Constants.isRTL ? rightItems : [leftItem]);
  });

  private getRightActionsContainerStyle = memoize((rightItems, leftItem) => {
    return this.getActionsContainerStyle(Constants.isRTL ? [leftItem] : rightItems);
  });

  private getActionsContainerStyle(items: DrawerItemProps[]) {
    return {backgroundColor: _.get(_.first(items), 'background', DEFAULT_BG)};
  }

  /** Actions */

  closeDrawer = () => {
    this._swipeableRow.current?.close();
  };

  openLeft = () => {
    this._swipeableRow.current?.openLeft();
  };

  openLeftFull = () => {
    this._swipeableRow.current?.openLeftFull();
  };

  toggleLeft = () => {
    this._swipeableRow.current?.toggleLeft();
  };

  openRight = () => {
    this._swipeableRow.current?.openRight();
  };

  openRightFull = () => {
    this._swipeableRow.current?.openRightFull();
  };

  /** Events */

  private onActionPress = (item: DrawerItemProps) => {
    if (!item.keepOpen) {
      this.closeDrawer();
    }
    item.onPress?.(this.props);
  };

  private onSwipeableWillOpen = () => {
    this.props.onSwipeableWillOpen?.(this.props);
  };

  private onSwipeableWillClose = () => {
    this.props.onSwipeableWillClose?.(this.props);
  };

  private onToggleSwipeLeft = (options?: any) => {
    if (this.props.onToggleSwipeLeft) {
      this.animateItem(options);
    }
  };

  private animateItem({rowWidth, leftWidth, dragX, released, resetItemPosition}: any) {
    const toValue = resetItemPosition ? 0 : dragX ? dragX - leftWidth : rowWidth * 0.6 - leftWidth;

    Animated.timing(this.leftActionX, {
      toValue,
      easing: Easing.bezier(0.25, 1, 0.5, 1),
      duration: 200,
      delay: 100,
      useNativeDriver: true
    }).start(() => {
      if (released) {
        // reset Drawer
        this.animateItem({released: false, resetItemPosition: true});
        this.closeDrawer();
        setTimeout(() => {
          this.props.onToggleSwipeLeft?.(this.props);
        }, 150);
      }
    });
  }

  /** Accessability */

  private getAccessibilityActions(withOnPress = false) {
    const {rightItems, leftItem} = this.props;
    const actions = [];

    if (leftItem?.onPress && leftItem.text) {
      const action: any = {name: leftItem.text, label: leftItem.text};
      if (withOnPress) {
        action.onPress = leftItem.onPress;
      }
      actions.push(action);
    }
    if (rightItems) {
      rightItems.forEach(item => {
        if (item.onPress && item.text) {
          const action: any = {name: item.text, label: item.text};
          if (withOnPress) {
            action.onPress = item.onPress;
          }
          actions.push(action);
        }
      });
    }

    return actions;
  }

  private onAccessibilityAction = (event: AccessibilityActionEvent) => {
    const actions = this.getAccessibilityActions(true);
    const action = _.find(actions, o => {
      // return o.text === event.nativeEvent.action;
      return o.name === event.nativeEvent.actionName;
    });
    action.onPress?.();
  };

  /** Renders */

  // TODO: enable support for rendering more than one left item
  private renderLeftActions = (progress: Animated.Value /* , dragX: Animated.Value */) => {
    const {leftItem} = this.props;
    const leftItems = leftItem ? [leftItem] : undefined;
    return this.renderActions(leftItems, progress /* , dragX */);
  };

  private renderRightActions = (progress: Animated.Value /* , dragX: Animated.Value */) => {
    const {rightItems} = this.props;
    return this.renderActions(rightItems, progress /* , dragX */);
  };

  private renderActions(items: DrawerItemProps[] | undefined, progress: Animated.Value /* , dragX: Animated.Value */) {
    if (items) {
      return (
        // @ts-ignore
        <View animated renderDelay={100} row style={{transform: [{translateX: this.leftActionX}]}}>
          {_.map(items, (item, index: number) => {
            return this.renderAction({
              item,
              index: items.length - index - 1,
              progress,
              // dragX,
              itemsCount: items.length
            });
          })}
        </View>
      );
    }
  }

  private renderAction = ({item, index, progress, itemsCount}: any) => {
    const {itemsTintColor, itemsIconSize, itemsTextStyle, itemsMinWidth} = this.props;
    const inputRange = [index / itemsCount, (index + 1) / itemsCount];
    const outputRange = [0.2, 1];

    const scale = progress.interpolate({
      inputRange,
      outputRange,
      extrapolate: 'clamp'
    });

    const opacity = progress.interpolate({
      inputRange,
      outputRange,
      extrapolate: 'clamp'
    });

    return (
      <RectButton key={index} testID={item.testID} onPress={() => this.onActionPress(item)}>
        <View
          style={[
            styles.action,
            item.style,
            {
              backgroundColor: item.background || DEFAULT_BG,
              height: '100%',
              width: item.width,
              minWidth: itemsMinWidth
            }
          ]}
        >
          {item.customElement}
          {!item.customElement && item.icon && (
            <Animated.Image
              source={item.icon}
              style={[
                styles.actionIcon,
                {
                  width: itemsIconSize,
                  height: itemsIconSize,
                  tintColor: item.iconColor || itemsTintColor,
                  opacity,
                  transform: [{scale}]
                }
              ]}
            />
          )}
          {!item.customElement && item.text && (
            <Animated.Text
              style={[
                styles.actionText,
                {
                  color: item.textColor || itemsTintColor,
                  opacity,
                  transform: [{scale}]
                },
                itemsTextStyle
              ]}
              accessibilityElementsHidden
              importantForAccessibility="no-hide-descendants"
              accessible={false}
            >
              {item.text}
            </Animated.Text>
          )}
        </View>
      </RectButton>
    );
  };

  render() {
    const {children, style, leftItem, rightItems, onToggleSwipeLeft, ...others} = this.props;

    return (
      <GestureHandlerRootView style={styles.container}>
        <Swipeable
          {...others}
          ref={this._swipeableRow}
          friction={1}
          containerStyle={style}
          animationOptions={this.animationOptions}
          renderLeftActions={this.leftRender}
          renderRightActions={this.rightRender}
          rightActionsContainerStyle={this.getRightActionsContainerStyle(rightItems, leftItem)}
          leftActionsContainerStyle={this.getLeftActionsContainerStyle(leftItem, rightItems)}
          onSwipeableWillOpen={this.onSwipeableWillOpen}
          onSwipeableWillClose={this.onSwipeableWillClose}
          onToggleSwipeLeft={onToggleSwipeLeft && this.onToggleSwipeLeft}
        >
          <View
            accessible
            accessibilityActions={this.getAccessibilityActions()}
            onAccessibilityAction={this.onAccessibilityAction}
            {...extractAccessibilityProps(this.props)}
          >
            {children}
          </View>
        </Swipeable>
      </GestureHandlerRootView>
    );
  }
}

export {DrawerProps, DrawerItemProps};
export default asBaseComponent<DrawerProps, typeof Drawer>(Drawer);

const styles = StyleSheet.create({
  container: {
    flex: 0
  },
  leftAction: {
    flex: 1,
    justifyContent: 'center',
    alignItems: /* Constants.isRTL ? 'flex-end' :  */ 'flex-start',
    backgroundColor: '#388e3c'
  },
  actionIcon: {
    width: 30,
    marginHorizontal: 10
  },
  actionText: {
    color: '#ffffff'
  },
  action: {
    paddingHorizontal: 12,
    justifyContent: 'center',
    alignItems: 'center',
    backgroundColor: '#dd2c00'
  }
});

import React, {useCallback, useMemo, useState, type JSX} from 'react';
import {LayoutChangeEvent, StyleSheet} from 'react-native';
import {useAnimatedStyle, useSharedValue, withTiming} from 'react-native-reanimated';
import {useDidUpdate} from '../../hooks';
import View from '../view';
import TouchableOpacity from '../touchableOpacity';

export type ExpandableSectionProps = {
  /**
   * expandableSection header element
   */
  sectionHeader?: JSX.Element;
  /**
   * expandableSection expandable children
   */
  children?: React.ReactNode;
  /**
   * should the expandableSection be expanded
   */
  expanded?: boolean;
  /**
   * should the expandableSection open above the sectionHeader
   */
  top?: boolean;
  /**
   * action for when pressing the header of the expandableSection
   */
  onPress?: () => void;
  /**
   * Set a minimum height for the expandableSection
   * If the children height is less than the minHeight, the expandableSection will collapse to that height
   * If the children height is greater than the minHeight, the expandableSection will result with only the children rendered (sectionHeader will not be rendered)
   */
  minHeight?: number;
  /**
   * Testing identifier
   */
  testID?: string;
};

/**
 * @description: ExpandableSection component to render expanded section below or above the sectionHeader
 * @example: https://github.com/wix/react-native-ui-lib/blob/master/demo/src/screens/componentScreens/ExpandableSectionScreen.tsx
 * @gif: https://github.com/wix/react-native-ui-lib/blob/master/demo/showcase/ExpandableSection/ExpandableSection.gif?raw=true
 */

function ExpandableSection(props: ExpandableSectionProps) {
  const {minHeight, expanded, sectionHeader, onPress, children, top, testID} = props;
  const [height, setHeight] = useState(0);
  const animatedHeight = useSharedValue(0);
  const shouldShowSectionHeader = !minHeight || height > minHeight;

  const onLayout = (event: LayoutChangeEvent) => {
    const layoutHeight = event.nativeEvent.layout.height;

    if (layoutHeight > 0 && height !== layoutHeight) {
      setHeight(layoutHeight);
    }
  };

  const animateHeight = useCallback((shouldAnimate = true) => {
    const collapsedHeight = Math.min(minHeight ?? 0, height);
    const toValue = expanded ? height : collapsedHeight;
    animatedHeight.value = shouldAnimate ? withTiming(toValue) : toValue;
  },
  [animatedHeight, expanded, height, minHeight]);

  useDidUpdate(() => {
    animateHeight(false);
  }, [height, minHeight]);

  useDidUpdate(() => {
    animateHeight();
  }, [expanded]);

  const expandableStyle = useAnimatedStyle(() => {
    return {
      height: animatedHeight.value
    };
  }, []);

  const style = useMemo(() => [styles.hidden, expandableStyle], [expandableStyle]);

  const accessibilityState = useMemo(() => {
    return {expanded};
  }, [expanded]);

  const renderChildren = () => {
    return (
      <View reanimated style={style}>
        <View absH onLayout={onLayout}>
          {children}
        </View>
      </View>
    );
  };

  const Container = onPress ? TouchableOpacity : View;

  if (shouldShowSectionHeader) {
    return (
      <View style={styles.hidden}>
        {top && renderChildren()}
        <Container onPress={onPress} testID={testID} accessibilityState={accessibilityState}>
          {sectionHeader}
        </Container>
        {!top && renderChildren()}
      </View>
    );
  } else {
    return renderChildren();
  }
}

export default ExpandableSection;

const styles = StyleSheet.create({
  hidden: {
    overflow: 'hidden'
  }
});

import React, {useCallback, useRef, useImperativeHandle} from 'react';
import {
  ScrollView as RNScrollView,
  ScrollViewProps,
  StyleSheet,
  NativeSyntheticEvent,
  NativeScrollEvent,
  LayoutChangeEvent
} from 'react-native';
import {ScrollView as GestureScrollView, GestureHandlerRootView} from 'react-native-gesture-handler';
import Fader, {FaderProps} from '../fader';
import useScrollEnabler from '../../hooks/useScrollEnabler';
import useScrollReached from '../../hooks/useScrollReached';
import {forwardRef, ForwardRefInjectedProps} from '../../commons/new';
import {ComponentStatics} from '../../typings/common';

export type FadedScrollViewProps = ScrollViewProps & {
  /**
   * Show a fader at the start of the scroll
   */
  showStartFader?: boolean;
  /**
   * Additional props for the start fader
   */
  startFaderProps?: Omit<FaderProps, 'visible' | 'position'>;
  /**
   * Show a fader at the end of the scroll
   */
  showEndFader?: boolean;
  /**
   * Additional props for the end fader
   */
  endFaderProps?: Omit<FaderProps, 'visible' | 'position'>;
  /**
   * Use the react-native-gesture-handler version, useful when using react-native-reanimated
   */
  useGesture?: boolean;
  children?: React.ReactNode | React.ReactNode[];
};

type Props = FadedScrollViewProps & ForwardRefInjectedProps;
export interface FadedScrollViewRef {
  scrollTo(
    y?: number | {x?: number | undefined; y?: number | undefined; animated?: boolean | undefined},
    x?: number,
    animated?: boolean
  ): void;
  isScrollEnabled: () => boolean;
}

const FadedScrollView = (props: Props) => {
  const {
    children,
    onScroll: propsOnScroll,
    onContentSizeChange: propsOnContentSizeChange,
    onLayout: propsOnLayout,
    horizontal: propsHorizontal,
    showStartFader,
    startFaderProps,
    showEndFader,
    endFaderProps,
    useGesture,
    ...others
  } = props;
  const ScrollView = useGesture ? GestureScrollView : RNScrollView;
  const scrollViewRef = useRef<typeof ScrollView>(undefined);
  const horizontal = propsHorizontal ?? false;
  const {onContentSizeChange, onLayout, scrollEnabled} = useScrollEnabler({horizontal});
  const {
    onScroll: onScrollReached,
    isScrollAtStart,
    isScrollAtEnd
  } = useScrollReached({
    horizontal,
    threshold: 50
  });

  const showStart = (showStartFader && scrollEnabled && !isScrollAtStart) ?? false;
  const showEnd = (showEndFader && scrollEnabled && !isScrollAtEnd) ?? false;

  const onScroll = useCallback((event: NativeSyntheticEvent<NativeScrollEvent>) => {
    onScrollReached(event);
    propsOnScroll?.(event);
  },
  [onScrollReached, propsOnScroll]);

  const _onContentSizeChange = useCallback((w: number, h: number) => {
    propsOnContentSizeChange?.(w, h);
    onContentSizeChange?.(w, h);
  },
  [propsOnContentSizeChange, onContentSizeChange]);

  const _onLayout = useCallback((event: LayoutChangeEvent) => {
    propsOnLayout?.(event);
    onLayout?.(event);
  },
  [propsOnLayout, onLayout]);

  const isScrollEnabled = () => {
    return scrollEnabled;
  };

  useImperativeHandle(props.forwardedRef, () => ({
    // @ts-expect-error
    scrollTo: (...data: any) => scrollViewRef.current?.scrollTo?.(...data),
    isScrollEnabled
  }));

  if (children) {
    return (
      <GestureHandlerRootView style={styles.container}>
        <ScrollView
          scrollEventThrottle={16}
          decelerationRate={'fast'}
          {...others}
          horizontal={horizontal}
          scrollEnabled={scrollEnabled}
          onContentSizeChange={_onContentSizeChange}
          onLayout={_onLayout}
          onScroll={onScroll}
          // @ts-expect-error
          ref={scrollViewRef}
        >
          {children}
        </ScrollView>
        <Fader
          visible={showStart}
          position={horizontal ? Fader.position.START : Fader.position.TOP}
          {...startFaderProps}
        />
        <Fader
          visible={showEnd}
          position={horizontal ? Fader.position.END : Fader.position.BOTTOM}
          {...endFaderProps}
        />
      </GestureHandlerRootView>
    );
  }

  return null;
};

const styles = StyleSheet.create({
  container: {
    flex: 0
  }
});

FadedScrollView.displayName = 'IGNORE';
export default forwardRef<FadedScrollViewProps, ComponentStatics<FadedScrollViewProps>, FadedScrollViewRef>(FadedScrollView);

import _ from 'lodash';
import React, {useMemo} from 'react';
import {StyleSheet, StyleProp, ImageStyle} from 'react-native';
import View from '../view';
import Image, {ImageProps} from '../image';
import {Colors} from 'style';

export enum FaderPosition {
  START = 'START',
  END = 'END',
  TOP = 'TOP',
  BOTTOM = 'BOTTOM'
}

export type FaderProps = Pick<ImageProps, 'supportRTL'> & {
  /**
   * Whether the fader is visible (default is true)
   */
  visible?: boolean;
  /**
   * The position of the fader (the image is different), defaults to Fader.position.END
   */
  position?: FaderPosition | `${FaderPosition}`;
  /**
   * Set to change from the default size (50) of the fade view.
   */
  size?: number;
  /**
   * Change the default tint color of the fade view.
   */
  tintColor?: string;
};

const DEFAULT_FADE_SIZE = 50;

/**
 * @description: A gradient fading overlay to render on top of overflowing content (like scroll component)
 * @example: https://github.com/wix/react-native-ui-lib/blob/master/demo/src/screens/componentScreens/FaderScreen.tsx
 * @gif: https://github.com/wix/react-native-ui-lib/blob/master/demo/showcase/Fader/Fader.gif?raw=true
 */
function Fader(props: FaderProps) {
  const {
    size = DEFAULT_FADE_SIZE,
    position = FaderPosition.END,
    visible,
    tintColor = Colors.$backgroundDefault
  } = props;

  const styles = useMemo(() => {
    let containerStyle, imageStyle: StyleProp<ImageStyle>, imageSource;
    switch (position) {
      case FaderPosition.START:
        containerStyle = {...staticStyles.containerLeft, width: size};
        imageStyle = {height: '100%', width: size};
        imageSource = require('./gradientLeft.png');
        break;
      case FaderPosition.END:
        containerStyle = {...staticStyles.containerRight, width: size};
        imageStyle = {height: '100%', width: size};
        imageSource = require('./gradientRight.png');
        break;
      case FaderPosition.TOP:
        containerStyle = {...staticStyles.containerTop, height: size};
        imageStyle = {height: size, width: '100%'};
        imageSource = require('./gradientTop.png');
        break;
      case FaderPosition.BOTTOM:
        containerStyle = {
          ...staticStyles.containerBottom,
          height: size
        };
        imageStyle = {height: size, width: '100%'};
        imageSource = require('./gradientBottom.png');
        break;
    }

    return {
      containerStyle,
      imageStyle,
      imageSource
    };
  }, [size, position]);

  return (
    <View pointerEvents={'none'} style={styles.containerStyle}>
      {(visible || _.isUndefined(visible)) && (
        <Image
          supportRTL
          source={styles.imageSource}
          tintColor={tintColor}
          style={styles.imageStyle}
          resizeMode={'stretch'}
        />
      )}
    </View>
  );
}

Fader.displayName = 'Fader';
Fader.position = FaderPosition;

export default Fader;

