import React, {Component, ElementRef} from 'react';
import {
  StyleSheet,
  findNodeHandle,
  TouchableWithoutFeedback,
  Animated,
  AccessibilityInfo,
  StyleProp,
  TextStyle,
  TouchableWithoutFeedbackProps,
  LayoutChangeEvent
} from 'react-native';
import {HighlighterOverlayView} from 'uilib-native';
import {Colors, Typography} from '../../style';
import {Constants, asBaseComponent} from '../../commons/new';
import View from '../view';
import Text from '../text';
import Button, {ButtonProps, ButtonSize} from '../button';
import PageControl, {PageControlProps} from '../pageControl';

const defaultOverlayColor = Colors.rgba(Colors.black, 0.82);
const defaultTextColor = Colors.white;
const defaultStrokeColor = Colors.rgba(Colors.white, 0.12);
const defaultStrokeWidth = 12;
const contentViewPadding = 32;
const contentViewRightMargin = Constants.isIOS ? 45 : 46;
const titleBottomMargin = 12;
const messageBottomMargin = 24;
const messageLineHeight = 24;
const defaultButtonLabel = 'Got it';
const contentViewHeight = Constants.isAndroid ? 268 : 282;

export type HighlightFrame = {
  x: number;
  y: number;
  width: number;
  height: number;
};

type RectSize = {
  width: number;
  height: number;
};

type Position = {
  left: number;
  top: number;
  width: number;
  height: number;
};

export type FeatureHighlightProps = {
  /**
   * Boolean to determine if to present the feature highlight component
   */
  visible: boolean;
  /**
   * Frame of the area to highlight {x, y, width, height}
   */
  highlightFrame?: HighlightFrame;
  /**
   * Callback that extract the ref of the element to be highlighted
   */
  getTarget?: () => any;
  /**
   * Title of the content to be displayed
   */
  title?: string;
  /**
   * Message to be displayed
   */
  message?: string;
  /**
   * Title text style
   */
  titleStyle?: StyleProp<TextStyle>;
  /**
   * Message text style
   */
  messageStyle?: StyleProp<TextStyle>;
  /**
   * Title's max number of lines
   */
  titleNumberOfLines?: number;
  /**
   * Message's max number of lines
   */
  messageNumberOfLines?: number;
  /**
   * Props that will be passed to the dismiss button
   */
  confirmButtonProps?: ButtonProps;
  /**
   * Callback for the background press
   */
  onBackgroundPress?: TouchableWithoutFeedbackProps['onPress'];
  /**
   * Color of the content's background (usually includes alpha for transparency)
   */
  overlayColor?: string;
  /**
   * Color of the content's text
   */
  textColor?: string;
  /**
   * Color of the border around the highlighted element
   */
  borderColor?: string;
  /**
   * Width of the border around the highlighted element
   */
  borderWidth?: number;
  /**
   * Border radius for the border corners around the highlighted element
   */
  borderRadius?: number;
  /**
   * The minimum size of the highlighted component (Android API 21+, and only when passing a ref in 'getTarget')
   */
  minimumRectSize?: RectSize;
  /**
   * The padding of the highlight frame around the highlighted element's frame (only when passing ref in 'getTarget')
   */
  innerPadding?: number;
  /**
   * PageControl component's props
   */
  pageControlProps?: PageControlProps;

  testID?: string;
};

interface State {
  fadeAnim: Animated.Value;
  contentTopPosition?: number;
  node?: number;
  getTarget?: () => any;
}

/*eslint-disable*/
/**
 * @description: FeatureHighlight component for feature discovery
 * @notes: 1) FeatureHighlight component must be a direct child of the root view returned in render().; 2) If the element to be highlighted doesn't have a style attribute add 'style={{opacity: 1}}' so the Android OS can detect it.
 * @important: FeatureHighlight uses a native library. You MUST add and link the native library to both iOS and Android projects. For instruction please see
 * @importantLink: https://facebook.github.io/react-native/docs/linking-libraries-ios.html
 * @gif: https://github.com/wix/react-native-ui-lib/blob/master/demo/showcase/FeatureHighlight/FeatureHighlight.gif?raw=true
 * @example: https://github.com/wix/react-native-ui-lib/blob/master/demo/src/screens/componentScreens/FeatureHighlightScreen.tsx
 */
/*eslint-enable*/
class FeatureHighlight extends Component<FeatureHighlightProps, State> {
  static displayName = 'FeatureHighlight';

  contentHeight = contentViewHeight;
  targetPosition?: Position;
  viewRef?: ElementRef<any>;

  constructor(props: FeatureHighlightProps) {
    super(props);

    this.getComponentDimensions = this.getComponentDimensions.bind(this);
    this.setTargetPosition = this.setTargetPosition.bind(this);

    this.state = {
      fadeAnim: new Animated.Value(0), // Initial value for opacity: 0
      contentTopPosition: undefined
    };
  }

  static defaultProps = {
    minimumRectSize: {width: 56, height: 56},
    innerPadding: 10
  };

  componentDidMount() {
    this.setTargetPosition();
  }

  static getDerivedStateFromProps(nextProps: FeatureHighlightProps, prevState: State) {
    if (prevState?.getTarget === nextProps?.getTarget) {
      return null;
    }

    const target = nextProps?.getTarget?.();
    const node = FeatureHighlight.findTargetNode(target);
    if (node && node !== prevState?.node) {
      return {getTarget: nextProps?.getTarget, node};
    }
    return null;
  }

  shouldSetTargetPosition = (nextProps: FeatureHighlightProps) => {
    return (
      nextProps.getTarget?.() !== this.props.getTarget?.() ||
      nextProps.title !== this.props.title ||
      nextProps.visible !== this.props.visible
    );
  };

  componentDidUpdate(nextProps: FeatureHighlightProps) {
    if (this.shouldSetTargetPosition(nextProps)) {
      this.setTargetPosition();
    }
    if (this.viewRef) {
      this.setAccessibilityFocus(this.viewRef);
    }
  }

  setAccessibilityFocus(ref: any) {
    const reactTag = findNodeHandle(ref);
    reactTag && AccessibilityInfo.setAccessibilityFocus(reactTag);
  }

  static findTargetNode(target: Component) {
    return findNodeHandle(target);
  }

  animate(toValue: number) {
    Animated.timing(
      // Animate over time
      this.state.fadeAnim, // The animated value to drive
      {
        toValue, // Animate to value
        duration: toValue ? 100 : 0, // Make it take a while
        useNativeDriver: true
      }
    ).start(); // Starts the animation
  }

  setTargetPosition(props = this.props) {
    if (props.getTarget !== undefined) {
      const target = props.getTarget();
      if (target) {
        setTimeout(() => {
          target.measureInWindow((x: number, y: number, width: number, height: number) => {
            this.targetPosition = {left: x, top: y, width, height};
            this.setContentPosition();
          });
        }, 0);
      }
    } else {
      const frame = props.highlightFrame;
      if (frame) {
        this.targetPosition = {left: frame.x, top: frame.y, width: frame.width, height: frame.height};
        this.setContentPosition();
      }
    }
  }

  getContentPosition() {
    const {highlightFrame, minimumRectSize = {height: 0}, innerPadding = 0} = this.props;
    const {top, height} = this.targetPosition || {top: 0, height: 0};
    const screenVerticalCenter = Constants.screenHeight / 2;
    const targetCenter = top + height / 2;
    const isAlignedTop = targetCenter > screenVerticalCenter;
    let topPosition = isAlignedTop ? top - this.contentHeight : top + height;
    if (!highlightFrame && !isAlignedTop) {
      const minRectHeight = minimumRectSize.height;
      const isUnderMin = height >= minRectHeight;
      topPosition = isUnderMin ? topPosition + innerPadding : targetCenter + minRectHeight / 2 + innerPadding / 2;
    }
    if (topPosition < 0 || topPosition + this.contentHeight > Constants.screenHeight) {
      console.warn(
        `Content is too long and might appear off screen. Please adjust the message length for better results.`
      );
    }
    return topPosition;
  }

  setContentPosition() {
    const top = this.getContentPosition();
    this.setState({contentTopPosition: top});
    this.animate(1);
  }

  // This method will be called more than once in case of layout change!
  getComponentDimensions(event: LayoutChangeEvent) {
    this.contentHeight = event.nativeEvent.layout.height;
    if (this.targetPosition !== undefined) {
      this.setContentPosition();
    }
  }

  onPress = () => {
    this.animate(0);
    this.contentHeight = contentViewHeight;
    this.targetPosition = undefined;
    const {confirmButtonProps} = this.props;
    confirmButtonProps?.onPress?.();
  };

  renderHighlightMessage() {
    const {
      title,
      message,
      titleStyle,
      messageStyle,
      confirmButtonProps,
      textColor,
      titleNumberOfLines,
      messageNumberOfLines,
      pageControlProps
    } = this.props;
    const color = textColor || defaultTextColor;

    return (
      <Animated.View
        style={[styles.highlightContent, {opacity: this.state.fadeAnim, top: this.state.contentTopPosition}]}
        onLayout={this.getComponentDimensions}
        pointerEvents="box-none"
        ref={
          !pageControlProps
            ? (r: ElementRef<any>) => {
              this.viewRef = r;
            }
            : undefined
        }
      >
        {title && (
          <Text
            text60
            style={[
              styles.title,
              {
                color,
                marginBottom: message ? titleBottomMargin : messageBottomMargin
              },
              titleStyle
            ]}
            numberOfLines={titleNumberOfLines}
            pointerEvents={'none'}
          >
            {title}
          </Text>
        )}
        {message && (
          <Text
            text70
            style={[styles.message, {color}, messageStyle]}
            numberOfLines={messageNumberOfLines}
            pointerEvents={'none'}
          >
            {message}
          </Text>
        )}
        <Button
          label={defaultButtonLabel}
          size={ButtonSize.medium}
          labelStyle={{...Typography.text80, fontWeight: '700'}}
          outline
          outlineColor={color}
          activeBackgroundColor={Colors.rgba(color, 0.3)}
          {...confirmButtonProps}
          onPress={this.onPress}
        />
      </Animated.View>
    );
  }

  render() {
    const {node, contentTopPosition} = this.state;
    if (contentTopPosition === undefined) {
      return null;
    }

    const {
      testID,
      visible,
      highlightFrame,
      overlayColor,
      borderColor,
      borderWidth,
      minimumRectSize,
      innerPadding,
      onBackgroundPress,
      borderRadius,
      pageControlProps
    } = this.props;

    return (
      <HighlighterOverlayView
        testID={testID}
        highlightViewTag={node}
        highlightFrame={highlightFrame}
        visible={visible}
        overlayColor={overlayColor || defaultOverlayColor}
        strokeColor={borderColor || defaultStrokeColor}
        strokeWidth={borderWidth || defaultStrokeWidth}
        minimumRectSize={minimumRectSize}
        innerPadding={innerPadding}
        borderRadius={borderRadius}
        accessible={false}
      >
        <TouchableWithoutFeedback style={styles.touchableOverlay} onPress={onBackgroundPress}>
          {pageControlProps ? (
            <View flex bottom>
              <PageControl
                {...pageControlProps}
                containerStyle={{marginBottom: 24}}
                ref={(r: ElementRef<any>) => {
                  (this.viewRef = r);
                }}
              />
              <View accessible accessibilityLabel={'dismiss button'}/>
            </View>
          ) : (
            <View flex accessible accessibilityLabel={'dismiss'} accessibilityRole={'button'}/>
          )}
        </TouchableWithoutFeedback>
        {this.renderHighlightMessage()}
      </HighlighterOverlayView>
    );
  }
}

const styles = StyleSheet.create({
  highlightContent: {
    position: 'absolute',
    padding: contentViewPadding,
    marginRight: contentViewRightMargin,
    alignItems: 'flex-start'
  },
  title: {
    lineHeight: Typography.text60?.lineHeight,
    fontWeight: '900'
  },
  message: {
    marginBottom: messageBottomMargin,
    ...Typography.text70,
    lineHeight: messageLineHeight
  },
  touchableOverlay: {
    ...StyleSheet.absoluteFillObject
  }
});
export {FeatureHighlight}; // for tests
//@ts-ignore typescript - will be fixed when moved to functional component
export default asBaseComponent<FeatureHighlightProps, typeof FeatureHighlight>(FeatureHighlight);

import React, {PropsWithChildren, useEffect, useMemo} from 'react';
import {StyleSheet} from 'react-native';
import {asBaseComponent, Constants} from '../../commons/new';
import {LogService} from '../../services';
import {Colors, Shadows, Spacings} from '../../style';
import Button, {ButtonProps} from '../button';
import ScreenFooter, {ScreenFooterProps, ScreenFooterLayouts, ScreenFooterBackgrounds, KeyboardBehavior, ItemsFit} from '../screenFooter';

export enum FloatingButtonLayouts {
  VERTICAL = 'Vertical',
  HORIZONTAL = 'Horizontal'
}

export interface FloatingButtonProps extends Pick<ScreenFooterProps, 'isAndroidEdgeToEdge' | 'animationType'> {
  /**
   * Whether the button is visible
   */
  visible?: boolean;
  /**
   * Button element (all Button's component's props)
   */
  button?: PropsWithChildren<ButtonProps>;
  /**
   * Secondary button element (all Button's component's props)
   */
  secondaryButton?: PropsWithChildren<ButtonProps>;
  /**
   * The bottom margin of the button, or secondary button if passed
   */
  bottomMargin?: number;
  /**
   * Whether the buttons get the container's full width (vertical layout only)
   */
  fullWidth?: boolean;
  /**
   * Button layout direction: vertical or horizontal
   */
  buttonLayout?: FloatingButtonLayouts | `${FloatingButtonLayouts}`;
  /**
   * The duration of the button's animations (show/hide)
   */
  duration?: number;
  /**
   * Whether to show/hide the button without animation
   */
  withoutAnimation?: boolean;
  /**
   * Whether to show background overlay
   */
  hideBackgroundOverlay?: boolean;
  /**
   * Whether the footer should be hoisted above the keyboard.
   * When true (default), uses KeyboardAccessoryView for keyboard-aware positioning.
   * When false, uses sticky positioning.
   */
  hoisted?: boolean;
  /**
   * Used as testing identifier
   * <TestID> - the floatingButton container
   * <TestID>.button - the floatingButton main button
   * <TestID>.secondaryButton - the floatingButton secondaryButton
   */
  testID?: string;
}

/**
 * @description: Hovering button with gradient background, backed by ScreenFooter
 * @modifiers: margin, background, color
 * @example: https://github.com/wix/react-native-ui-lib/blob/master/demo/src/screens/componentScreens/FloatingButtonScreen.tsx
 * @gif: https://github.com/wix/react-native-ui-lib/blob/master/demo/showcase/FloatingButton/FloatingButton.gif?raw=true
 */
const FloatingButton = (props: FloatingButtonProps) => {
  const {
    visible = false,
    button,
    secondaryButton,
    bottomMargin,
    fullWidth,
    buttonLayout = FloatingButtonLayouts.VERTICAL,
    duration = 300,
    withoutAnimation,
    hideBackgroundOverlay,
    hoisted = Constants.isAndroid,
    isAndroidEdgeToEdge,
    animationType,
    testID
  } = props;

  useEffect(() => {
    // eslint-disable-next-line max-len
    LogService.warn(
      'RNUILib FloatingButton now uses ScreenFooter internally, which requires a SafeAreaProvider. If you experience safe area issues, please wrap your app (or the relevant screen) with <SafeAreaProvider>.'
    );
  }, []);

  const isSecondaryOnly = !!secondaryButton && !button;
  const isHorizontal = buttonLayout === FloatingButtonLayouts.HORIZONTAL || isSecondaryOnly;

  const footerContentContainerStyle = useMemo(() => {
    if (bottomMargin !== undefined) {
      return {paddingBottom: bottomMargin};
    }
    const isSecondaryAtBottom = !!secondaryButton && (isSecondaryOnly || !isHorizontal);
    return {paddingBottom: isSecondaryAtBottom ? Spacings.s7 : Spacings.s8};
  }, [bottomMargin, secondaryButton, isSecondaryOnly, isHorizontal]);

  if (!button && !secondaryButton) {
    return null;
  }

  const renderPrimaryButton = () => {
    if (!button) {
      return null;
    }

    const shadowStyle = !button.outline && !button.link ? styles.shadow : undefined;
    const shouldFlex = (isHorizontal && !!secondaryButton) || (fullWidth && isHorizontal);

    return (
      <Button
        key="primary"
        size={Button.sizes.large}
        flex={!!shouldFlex}
        style={shadowStyle}
        testID={testID ? `${testID}.button` : undefined}
        {...button}
      />
    );
  };

  const renderSecondaryButton = () => {
    if (!secondaryButton) {
      return null;
    }

    const shouldFlex = (isHorizontal && !!button) || (fullWidth && isSecondaryOnly);
    const bgColor = secondaryButton.backgroundColor || Colors.$backgroundDefault;

    return (
      <Button
        key="secondary"
        outline={isHorizontal}
        link={!isHorizontal}
        flex={shouldFlex}
        size={Button.sizes.large}
        testID={testID ? `${testID}.secondaryButton` : undefined}
        {...secondaryButton}
        style={isHorizontal ? [styles.shadow, {backgroundColor: bgColor}] : undefined}
        enableShadow={false}
      />
    );
  };

  const children = isHorizontal
    ? [renderSecondaryButton(), renderPrimaryButton()]
    : [renderPrimaryButton(), renderSecondaryButton()];

  return (
    <ScreenFooter
      visible={visible}
      layout={isHorizontal ? ScreenFooterLayouts.HORIZONTAL : ScreenFooterLayouts.VERTICAL}
      backgroundType={hideBackgroundOverlay ? ScreenFooterBackgrounds.TRANSPARENT : ScreenFooterBackgrounds.FADING}
      keyboardBehavior={hoisted ? KeyboardBehavior.HOISTED : KeyboardBehavior.STICKY}
      isAndroidEdgeToEdge={isAndroidEdgeToEdge}
      animationDuration={withoutAnimation ? 0 : duration}
      animationType={animationType}
      itemsFit={fullWidth ? ItemsFit.STRETCH : undefined}
      contentContainerStyle={footerContentContainerStyle}
      testID={testID}
    >
      {children}
    </ScreenFooter>
  );
};

FloatingButton.displayName = 'FloatingButton';
FloatingButton.floatingButtonLayouts = FloatingButtonLayouts;

const styles = StyleSheet.create({
  shadow: {
    ...Shadows.sh20.bottom
  }
});

export default asBaseComponent<FloatingButtonProps, typeof FloatingButton>(FloatingButton);

import isString from 'lodash/isString';
import tinycolor from 'tinycolor2';
import React, {useCallback, useMemo} from 'react';
import {StyleSheet, StyleProp, ViewStyle} from 'react-native';
import {Colors} from '../../style';
import View from '../view';

export enum GradientTypes {
  HUE = 'hue',
  LIGHTNESS = 'lightness',
  SATURATION = 'saturation'
}

export interface GradientProps {
  color?: string | tinycolor.ColorFormats.HSLA;
  type?: GradientTypes | `${GradientTypes}`;
  numberOfSteps: number;
  style?: StyleProp<ViewStyle>;
}

const Gradient = (props: GradientProps) => {
  const {color = Colors.white, type, style, numberOfSteps} = props;

  const getBackgroundColor = useCallback((index: number) => {
    const hslColor = isString(color) ? Colors.getHSL(color) : color;
    const maximum = (type === GradientTypes.HUE) ? 359 : 1;
    const i = index * maximum / numberOfSteps;

    switch (type) {
      case GradientTypes.HUE: 
        return tinycolor({s: 1, l: 0.5, h: i}).toHslString();
      case GradientTypes.LIGHTNESS:
        return tinycolor({...hslColor, l: i}).toHslString();
      case GradientTypes.SATURATION:
        return tinycolor({...hslColor, s: i}).toHslString();
      default:
        return tinycolor({...hslColor, a: i}).toHslString();
    }
  }, [color, numberOfSteps, type]);

  const getStyle = useCallback((index: number) => {
    return {
      flex: 1,
      marginLeft: -StyleSheet.hairlineWidth,
      backgroundColor: getBackgroundColor(index)
    };
  }, [getBackgroundColor]);

  const rows = useMemo(() => {
    const array = [];
    for (let i = 0; i <= numberOfSteps; i++) {
      array.push(<View key={i} style={getStyle(i)}/>);
    }
    return array;
  }, [numberOfSteps, getStyle]);

  const containerStyle = useMemo(() => {
    return [styles.container, style];
  }, [style]);

  return <View style={containerStyle}>{rows}</View>;
};

export default Gradient;
Gradient.types = GradientTypes;

const styles = StyleSheet.create({
  container: {
    flex: 1,
    flexDirection: 'row',
    justifyContent: 'center',
    alignItems: 'stretch'
  }
});

import React, {useCallback} from 'react';
import {FlatList} from 'react-native';
import useGridLayout from './useGridLayout';
import View from '../view';
import {GridListProps, GridListBaseProps} from './types';

function GridList<T = any>(props: GridListProps<T>) {
  const {
    renderItem,
    numColumns,
    itemSpacing,
    maxItemWidth,
    listPadding = 0,
    keepItemSize,
    containerWidth,
    style,
    contentContainerStyle,
    ...others
  } = props;

  const {itemContainerStyle, numberOfColumns, listStyle, listContentStyle, listColumnWrapperStyle} = useGridLayout({
    numColumns,
    itemSpacing,
    maxItemWidth,
    listPadding,
    keepItemSize,
    containerWidth,
    style,
    contentContainerStyle
  });

  const _renderItem = useCallback((...args: any[]) => {
    // @ts-expect-error
    return <View style={itemContainerStyle}>{renderItem?.(...args)}</View>;
  },
  [renderItem, itemContainerStyle]);

  return (
    <FlatList
      key={numberOfColumns}
      {...others}
      /* NOTE: Using style with contentContainerStyle because of RN issue with a flatlist nested in another flatlist 
      losing their contentContainerStyle */
      style={listStyle}
      columnWrapperStyle={numberOfColumns > 1 ? listColumnWrapperStyle : undefined}
      contentContainerStyle={listContentStyle}
      renderItem={_renderItem}
