export default asBaseComponent<HintProps, typeof Hint>(Hint);

import {ElementRef, useCallback, useMemo} from 'react';
import {AccessibilityInfo, findNodeHandle, View as RNView} from 'react-native';
import _ from 'lodash';
import {HintProps} from '../types';

export default function useHintAccessibility(message?: HintProps['message']) {
  const focusAccessibilityOnHint = useCallback((targetRef: ElementRef<typeof RNView>, hintRef: ElementRef<typeof RNView>) => {
    const targetRefTag = findNodeHandle(targetRef);
    const hintRefTag = findNodeHandle(hintRef);

    if (targetRefTag && _.isString(message)) {
      AccessibilityInfo.setAccessibilityFocus(targetRefTag);
    } else if (hintRefTag) {
      AccessibilityInfo.setAccessibilityFocus(hintRefTag);
    }
  },
  [message]);

  const accessibilityInfo = useMemo(() => {
    if (_.isString(message)) {
      return {
        accessible: true,
        accessibilityLabel: `hint: ${message}`
      };
    }
  }, [message]);

  return {
    focusAccessibilityOnHint,
    accessibilityInfo
  };
}

import {type ElementRef, useState, useCallback, useRef} from 'react';
import type {LayoutChangeEvent, LayoutRectangle, View as RNView} from 'react-native';
import _ from 'lodash';
import {HintProps} from '../types';

type UseHintLayoutProps = Pick<HintProps, 'onBackgroundPress' | 'targetFrame'>;

export default function useHintLayout({onBackgroundPress, targetFrame}: UseHintLayoutProps) {
  const [targetLayoutState, setTargetLayout] = useState<LayoutRectangle | undefined>(targetFrame);
  const [targetLayoutInWindowState, setTargetLayoutInWindow] = useState<LayoutRectangle | undefined>(targetFrame);
  const [hintMessageWidth, setHintMessageWidth] = useState<number | undefined>();
  const targetRef = useRef<ElementRef<typeof RNView> | null>(null);

  const onTargetLayout = useCallback(({nativeEvent: {layout}}: LayoutChangeEvent) => {
    if (!_.isEqual(targetLayoutState, layout)) {
      setTargetLayout(layout);
    }

    if (!targetLayoutInWindowState || !!onBackgroundPress) {
      setTimeout(() => {
        targetRef?.current?.measureInWindow?.((x: number, y: number, width: number, height: number) => {
          const targetLayoutInWindow = {x, y, width, height};
          setTargetLayoutInWindow(targetLayoutInWindow);
        });
      });
    }
  },
  [targetLayoutState, targetLayoutInWindowState, onBackgroundPress]);

  const setHintLayout = useCallback(({nativeEvent: {layout}}: LayoutChangeEvent) => {
    if (!hintMessageWidth) {
      setHintMessageWidth(layout.width);
    }
  },
  [hintMessageWidth]);

  return {
    targetLayoutState,
    targetLayoutInWindowState,
    hintMessageWidth,
    targetRef,
    onTargetLayout,
    setHintLayout
  };
}

import {useMemo} from 'react';
import {LayoutRectangle} from 'react-native';
import _ from 'lodash';
import {Constants} from '../../../commons/new';
import {HintPositions, LayoutStyle, PositionStyle, PaddingsStyle, TargetAlignments, HintProps} from '../types';

interface UseHintPositionProps extends Pick<HintProps, 'position' | 'useSideTip'> {
  isUsingModal: boolean;
  targetLayoutState?: LayoutRectangle;
  targetLayoutInWindowState?: LayoutRectangle;
  containerWidth: number;
  edgeMargins: number;
  offset: number;
  hintMessageWidth?: number;
}

export default function useHintPosition({
  isUsingModal,
  targetLayoutState,
  targetLayoutInWindowState,
  position,
  containerWidth,
  useSideTip,
  offset,
  edgeMargins,
  hintMessageWidth
}: UseHintPositionProps) {
  const targetMidPosition = useMemo(() => {
    if (targetLayoutInWindowState?.x !== undefined && targetLayoutInWindowState?.width) {
      const midPosition = targetLayoutInWindowState?.x + targetLayoutInWindowState?.width / 2;
      return Constants.isRTL ? containerWidth - midPosition : midPosition;
    }
  }, [targetLayoutInWindowState, containerWidth]);

  const tipSize = useMemo(() => {
    return useSideTip ? {width: 14, height: 7} : {width: 20, height: 7};
  }, [useSideTip]);

  // Calculate target's horizontal position on screen (left, center, right)
  const targetAlignmentOnScreen = useMemo(() => {
    const _containerWidth = containerWidth - edgeMargins * 2;
    if (targetMidPosition !== undefined) {
      if (targetMidPosition > _containerWidth * (4 / 5)) {
        return TargetAlignments.RIGHT;
      } else if (targetMidPosition < _containerWidth * (1 / 5)) {
        return TargetAlignments.LEFT;
      }
    }
    return TargetAlignments.CENTER;
  }, [targetMidPosition, containerWidth, edgeMargins]);

  // Calc the hint container - a full width rectangle that contains the hint bubble message
  const hintContainerLayout = useMemo(() => {
    const containerStyle: LayoutStyle = {alignItems: 'flex-start'};

    if (targetLayoutInWindowState?.x !== undefined) {
      containerStyle.left = -targetLayoutInWindowState.x;
    }

    if (position === HintPositions.TOP) {
      containerStyle.bottom = 0;
    } else if (targetLayoutInWindowState?.height) {
      containerStyle.top = targetLayoutInWindowState.height;
    }

    return containerStyle;
  }, [position, targetLayoutInWindowState]);

  const hintPositionStyle = useMemo(() => {
    const positionStyle = {left: 0};
    if (targetMidPosition !== undefined && hintMessageWidth !== undefined) {
      positionStyle.left = targetMidPosition;
      positionStyle.left -= hintMessageWidth / 2;
      positionStyle.left = _.clamp(positionStyle.left, edgeMargins, containerWidth - edgeMargins - hintMessageWidth); 
    }

    return positionStyle;
  }, [hintMessageWidth, edgeMargins, containerWidth, targetMidPosition]);

  const tipPositionStyle = useMemo(() => {
    const positionStyle: PositionStyle = {};
    const _containerWidth = containerWidth - (isUsingModal ? 0 : edgeMargins);

    if (position === HintPositions.TOP) {
      positionStyle.bottom = offset - tipSize.height;
      !useSideTip ? (positionStyle.bottom += 1) : undefined;
    } else {
      positionStyle.top = offset - tipSize.height;
    }

    if (
      targetMidPosition !== undefined &&
      targetLayoutInWindowState?.x !== undefined &&
      targetLayoutInWindowState?.width &&
      hintMessageWidth !== undefined
    ) {
      const layoutWidth = targetLayoutInWindowState?.width || 0;
      const targetMidWidth = layoutWidth / 2;
      const tipMidWidth = tipSize.width / 2;

      let sideTipPosition = 0;

      if (targetAlignmentOnScreen === TargetAlignments.LEFT || targetAlignmentOnScreen === TargetAlignments.CENTER) {
        sideTipPosition = Math.max(hintPositionStyle.left, targetLayoutInWindowState.x);
      } else if (targetAlignmentOnScreen === TargetAlignments.RIGHT) {
        sideTipPosition =
          Math.min(hintPositionStyle.left + hintMessageWidth,
            targetLayoutInWindowState.x + targetLayoutInWindowState.width) - edgeMargins;
      }

      const leftPosition = useSideTip ? sideTipPosition : targetMidPosition - tipMidWidth;
      const rightPosition = useSideTip
        ? _containerWidth - targetLayoutInWindowState.x - layoutWidth
        : _containerWidth - targetLayoutInWindowState.x - targetMidWidth - tipMidWidth;

      positionStyle.left = Constants.isRTL ? rightPosition : leftPosition;
    }

    return positionStyle;
  }, [
    targetMidPosition,
    targetLayoutInWindowState,
    hintMessageWidth,
    hintPositionStyle,
    containerWidth,
    position,
    targetAlignmentOnScreen,
    offset,
    useSideTip,
    tipSize,
    isUsingModal,
    edgeMargins
  ]);

  const hintPadding = useMemo(() => {
    const paddings: PaddingsStyle = {paddingVertical: offset};
    return paddings;
  }, [offset]);


  // This is the offset between the target relative position and its absolute position on the screen
  const targetScreenToRelativeOffset = useMemo(() => {
    return {
      left: (targetLayoutState?.x ?? 0) - (targetLayoutInWindowState?.x ?? 0),
      top: (targetLayoutState?.y ?? 0) - (targetLayoutInWindowState?.y ?? 0)
    };
  }, [targetLayoutState, targetLayoutInWindowState]);

  return {
    tipSize,
    targetAlignmentOnScreen,
    hintContainerLayout,
    tipPositionStyle,
    hintPadding,
    hintPositionStyle,
    targetScreenToRelativeOffset
  };
}

import {useRef, useCallback, useState} from 'react';
import {Animated} from 'react-native';
import {useDidUpdate} from 'hooks';

const ANIMATION_DURATION = 170;

export default function useHintVisibility(visible?: boolean) {
  const [hintUnmounted, setHintUnmounted] = useState(!visible);
  const visibleAnimated = useRef(new Animated.Value(Number(!!visible)));

  useDidUpdate(() => {
    animateHint();
  }, [visible]);

  const toggleAnimationEndedToRemoveHint = useCallback(() => {
    setHintUnmounted(!visible);
  }, [visible]);

  const animateHint = useCallback(() => {
    Animated.timing(visibleAnimated.current, {
      toValue: Number(!!visible),
      duration: ANIMATION_DURATION,
      useNativeDriver: true
    }).start(toggleAnimationEndedToRemoveHint);
  }, [visible, toggleAnimationEndedToRemoveHint]);

  return {
    hintUnmounted,
    visibilityProgress: visibleAnimated.current,
    animateHint
  };
}

import React, {isValidElement, ElementRef, useMemo, useCallback, useRef, useEffect} from 'react';
import {Animated, StyleSheet, TouchableWithoutFeedback, View as RNView} from 'react-native';
import {Typography, Spacings, Colors, BorderRadiuses, Shadows} from 'style';
import {Constants, asBaseComponent} from '../../commons/new';
import View from '../view';
import Image from '../image';
import Modal from '../modal';
import TouchableOpacity from '../touchableOpacity';
import Assets from '../../assets';
import {HintPositions, HintProps, TargetAlignments} from './types';

import useHintVisibility from './hooks/useHintVisibility';
import useHintLayout from './hooks/useHintLayout';
import useHintAccessibility from './hooks/useHintAccessibility';
import useHintPosition from './hooks/useHintPosition';
import HintMockChildren from './HintMockChildren';
import HintAnchor from './HintAnchor';
import HintBubble from './HintBubble';

const DEFAULT_COLOR = Colors.$backgroundPrimaryHeavy;
const DEFAULT_HINT_OFFSET = Spacings.s4;
const DEFAULT_EDGE_MARGINS = Spacings.s5;
const HINT_MIN_WIDTH = 68;

const Hint = (props: HintProps) => {
  const {
    visible,
    useModal = true,
    position = HintPositions.BOTTOM,
    children,
    message,
    containerWidth = Constants.windowWidth,
    offset = DEFAULT_HINT_OFFSET,
    edgeMargins = DEFAULT_EDGE_MARGINS,
    targetFrame,
    useSideTip,
    onPress,
    onBackgroundPress,
    backdropColor,
    color = DEFAULT_COLOR,
    icon,
    iconStyle,
    messageStyle,
    removePaddings,
    enableShadow,
    borderRadius,
    customContent,
    testID
  } = props;

  const hintRef = useRef<RNView>(null);
  const isUsingModal = Boolean(onBackgroundPress && useModal);

  const {hintUnmounted, visibilityProgress} = useHintVisibility(visible);
  const {targetLayoutState, targetLayoutInWindowState, hintMessageWidth, targetRef, onTargetLayout, setHintLayout} =
    useHintLayout({onBackgroundPress, targetFrame});
  const {focusAccessibilityOnHint, accessibilityInfo} = useHintAccessibility(message);

  useEffect(() => {
    if (targetRef.current && hintRef.current) {
      focusAccessibilityOnHint(targetRef.current, hintRef.current);
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const targetLayout = useMemo(() => {
    return isUsingModal ? targetLayoutInWindowState : targetLayoutState;
  }, [isUsingModal, targetLayoutState, targetLayoutInWindowState]);

  const setTargetRef = useCallback((ref: ElementRef<typeof RNView>) => {
    targetRef.current = ref;
    if (hintRef.current) {
      focusAccessibilityOnHint(targetRef.current, hintRef.current);
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const showHint = !!targetLayout;

  const {
    targetAlignmentOnScreen,
    hintContainerLayout,
    tipPositionStyle,
    hintPadding,
    hintPositionStyle,
    targetScreenToRelativeOffset
  } = useHintPosition({
    isUsingModal,
    useSideTip,
    position,
    offset,
    targetLayoutState,
    targetLayoutInWindowState,
    containerWidth,
    edgeMargins,
    hintMessageWidth
  });

  const hintAnimatedStyle = useMemo(() => {
    const translateY = position === HintPositions.TOP ? -10 : 10;

    return {
      opacity: visibilityProgress,
      transform: [
        {
          translateY: visibilityProgress.interpolate({inputRange: [0, 1], outputRange: [translateY, 0]})
        }
      ]
    };
  }, [position, visibilityProgress]);

  const renderOverlay = () => {
    if (
      targetLayoutInWindowState &&
      targetScreenToRelativeOffset?.top !== undefined &&
      targetScreenToRelativeOffset?.left !== undefined
    ) {
      return (
        <Animated.View
          style={[
            styles.overlay,
            {
              ...targetScreenToRelativeOffset,
              backgroundColor: backdropColor,
              opacity: visibilityProgress
            }
          ]}
          pointerEvents="box-none"
          testID={`${testID}.overlay`}
        >
          {onBackgroundPress && (
            <TouchableWithoutFeedback style={StyleSheet.absoluteFillObject} onPress={onBackgroundPress}>
              <View flex/>
            </TouchableWithoutFeedback>
          )}
        </Animated.View>
      );
    }
  };

  const renderHintTip = () => {
    const source = useSideTip ? Assets.internal.images.hintTipSide : Assets.internal.images.hintTipMiddle;
    const flipVertically = position === HintPositions.TOP;
    const flipHorizontally = targetAlignmentOnScreen === TargetAlignments.RIGHT;
    const flipStyle = {
      transform: [{scaleY: flipVertically ? -1 : 1}, {scaleX: flipHorizontally ? -1 : 1}]
    };

    return <Image tintColor={color} source={source} style={[styles.hintTip, tipPositionStyle, flipStyle]}/>;
  };

  const renderHint = () => {
    return (
      <HintBubble
        visible={visible}
        message={message}
        messageStyle={messageStyle}
        color={color}
        removePaddings={removePaddings}
        enableShadow={enableShadow}
        borderRadius={borderRadius}
        icon={icon}
        iconStyle={iconStyle}
        customContent={customContent}
        testID={testID}
        hintRef={hintRef}
        setHintLayout={setHintLayout}
        hintPositionStyle={hintPositionStyle}
      />
    );
  };

  const renderHintAnchor = () => {
    const opacity = onPress ? 0.9 : 1.0;
    return (
      <HintAnchor
        {...props}
        showHint={showHint}
        containerWidth={containerWidth}
        hintContainerLayout={hintContainerLayout}
        hintPadding={hintPadding}
        hintAnimatedStyle={hintAnimatedStyle}
        isUsingModal={isUsingModal}
        targetLayout={targetLayout}
      >
        <TouchableOpacity activeOpacity={opacity} onPress={onPress}>
          {renderHint()}
        </TouchableOpacity>
        {renderHintTip()}
      </HintAnchor>
    );
  };

  const renderMockChildren = () => {
    return <HintMockChildren children={children} backdropColor={backdropColor} targetLayout={targetLayout}/>;
  };

  const renderChildren = () => {
    if (!targetFrame && isValidElement(children)) {
      return React.cloneElement<any>(children, {
        key: 'clone',
        collapsable: false,
        onLayout: onTargetLayout,
        ref: setTargetRef,
        ...accessibilityInfo
      });
    }
  };

  if (!visible && hintUnmounted) {
    return children || null;
  }

  return (
    <>
      {renderChildren()}
      {isUsingModal ? (
        <Modal
          visible={showHint}
          animationType={backdropColor ? 'fade' : 'none'}
          overlayBackgroundColor={backdropColor}
          transparent
          onBackgroundPress={onBackgroundPress}
          onRequestClose={onBackgroundPress as () => void}
          testID={`${testID}.modal`}
        >
          {renderMockChildren()}
          {renderHintAnchor()}
        </Modal>
      ) : (
        <>
          {renderOverlay()}
          {renderMockChildren()}
          {renderHintAnchor()}
        </>
      )}
    </>
  );
};

const styles = StyleSheet.create({
  container: {
    position: 'absolute'
  },
  hidden: {opacity: 0},
  overlayContainer: {
    zIndex: 10,
    elevation: 10
  },
