} from 'react-native';

export type PositionStyle = Pick<ViewStyle, 'top' | 'bottom' | 'left' | 'right'>;

export type LayoutStyle = PositionStyle & Pick<ViewStyle, 'alignItems'>;

export type PaddingsStyle = Pick<ViewStyle, 'paddingLeft' | 'paddingRight' | 'paddingVertical' | 'paddingHorizontal'>;

export type ContentType = string | ReactElement<any>;

export enum TargetAlignments {
  LEFT = 'left',
  RIGHT = 'right',
  CENTER = 'center'
}

export enum HintPositions {
  TOP = 'top',
  BOTTOM = 'bottom'
}

export interface HintProps {
  /**
   * Control the visibility of the hint
   */
  visible?: boolean;
  /**
   * The hint background color
   */
  color?: string;
  /**
   * The hint message
   */
  message?: ContentType | ContentType[];
  /**
   * The hint message custom style
   */
  messageStyle?: StyleProp<TextStyle>;
  /**
   * Icon to show next to the hint's message
   */
  icon?: ImageSourcePropType;
  /**
   * The icon's style
   */
  iconStyle?: StyleProp<ImageStyle>;
  /**
   * The hint's position
   */
  position?: HintPositions;
  /**
   * Provide custom target position instead of wrapping a child
   */
  targetFrame?: LayoutRectangle;
  /**
   * Open the hint using a Modal component
   */
  useModal?: boolean;
  /**
   * Show side tips instead of the middle tip
   */
  useSideTip?: boolean;
  /**
   * The hint's border radius
   */
  borderRadius?: number;
  /**
   * Hint margins from screen edges
   */
  edgeMargins?: number;
  /**
   * Hint offset from target
   */
  offset?: number;
  /**
   * Callback for Hint press
   */
  onPress?: () => void;
  /**
   * Callback for the background press
   */
  onBackgroundPress?: (event: GestureResponderEvent) => void;
  /**
   * Color for background overlay (require onBackgroundPress)
   */
  backdropColor?: string;
  /**
   * The hint container width
   */
  containerWidth?: number;
  /**
   * Custom content element to render inside the hint container
   */
  customContent?: JSX.Element;
  /**
   * Remove all hint's paddings
   */
  removePaddings?: boolean;
  /**
   * Enable shadow (for hint with white background only)
   */
  enableShadow?: boolean;
  /**
   * The hint's test identifier
   */
  testID?: string;
  /**
   * Additional styling
   */
  style?: StyleProp<ViewStyle>;
  children?: React.ReactNode;
}

import isUndefined from 'lodash/isUndefined';
import React, {useMemo, forwardRef} from 'react';
import {Image, ImageProps as RNImageProps, StyleSheet, StyleProp, ViewStyle} from 'react-native';
import {asBaseComponent, BaseComponentInjectedProps, MarginModifiers, Constants} from '../../commons/new';
import {ComponentStatics} from '../../typings/common';
import {getAsset, isSvg, isBase64ImageContent} from '../../utils/imageUtils';
import {RecorderProps} from '../../typings/recorderTypes';
import Badge, {BadgeProps} from '../badge';
import SvgImage from '../svgImage';
import type {ImageProps} from '../image';

export type IconProps = Omit<RNImageProps, 'source' | 'tintColor'> &
  MarginModifiers &
  RecorderProps & {
    /**
     * if provided icon source will be driven from asset name
     */
    assetName?: string;
    /**
     * the asset group, default is "icons"
     */
    assetGroup?: string;
    /**
     * Badge props passed down to Badge component
     */
    badgeProps?: BadgeProps;
    /**
     * the icon tint
     */
    tintColor?: string | null;
    /**
     * the icon size
     */
    size?: number | {width: number; height: number};
    /**
     * whether the icon should flip horizontally on RTL
     */
    supportRTL?: boolean;
    source?: ImageProps['source'];
  };

/**
 * @description: Icon component
 * @extends: Image
 * @extendsLink: https://reactnative.dev/docs/image
 */

type Props = IconProps & BaseComponentInjectedProps;

const Icon = forwardRef((props: Props, ref: any) => {
  const {
    size,
    tintColor,
    style,
    supportRTL,
    source,
    assetGroup = 'icons',
    assetName,
    modifiers,
    recorderTag,
    badgeProps,
    ...others
  } = props;
  const {margins} = modifiers;
  const shouldFlipRTL = supportRTL && Constants.isRTL;

  const getBadgeStyling = (): StyleProp<ViewStyle> => {
    const containerStyle = badgeProps?.containerStyle;
    const badgeSizeProp = badgeProps?.size || 1;
    const badgePosition: StyleProp<ViewStyle> = {
      position: 'absolute'
    };
    const position = -badgeSizeProp / 2;
    badgePosition.right = position;
    badgePosition.top = position;
    return [badgePosition, containerStyle];
  };

  const iconSize = useMemo(() => {
    if (typeof size === 'number') {
      return {width: size, height: size};
    }
    if (typeof size === 'object') {
      return size;
    }
    return undefined;
  }, [size]);

  const iconSource = useMemo(() => {
    if (!isUndefined(assetName)) {
      return getAsset(assetName, assetGroup);
    }
    return source;
  }, [source, assetGroup, assetName]);

  const renderImage = () => {
    return (
      <Image
        accessible={false}
        accessibilityRole={'image'}
        fsTagName={recorderTag}
        {...others}
        ref={ref}
        source={iconSource}
        style={[margins, iconSize, shouldFlipRTL && styles.rtlFlipped, !!tintColor && {tintColor}, style]}
      />
    );
  };

  const renderSvg = () => <SvgImage fsTagName={recorderTag} data={source} {...iconSize} {...props}/>;

  if (typeof source === 'string' && isBase64ImageContent(source) && Constants.isWeb) {
    return renderImage();
  }

  return (
    <>
      {isSvg(source) ? renderSvg() : renderImage()}
      {badgeProps && (
        <Badge
          pointerEvents={'none'}
          {...badgeProps}
          containerStyle={getBadgeStyling()}
          testID={`${props?.testID}.badge`}
        />
      )}
    </>
  );
});

Icon.displayName = 'Icon';

export default asBaseComponent<IconProps, ComponentStatics<typeof Icon>>(Icon, {modifiersOptions: {margins: true}});

const styles = StyleSheet.create({
  rtlFlipped: {
    transform: [{scaleX: -1}]
  }
});

import _ from 'lodash';
import React, {PureComponent} from 'react';
import hoistNonReactStatic from 'hoist-non-react-statics';
import {
  StyleSheet,
  Image as RNImage,
  ImageProps as RNImageProps,
  ImageBackground,
  ImageBackgroundProps,
  NativeSyntheticEvent,
  ImageErrorEventData
} from 'react-native';
import {
  Constants,
  asBaseComponent,
  ForwardRefInjectedProps,
  BaseComponentInjectedProps,
  MarginModifiers
} from '../../commons/new';
import {ComponentStatics} from '../../typings/common';
import {RecorderProps} from '../../typings/recorderTypes';
import {getAsset, isSvg} from '../../utils/imageUtils';
import Overlay, {OverlayTypeType, OverlayIntensityType} from '../overlay';
import SvgImage from '../svgImage';
import View from '../view';
import {Colors} from '../../style';

export type ImageSourceType = string | RNImageProps['source'];

export type ImageProps = Omit<RNImageProps, 'source'> &
  Pick<ImageBackgroundProps, 'imageStyle'> &
  MarginModifiers &
  RecorderProps & {
    /**
     * custom source transform handler for manipulating the image source (great for size control)
     */
    sourceTransformer?: (props: any) => ImageSourceType;
    /**
     * if provided image source will be driven from asset name
     */
    assetName?: string;
    /**
     * the asset group, default is "icons"
     */
    assetGroup?: string;
    /**
     * the asset tint
     */
    tintColor?: string;
    /**
     * whether the image should flip horizontally on RTL locals
     */
    supportRTL?: boolean;
    /**
     * Show image as a cover, full width, image (according to aspect ratio, default: 16:8)
     */
    cover?: boolean;
    /**
     * The aspect ratio for the image
     */
    aspectRatio?: number;
    /**
     * The type of overly to place on top of the image. Note: the image MUST have proper size, see examples in:
     * https://github.com/wix/react-native-ui-lib/blob/master/demo/src/screens/componentScreens/OverlaysScreen.tsx
     */
    overlayType?: OverlayTypeType;
    /**
     * The intensity of the overlay ('LOW' | 'MEDIUM' | 'HIGH'), default is 'LOW'.
     */
    overlayIntensity?: OverlayIntensityType;
    /**
     * Pass a custom color for the overlay
     */
    overlayColor?: string;
    /**
     * Render an overlay with custom content
     */
    customOverlayContent?: React.ReactElement<any> | React.ReactElement<any>[];
    /**
     * Default image source in case of an error
     */
    errorSource?: ImageSourceType;
    /**
     * An imageId that can be used in sourceTransformer logic
     */
    imageId?: string;
    /**
     * Use a container for the Image, this can solve issues on
     * Android when animation needs to be performed on the same
     * view; i.e. animation related crashes on Android.
     */
    useBackgroundContainer?: boolean;
    /**
     * The image width
     */
    width?: string | number;
    /**
     * The image height
     */
    height?: string | number;
    source: ImageSourceType;
  };

type Props = ImageProps & ForwardRefInjectedProps & BaseComponentInjectedProps;

type State = {
  error: boolean;
  prevSource: ImageSourceType;
};

/**
 * @description: Image wrapper with extra functionality like source transform and assets support
 * @extends: Image
 * @extendsLink: https://reactnative.dev/docs/image
 * @notes: please note that for SVG support you need to add both
 * `react-native-svg` and `react-native-svg-transformer`,
 * and also configure them (see `metro.config.js`)
 */
class Image extends PureComponent<Props, State> {
  static displayName = 'Image';

  static defaultProps = {
    assetGroup: 'icons'
  };

  public static overlayTypes = Overlay.overlayTypes;
  public static overlayIntensityType = Overlay.intensityTypes;

  sourceTransformer?: (props: any) => ImageSourceType;

  constructor(props: Props) {
    super(props);

    this.sourceTransformer = this.props.sourceTransformer;

    this.state = {
      error: false,
      prevSource: props.source
    };
  }

  static getDerivedStateFromProps(nextProps: Partial<Props>, prevState: State) {
    if (nextProps.source !== prevState.prevSource) {
      return {
        error: false,
        prevSource: nextProps.source
      };
    }
    return null;
  }

  isGif() {
    if (Constants.isAndroid) {
      const {source} = this.props;
      const url = _.get(source, 'uri');
      const isGif = /(http(s?):)([/|.|\w|\s|-])*\.gif/.test(url ?? '');
      return isGif;
    }
  }

  shouldUseImageBackground() {
    const {overlayType, customOverlayContent} = this.props;

    return !!overlayType || this.isGif() || !_.isUndefined(customOverlayContent);
  }

  getVerifiedSource(source?: ImageSourceType) {
    if (_.get(source, 'uri') === null || _.get(source, 'uri') === '') {
      // @ts-ignore
      return {...source, uri: undefined};
    }
    return source;
  }

  getImageSource() {
    const {assetName, assetGroup, source} = this.props;

    if (!_.isUndefined(assetName)) {
      return getAsset(assetName, assetGroup);
    }
    if (this.sourceTransformer) {
      return this.sourceTransformer(this.props);
    }

    return this.getVerifiedSource(source);
  }

  getImageStyle = () => {
    const {imageStyle, borderRadius} = this.props;
    if (this.shouldUseImageBackground()) {
      return borderRadius ? [{borderRadius}, imageStyle] : imageStyle;
    }
  };

  onError = (event: NativeSyntheticEvent<ImageErrorEventData>) => {
    if (event.nativeEvent.error) {
      // TODO: RN 77 hack - test in future releases (ticket 4835)
      if (Constants.isIOS && this.props.source === undefined) {
        return;
      }
      this.setState({error: true});
      this.props.onError?.(event);
    }
  };

  renderSvg = () => {
    const {source, recorderTag, ...others} = this.props;
    return <SvgImage data={source} fsTagName={recorderTag} {...others}/>;
  };

  renderImageWithContainer = () => {
    const {style, cover, modifiers, width, height} = this.props;
    const {margins} = modifiers;

    return (
      <View style={[{width, height}, margins, style, styles.errorImageContainer, cover && styles.coverImage]}>
        {this.renderImage(true)}
      </View>
    );
  };

  renderImage = (useImageInsideContainer: boolean) => {
    const {error} = this.state;
    const source = error ? this.getVerifiedSource(this.props.errorSource) : this.getImageSource();

    const {
      tintColor,
      style,
      width,
      height,
      supportRTL,
      cover,
      aspectRatio,
      overlayType,
      overlayIntensity,
      overlayColor,
      customOverlayContent,
      modifiers,
      recorderTag,
      borderRadius,
      ...others
    } = this.props;
    const shouldFlipRTL = supportRTL && Constants.isRTL;
    const ImageView = this.shouldUseImageBackground() ? ImageBackground : RNImage;
    const {margins} = modifiers;

    return (
      <ImageView
        // @ts-expect-error TODO: this error emanates from the fact that
        // RNImage does not support `resizeMode` inside styles.containImage
        // I think this is too complex for TS to handle as using inline style
        // solves it. It is probably possible to refactor and solve it, but
        // I feel it is not worth the risk ATM.
        style={[
          tintColor && {tintColor},
          shouldFlipRTL && styles.rtlFlipped,
          width ? {width} : undefined,
          height ? {height} : undefined,
          borderRadius ? {borderRadius} : undefined,
          cover && styles.coverImage,
          this.isGif() && styles.gifImage,
          aspectRatio ? {aspectRatio} : undefined,
          !useImageInsideContainer && margins,
          useImageInsideContainer && styles.containImage,
          style,
          useImageInsideContainer && styles.shrink
        ]}
        accessible={false}
        accessibilityRole={'image'}
        fsTagName={recorderTag}
        {...others}
        // NOTE: imageStyle prop is only relevant for when rendering ImageBackground component
        imageStyle={this.getImageStyle()}
        onError={this.onError}
        source={source}
      >
        {(overlayType || customOverlayContent) && (
          <Overlay
            type={overlayType}
            intensity={overlayIntensity}
            color={overlayColor}
            customContent={customOverlayContent}
            borderRadius={borderRadius}
          />
        )}
      </ImageView>
    );
  };

  renderRegularImage() {
    const {error} = this.state;
    const {useBackgroundContainer} = this.props;
    if (error || useBackgroundContainer) {
      return this.renderImageWithContainer();
    } else {
      return this.renderImage(false);
    }
  }

  render() {
    const {source} = this.props;
    if (isSvg(source)) {
      return this.renderSvg();
    } else {
      return this.renderRegularImage();
    }
  }
}

const styles = StyleSheet.create({
  rtlFlipped: {
    transform: [{scaleX: -1}]
  },
  coverImage: {
    width: '100%',
    aspectRatio: 16 / 8
  },
  gifImage: {
    overflow: 'hidden'
  },
  errorImageContainer: {
    backgroundColor: Colors.grey70,
    zIndex: -1
  },
  shrink: {
    flexShrink: 1
  },
  containImage: {
    resizeMode: 'contain'
  }
});

hoistNonReactStatic(Image, RNImage);
export {Image};
export default asBaseComponent<ImageProps, ComponentStatics<typeof Image & typeof RNImage>>(Image, {
  modifiersOptions: {margins: true}
});

import React, {Component} from 'react';
