  textFieldContainerStyle: {
    flexShrink: 1
  },
  accessory: {
    flexGrow: 999
  }
});

import {isUndefined} from 'lodash';
import React, {PureComponent} from 'react';
import {StyleSheet, Image, ImageProps, ImageSourcePropType} from 'react-native';
import {Colors} from '../../style';
import View from '../view';
import Assets from '../../assets';
import Constants from '../../commons/Constants';

const OVERLY_TYPES = {
  VERTICAL: 'vertical',
  TOP: 'top',
  BOTTOM: 'bottom',
  SOLID: 'solid'
};

export enum OverlayIntensityType {
  LOW = 'low',
  MEDIUM = 'medium',
  HIGH = 'high'
}

export type OverlayTypeType = (typeof OVERLY_TYPES)[keyof typeof OVERLY_TYPES];

export type OverlayTypes = Pick<ImageProps, 'borderRadius'> & {
  /**
   * The type of overlay to set on top of the image
   */
  type?: OverlayTypeType;
  /**
   * The intensity of the gradient, default is 'LOW'.
   */
  intensity?: OverlayIntensityType | `${OverlayIntensityType}`;
  /**
   * The overlay color
   */
  color?: string;
  /**
   * Custom overlay content to be rendered on top of the image
   */
  customContent?: React.ReactElement<any> | React.ReactElement<any>[];
};

/**
 * @description: Overlay view with types (default, top, bottom, solid)
 * @extends: Image
 * @extendsLink: https://reactnative.dev/docs/image
 */
class Overlay extends PureComponent<OverlayTypes> {
  static displayName = 'Overlay';
  static overlayTypes = OVERLY_TYPES;
  static intensityTypes = OverlayIntensityType;

  getStyleByType(type = this.props.type) {
    const {color, intensity} = this.props;

    switch (type) {
      case OVERLY_TYPES.TOP:
        return [styles.top, color && {tintColor: color}];
      case OVERLY_TYPES.BOTTOM:
        return [styles.bottom, color && {tintColor: color}];
      case OVERLY_TYPES.SOLID: {
        if (isUndefined(color)) {
          const opacity =
            intensity === OverlayIntensityType.HIGH ? 0.75 : intensity === OverlayIntensityType.MEDIUM ? 0.55 : 0.4;
          return {backgroundColor: Colors.rgba(Colors.grey10, opacity)};
        } else if (color === Colors.white) {
          const opacity =
            intensity === OverlayIntensityType.HIGH ? 0.85 : intensity === OverlayIntensityType.MEDIUM ? 0.7 : 0.45;
          return {backgroundColor: Colors.rgba(Colors.white, opacity)};
        } else {
          return {backgroundColor: color};
        }
      }
      default:
        break;
    }
  }

  renderCustomContent = () => {
    const {customContent} = this.props;
    return (
      <View pointerEvents="box-none" style={styles.customContent}>
        {customContent}
      </View>
    );
  };

  renderImage = (style: any, source: ImageSourcePropType) => {
    return <Image style={[styles.container, style]} resizeMode={'stretch'} source={source}/>;
  };

  getImageSource = (type?: OverlayTypeType, intensity?: OverlayTypes['intensity']) => {
    if (type !== OVERLY_TYPES.SOLID) {
      if (intensity === OverlayIntensityType.MEDIUM) {
        return Assets.internal.images.gradientOverlayMedium;
      } else if (intensity === OverlayIntensityType.HIGH) {
        return Assets.internal.images.gradientOverlayHigh;
      } else {
        return Assets.internal.images.gradientOverlayLow;
      }
    }
  };

  render() {
    const {type, intensity, customContent, borderRadius} = this.props;
    const imageSource = this.getImageSource(type, intensity);

    return (
      <View flex style={{overflow: 'hidden', borderRadius}}>
        {type === OVERLY_TYPES.VERTICAL ? (
          <>
            {this.renderImage([this.getStyleByType(OVERLY_TYPES.TOP), styles.vertical], imageSource)}
            {this.renderImage([this.getStyleByType(OVERLY_TYPES.BOTTOM), styles.vertical], imageSource)}
            {customContent && this.renderCustomContent()}
          </>
        ) : (
          <>
            {type && this.renderImage(this.getStyleByType(), imageSource)}
            {customContent && this.renderCustomContent()}
          </>
        )}
      </View>
    );
  }
}

const styles = StyleSheet.create({
  container: {
    ...StyleSheet.absoluteFillObject,
    width: Constants.isWeb ? '100%' : undefined
  },
  top: {
    bottom: undefined,
    height: '75%'
  },
  bottom: {
    top: undefined,
    transform: [{scaleY: -1}],
    height: '75%'
  },
  vertical: {
    height: '40%'
  },
  customContent: {
    ...StyleSheet.absoluteFillObject
  }
});

export default Overlay;

import _ from 'lodash';
import React, {PureComponent} from 'react';
import {StyleSheet, LayoutAnimation, StyleProp, ViewStyle} from 'react-native';
import {asBaseComponent} from '../../commons/new';
import {Colors} from '../../style';
import {StyleUtils} from '../../utils';
import TouchableOpacity, {TouchableOpacityProps} from '../touchableOpacity';
import View from '../view';

const MAX_SHOWN_PAGES = 7;
const NUM_LARGE_INDICATORS = 3;
const DEFAULT_INDICATOR_COLOR = Colors.$iconPrimary;

function getColorStyle(isCurrentPage: boolean, color?: string, inactiveColor?: string) {
  const activeColor = color || DEFAULT_INDICATOR_COLOR;
  return {
    borderColor: isCurrentPage ? activeColor : inactiveColor || activeColor,
    backgroundColor: isCurrentPage ? activeColor : inactiveColor || 'transparent'
  };
}

function getSizeStyle(size: number, index: number, currentPage: number, enlargeActive?: boolean) {
  const temp = enlargeActive ? (index === currentPage ? size + 2 : size) : size;
  return {width: temp, height: temp, borderRadius: temp / 2};
}

function getNumberOfPagesShown(props: PageControlProps) {
  return Math.min(MAX_SHOWN_PAGES, props.numOfPages);
}

export interface PageControlProps {
  /**
   * Limit the number of page indicators shown.
   * enlargeActive prop is disabled in this state,
   * When set to true there will be maximum of 7 shown.
   * Only relevant when numOfPages > 5.
   */
  limitShownPages?: boolean;
  /**
   * Additional styles for the top container
   */
  containerStyle?: StyleProp<ViewStyle>;
  /**
   * Total number of pages
   */
  numOfPages: number;
  /**
   * Zero-based index of the current page
   */
  currentPage: number;
  /**
   * Action handler for clicking on a page indicator
   */
  onPagePress?: (index: number) => void;
  /**
   * Color of the selected page dot and, if inactiveColor not passed, the border of the not selected pages
   */
  color?: string;
  /**
   * Color of the unselected page dots and the border of the not selected pages
   */
  inactiveColor?: string;
  /**
   * The size of the page indicator.
   * When setting limitShownPages the medium sized will be 2/3 of size and the small will be 1/3 of size.
   * An alternative is to send an array [smallSize, mediumSize, largeSize].
   */
  size?: number | [number, number, number];
  /**
   * Whether to enlarge the active page indicator
   * Irrelevant when limitShownPages is in effect.
   */
  enlargeActive?: boolean;
  /**
   * The space between the siblings page indicators
   */
  spacing?: number;
  /**
   * Used to identify the pageControl in tests
   */
  testID?: string;
}

interface State {
  numOfPagesShown: number;
  largeIndicatorsOffset: number;
  pagesOffset: number;
  prevPage?: number;
}

/**
 * @description: Page indicator, typically used in paged scroll-views
 * @gif: https://user-images.githubusercontent.com/1780255/107114259-2e278d00-686d-11eb-866c-59f3d410d6c3.gif
 * @example: https://github.com/wix/react-native-ui-lib/blob/master/demo/src/screens/componentScreens/PageControlScreen.tsx
 */
class PageControl extends PureComponent<PageControlProps, State> {
  static displayName = 'PageControl';

  static DEFAULT_SIZE = 10;
  static DEFAULT_SPACING = 4;

  static defaultProps = {
    enlargeActive: false
  };

  constructor(props: PageControlProps) {
    super(props);

    this.state = {
      numOfPagesShown: getNumberOfPagesShown(props),
      largeIndicatorsOffset: 0,
      pagesOffset: 0,
      prevPage: undefined
    };

    if (Array.isArray(props.size)) {
      if (props.size[0] >= props.size[1] || props.size[1] >= props.size[2]) {
        console.warn('It is recommended that largeSize > mediumSize > smallSize, currently: smallSize=',
          props.size[0],
          'mediumSize=',
          props.size[1],
          'largeSize=',
          props.size[2]);
      }
    }
  }

  static getDerivedStateFromProps(nextProps: PageControlProps, prevState: State) {
    const {currentPage} = nextProps;
    const {largeIndicatorsOffset: prevLargeIndicatorsOffset, prevPage} = prevState;
    const newState: {prevPage?: number; pagesOffset?: number; largeIndicatorsOffset?: number} = {};

    if (currentPage !== prevPage) {
      newState.prevPage = currentPage;
      if (currentPage >= prevLargeIndicatorsOffset + NUM_LARGE_INDICATORS) {
        PageControl.animate(nextProps);
        newState.pagesOffset = Math.max(0, currentPage - NUM_LARGE_INDICATORS - 1);
        newState.largeIndicatorsOffset = currentPage - NUM_LARGE_INDICATORS + 1;
      } else if (currentPage < prevLargeIndicatorsOffset) {
        PageControl.animate(nextProps);
        newState.pagesOffset = Math.max(0, currentPage - 2);
        newState.largeIndicatorsOffset = currentPage;
      }
    }

    return _.isEmpty(newState) ? null : newState;
  }

  static animate(props: PageControlProps) {
    if (PageControl.showLimitedVersion(props)) {
      LayoutAnimation.configureNext({...LayoutAnimation.Presets.linear, duration: 100});
    }
  }

  static showLimitedVersion({limitShownPages, numOfPages}: PageControlProps) {
    return limitShownPages && numOfPages > 5;
  }

  getSize(index: number): undefined | number {
    const {largeIndicatorsOffset} = this.state;
    const {numOfPages} = this.props;
    let mediumSize,
      smallSize,
      {size = PageControl.DEFAULT_SIZE} = this.props;
    if (Array.isArray(size)) {
      smallSize = size[0];
      mediumSize = size[1];
      size = size[2];
    } else {
      mediumSize = (size * 2) / 3;
      smallSize = size / 3;
    }

    if (index < 0 || index > numOfPages - 1) {
      return undefined;
    } else if (index >= largeIndicatorsOffset && index < largeIndicatorsOffset + NUM_LARGE_INDICATORS) {
      return size;
    } else if (index === largeIndicatorsOffset - 1 || index === largeIndicatorsOffset + NUM_LARGE_INDICATORS) {
      return mediumSize;
    } else if (index === largeIndicatorsOffset - 2 || index === largeIndicatorsOffset + NUM_LARGE_INDICATORS + 1) {
      return smallSize;
    }
  }

  onPagePress = ({customValue: index}: TouchableOpacityProps) => {
    PageControl.animate(this.props);
    this.props.onPagePress?.(index);
  };

  renderIndicator(index: number, size: number, enlargeActive?: boolean) {
    const {currentPage, color, inactiveColor, onPagePress, spacing = PageControl.DEFAULT_SPACING} = this.props;
    const hitSlopValue = StyleUtils.getAccessibleHitSlop(size);

    return (
      <TouchableOpacity
        customValue={index}
        onPress={onPagePress && this.onPagePress}
        key={index}
        style={[
          styles.pageIndicator,
          {marginHorizontal: spacing / 2},
          getColorStyle(index === currentPage, color, inactiveColor),
          getSizeStyle(size, index, currentPage, enlargeActive)
        ]}
        hitSlop={{
          top: hitSlopValue,
          bottom: hitSlopValue
        }}
      />
    );
  }

  renderDifferentSizeIndicators() {
    const {numOfPagesShown, pagesOffset} = this.state;

    return _.map(_.times(numOfPagesShown), index => {
      const adjustedIndex = index + pagesOffset;
      const adjustedSize = this.getSize(adjustedIndex);
      if (adjustedSize) {
        return this.renderIndicator(adjustedIndex, adjustedSize, false);
      } else {
        return null;
      }
    });
  }

  renderSameSizeIndicators() {
    const {numOfPages, size: sizeFromProps = PageControl.DEFAULT_SIZE, enlargeActive} = this.props;
    const size = Array.isArray(sizeFromProps) ? sizeFromProps[2] : sizeFromProps;

    return _.map(_.times(numOfPages), index => this.renderIndicator(index, size, enlargeActive));
  }

  render() {
    const {containerStyle, testID} = this.props;

    return (
      <View style={[styles.container, containerStyle]} inaccessible testID={testID}>
        {PageControl.showLimitedVersion(this.props)
          ? this.renderDifferentSizeIndicators()
          : this.renderSameSizeIndicators()}
      </View>
    );
  }
}

// @ts-expect-error
export default asBaseComponent<PageControlProps>(PageControl);

const styles = StyleSheet.create({
  container: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center'
  },
  pageIndicator: {
    backgroundColor: 'transparent',
    borderWidth: 1
  }
});

import React from 'react';
import {StyleProp, View as RNView, ViewStyle} from 'react-native';
import {useAnimatedStyle} from 'react-native-reanimated';
import {GestureDetector, gestureHandlerRootHOC} from 'react-native-gesture-handler';
import {asBaseComponent} from '../../commons/new';
import View, {ViewProps} from '../view';
import useHiddenLocation from '../../hooks/useHiddenLocation';
import {PanningDirections, PanningDirectionsEnum} from './panningUtil';
import usePanGesture, {
  PanGestureProps,
  PanViewDirections,
  PanViewDirectionsEnum,
  PanViewDismissThreshold,
  DEFAULT_DIRECTIONS
} from './usePanGesture';

export {
  PanningDirections,
  PanningDirectionsEnum,
  PanViewDirections,
  PanViewDirectionsEnum,
  PanViewDismissThreshold
};

export interface PanViewProps extends Omit<PanGestureProps, 'hiddenLocation'>, ViewProps {
  /**
   * Add a style to the container
   */
  containerStyle?: StyleProp<ViewStyle>;
}

interface Props extends PanViewProps {
  children?: React.ReactNode | React.ReactNode[];
}

const PanView = (props: Props) => {
  const {
    directions = DEFAULT_DIRECTIONS,
    dismissible,
    animateToOrigin,
    onDismiss,
    directionLock,
    threshold,
    containerStyle,
    children,
    ...others
  } = props;

  const {setRef, onLayout, hiddenLocation} = useHiddenLocation<RNView>();
  const {translation, gesture} = usePanGesture({
    directions,
    dismissible,
    animateToOrigin,
    onDismiss,
    directionLock,
    threshold,
    hiddenLocation
  });

  const animatedStyle = useAnimatedStyle(() => {
    return {
      transform: [{translateX: translation.x.value}, {translateY: translation.y.value}]
    };
  }, []);

  return (
    <View ref={setRef} style={containerStyle} onLayout={onLayout}>
      <GestureDetector gesture={gesture}>
        <View reanimated style={animatedStyle}>
          <View {...others}>{children}</View>
        </View>
      </GestureDetector>
    </View>
  );
};

PanView.displayName = 'IGNORE';
PanView.directions = PanViewDirectionsEnum;

export default asBaseComponent<PanViewProps, typeof PanView>(gestureHandlerRootHOC(PanView));

