    testID?: string;
    /**
     * Show a loader (while items are loading/fetching)
     */
    showLoader?: boolean;
    /**
     * Custom loader element
     */
    customLoaderElement?: JSX.Element;
  };

export type PickerPropsWithSingle = PickerBaseProps & {
  mode?: PickerModes.SINGLE;
