import React from 'react';
import {ColorValue, StyleSheet} from 'react-native';
import View from '../view';
import {SvgPackage} from '../../optionalDependencies';
import {Colors} from '../../style';
const {Svg, Path} = SvgPackage;

export type PieSegmentProps = {
  /**
   * The percentage of pie the segment should cover
   */
  percentage: number;
  /**
   * The radius of the containing pie
   */
  radius: number;
  /**
   * The color of the segment
   */
  color: string;
  /**
   * The start angle of the segment
   */
  startAngle?: number;
  /**
   * The padding between the segments and the container of the pie.
   */
  padding?: number;
  /**
   * The width of the divider between the segments
   */
  dividerWidth?: number;
  /**
   * The color of the divider between the segments
   */
  dividerColor?: ColorValue;
};

const PieSegment = (props: PieSegmentProps) => {
  const {
    percentage,
    radius,
    color,
    startAngle = 0,
    padding = 0,
    dividerWidth = 4,
    dividerColor = Colors.$backgroundDefault
  } = props;

  const actualRadius = radius - padding;
  const centerXAndY = radius;
  const amountToCover = (percentage / 100) * 360;
  const angleFromTop = startAngle - 90;

  const startRad = (angleFromTop * Math.PI) / 180;
  const endRad = startRad + (amountToCover * Math.PI) / 180;

  const startX = centerXAndY + Math.cos(startRad) * actualRadius;
  const startY = centerXAndY + Math.sin(startRad) * actualRadius;
  const endX = centerXAndY + Math.cos(endRad) * actualRadius;
  const endY = centerXAndY + Math.sin(endRad) * actualRadius;

  const largeArcFlag = amountToCover > 180 ? 1 : 0;
  const sweepFlag = 1;

  const arcPath = `
    M ${centerXAndY} ${centerXAndY}
    L ${startX} ${startY}
    A ${actualRadius} ${actualRadius} 0 ${largeArcFlag} ${sweepFlag} ${endX} ${endY}
    Z
  `;
  const startBorderLine = `M ${centerXAndY} ${centerXAndY} L ${startX} ${startY}`;
  const endBorderLine = `M ${centerXAndY} ${centerXAndY} L ${endX} ${endY}`;

  const arc = <Path d={arcPath} fill={color}/>;
  const borders = (
    <Path
      d={`${startBorderLine} ${endBorderLine}`}
      fill="none"
      stroke={dividerColor}
      strokeWidth={dividerWidth / 2}
      strokeLinejoin="round"
    />
  );
  const totalSize = radius * 2 + padding;

  return (
    <View style={styles.container}>
      <Svg width={totalSize} height={totalSize} viewBox={`0 0 ${totalSize} ${totalSize}`} style={styles.svg}>
        {arc}
        {borders}
      </Svg>
    </View>
  );
};

export default PieSegment;

const styles = StyleSheet.create({
  container: {
    position: 'absolute'
  },
  svg: {
    position: 'absolute'
  }
});

import isUndefined from 'lodash/isUndefined';
import React, {PureComponent, type JSX} from 'react';
import {Animated, Easing, StyleSheet, StyleProp, ViewStyle, LayoutChangeEvent} from 'react-native';
import {Constants, asBaseComponent} from '../../commons/new';
import {extractAccessibilityProps} from '../../commons/modifiers';
import View from '../view';
import {Colors, BorderRadiuses, Spacings} from '../../style';

const CONTAINER_HEIGHT = Spacings.s2;
const FULL_WIDTH_CONTAINER_HEIGHT = Spacings.s1;
const TABLET_CONTAINER_HEIGHT = 6;
const TABLET_FULL_WIDTH_CONTAINER_HEIGHT = 10;
const DEFAULT_COLOR = Colors.$backgroundPrimaryHeavy;

/**
 * @description: Progress bar
 * @example:https://github.com/wix/react-native-ui-lib/blob/master/demo/src/screens/componentScreens/ProgressBarScreen.tsx
 */
interface Props {
  /**
   * The progress of the bar from 0 to 100
   */
  progress?: number;
  /**
   *  FullWidth Ui preset
   */
  fullWidth?: boolean;
  /**
   * Override container style
   * @deprecated Use containerStyle instead
   */
  style?: StyleProp<ViewStyle>;
  /**
   * Override container style
   */
  containerStyle?: StyleProp<ViewStyle>;
  /**
   * Override progress style
   */
  progressStyle?: StyleProp<ViewStyle>;
  /**
   * Progress color
   */
  progressColor?: string;
  /**
   * Custom element to render on top of the animated progress
   */
  customElement?: JSX.Element;
  testID?: string;
}
export type ProgressBarProps = Props;

interface State {
  containerWidth?: number;
}

class ProgressBar extends PureComponent<Props, State> {
  static displayName = 'ProgressBar';

  static defaultProps: Partial<Props> = {
    progress: 0
  };

  progressAnimation: Animated.Value;

  constructor(props: Props) {
    super(props);
    this.progressAnimation = new Animated.Value(props.progress || 0);

    this.state = {
      containerWidth: undefined
    };
  }

  componentDidUpdate(prevProps: Props) {
    const {progress} = this.props;

    if (prevProps.progress !== progress) {
      this.animateProgress(progress);
    }
  }

  getContainerWidth = (event: LayoutChangeEvent) => {
    if (!this.state.containerWidth) {
      this.setState({containerWidth: event.nativeEvent.layout.width});
    }
  };

  animateProgress(toValue?: number) {
    if (!isUndefined(toValue)) {
      Animated.timing(this.progressAnimation, {
        duration: 220,
        easing: Easing.ease,
        toValue,
        useNativeDriver: true
      }).start();
    }
  }

  getAccessibilityProps() {
    const {progress} = this.props;
    if (progress) {
      return {
        accessible: true,
        accessibilityLabel: `progress bar. ${Math.round(progress)}%`,
        ...extractAccessibilityProps()
      };
    }
  }

  getContainerStyle() {
    const {fullWidth} = this.props;
    const containerHeight = fullWidth ? FULL_WIDTH_CONTAINER_HEIGHT : CONTAINER_HEIGHT;
    const tabletContainerHeight = fullWidth ? TABLET_FULL_WIDTH_CONTAINER_HEIGHT : TABLET_CONTAINER_HEIGHT;
    const inlineStyle = fullWidth ? null : styles.inlineContainer;

    return {
      ...inlineStyle,
      height: Constants.isTablet ? tabletContainerHeight : containerHeight
    };
  }

  getProgressStyle() {
    const {fullWidth, progressColor} = this.props;
    const borderRadius = fullWidth ? styles.fullWidthProgressBorderRadius : styles.inlineBorderRadius;
    const progressStyle = {
      right: Constants.isRTL ? undefined : this.state.containerWidth,
      backgroundColor: progressColor || DEFAULT_COLOR
    };

    return {
      ...borderRadius,
      ...progressStyle
    };
  }

  renderCustomElement() {
    const {customElement} = this.props;

    if (customElement) {
      return React.cloneElement(customElement, {
        style: [customElement.props.style, styles.customElement]
      });
    }
  }

  render() {
    const {style, containerStyle, testID, progressStyle} = this.props;
    const {containerWidth = 0} = this.state;
    const outputRange = Constants.isRTL ? [containerWidth, 0] : [0, containerWidth];
    const newProgress = this.progressAnimation.interpolate({
      inputRange: [0, 100],
      outputRange
    });

    const animatedStyle = {transform: [{translateX: newProgress}]};

    return (
      <View
        onLayout={this.getContainerWidth}
        style={[styles.container, this.getContainerStyle(), style, containerStyle]}
        {...this.getAccessibilityProps()}
        testID={testID}
      >
        {!!containerWidth && (
          <Animated.View style={[styles.progress, this.getProgressStyle(), progressStyle, animatedStyle]}>
            {this.renderCustomElement()}
          </Animated.View>
        )}
      </View>
    );
  }
}

export {ProgressBar}; // For tests
export default asBaseComponent<ProgressBarProps, typeof ProgressBar>(ProgressBar);

const styles = StyleSheet.create({
  container: {
    backgroundColor: Colors.$backgroundNeutralMedium,
    overflow: 'hidden',
    borderRadius: BorderRadiuses.br100
  },
  inlineContainer: {
    borderRadius: BorderRadiuses.br100
  },
  progress: {
    position: 'absolute',
    height: '100%',
    width: '100%',
    alignItems: 'center',
    justifyContent: 'center',
    overflow: 'hidden'
  },
  customElement: {
    height: '100%',
    width: '100%'
  },
  inlineBorderRadius: {
    borderRadius: BorderRadiuses.br100
  },
  fullWidthProgressBorderRadius: {
    borderBottomRightRadius: BorderRadiuses.br100,
    borderTopRightRadius: BorderRadiuses.br100
  }
});

