export {
  ScreenFooterProps,
  ScreenFooterLayouts,
  ScreenFooterBackgrounds,
  FooterAlignment,
  HorizontalItemsDistribution,
  ItemsFit,
  KeyboardBehavior,
  ScreenFooterAnimationTypeProp,
  ScreenFooterShadow
};
const ScreenFooter = (props: ScreenFooterProps) => {
  const {
    testID,
    layout,
    alignment,
    horizontalAlignment,
    backgroundType,
    children,
    keyboardBehavior = KeyboardBehavior.STICKY,
    itemsFit,
    itemWidth,
    horizontalItemsDistribution: distribution,
    visible = true,
    animationDuration,
    animationType,
    shadow = ScreenFooterShadow.SH20,
    hideDivider = false,
    isAndroidEdgeToEdge,
    containerStyle: containerStyleOverride,
    contentContainerStyle: contentContainerStyleOverride
  } = props;

  const {containerStyle, setHeight} = useAnimatedFooterStyle({
    animationDuration,
    animationType,
    keyboardBehavior,
    visible,
    isAndroidEdgeToEdge,
    containerStyle: containerStyleOverride
  });

  const onLayout = useCallback((event: LayoutChangeEvent) => {
    setHeight(event.nativeEvent.layout.height);
  }, []);

  const isSolid = backgroundType === ScreenFooterBackgrounds.SOLID;
  const isFading = backgroundType === ScreenFooterBackgrounds.FADING;
  const isHorizontal = layout === ScreenFooterLayouts.HORIZONTAL;

  const childrenCount = React.Children.count(children);

  const justifyContent: ViewStyle['justifyContent'] = useMemo(() => {
    if (isHorizontal) {
      if (distribution === HorizontalItemsDistribution.SPREAD) {
        return childrenCount === 1 ? 'center' : 'space-between';
      }
      switch (horizontalAlignment) {
        case FooterAlignment.START:
          return 'flex-start';
        case FooterAlignment.END:
          return 'flex-end';
        default:
          return 'center';
      }
    }
    return 'flex-start';
  }, [isHorizontal, distribution, horizontalAlignment, childrenCount]);

  const alignItems = useMemo(() => {
    if (layout === ScreenFooterLayouts.VERTICAL) {
      if (itemsFit === ItemsFit.STRETCH) {
        return 'stretch';
      }
    }

    switch (alignment) {
      case FooterAlignment.START:
        return 'flex-start';
      case FooterAlignment.END:
        return 'flex-end';
      default:
        return 'center';
    }
  }, [layout, itemsFit, alignment]);

  const useSafeAreaInsets = SafeAreaContextPackage?.useSafeAreaInsets ?? (() => Constants.getSafeAreaInsets());
  const insets = useSafeAreaInsets();

  const keyboardHeight = useKeyboardHeight();
  const isKeyboardVisible = keyboardHeight > 0;

  const contentContainerStyle = useMemo(() => {
    const style: any[] = [
      styles.contentContainer,
      layout === ScreenFooterLayouts.HORIZONTAL ? styles.horizontalContainer : styles.verticalContainer,
      {alignItems, justifyContent}
    ];

    if (!isKeyboardVisible) {
      style.push({paddingBottom: insets.bottom});
    }

    if (isSolid) {
      const shadowStyle = Shadows[shadow]?.top;
      const backgroundElevation = shadowStyle?.elevation || 0;
      style.push({elevation: backgroundElevation + 1});
    }

    if (contentContainerStyleOverride) {
      style.push(contentContainerStyleOverride);
    }

    return style;
  }, [
    layout,
    alignItems,
    justifyContent,
    insets.bottom,
    isSolid,
    shadow,
    isKeyboardVisible,
    contentContainerStyleOverride
  ]);

  const solidBackgroundStyle = useMemo(() => {
    if (!isSolid) {
      return undefined;
    }
    const shadowStyle = Shadows[shadow]?.top;
    const dividerStyle = hideDivider ? undefined : {borderTopWidth: 1, borderColor: Colors.$outlineDefault};
    return [shadowStyle, dividerStyle];
  }, [isSolid, shadow, hideDivider]);

  const renderBackground = useCallback(() => {
    if (isSolid) {
      return (
        <View
          testID={testID ? `${testID}.solidBackground` : undefined}
          absF
          bg-$backgroundElevated
          style={solidBackgroundStyle}
          pointerEvents="none"
        />
      );
    }

    if (isFading) {
      return (
        <View testID={testID ? `${testID}.fadingBackground` : undefined} absF pointerEvents="none">
          <Image
            source={Assets.internal.images.bottomGradient}
            style={styles.background}
            resizeMode="stretch"
            tintColor={Colors.$backgroundDefault}
          />
        </View>
      );
    }

    return null;
  }, [testID, isSolid, isFading, solidBackgroundStyle]);

  const renderChild = useCallback((child: React.ReactNode, index: number) => {
    if (itemsFit === ItemsFit.FIXED && itemWidth) {
      const fixedStyle: ViewStyle = isHorizontal
        ? {width: itemWidth, flexShrink: 1, overflow: 'hidden', flexDirection: 'row', justifyContent: 'center'}
        : {width: itemWidth, maxWidth: '100%'};
      return (
        <View key={index} style={fixedStyle}>
          {child}
        </View>
      );
    }

    if (isHorizontal && React.isValidElement(child) && itemsFit === ItemsFit.STRETCH) {
      return (
        <View flex row centerH key={index}>
          {child}
        </View>
      );
    }
    return child;
  },
  [itemsFit, itemWidth, isHorizontal]);

  const childrenArray = React.Children.toArray(children).slice(0, 3).map(renderChild);

  const renderFooterContent = useCallback(() => {
    return (
      <>
        {renderBackground()}
        <View testID={testID ? `${testID}.content` : undefined} style={contentContainerStyle}>
          {childrenArray}
        </View>
      </>
    );
  }, [renderBackground, testID, contentContainerStyle, childrenArray]);

  const renderKeyboardAwareFooter = useCallback(() => {
    if (keyboardBehavior === 'hoisted') {
      return (
        <Keyboard.KeyboardAccessoryView
          renderContent={renderFooterContent}
          kbInputRef={undefined}
          scrollBehavior={Keyboard.KeyboardAccessoryView.scrollBehaviors.FIXED_OFFSET}
          useSafeArea={false}
          manageScrollView={false}
          revealKeyboardInteractive
          onHeightChanged={setHeight}
        />
      );
    } else {
      return renderFooterContent();
    }
  }, [keyboardBehavior, renderFooterContent]);

  return (
    <Animated.View
      testID={testID}
      style={containerStyle}
      onLayout={keyboardBehavior === 'hoisted' ? undefined : onLayout}
      pointerEvents={!visible ? 'none' : keyboardBehavior === 'hoisted' ? 'box-none' : 'auto'}
    >
      {renderKeyboardAwareFooter()}
    </Animated.View>
  );
};

ScreenFooter.displayName = 'ScreenFooter';

const styles = StyleSheet.create({
  contentContainer: {
    paddingTop: Spacings.s4,
    paddingHorizontal: Spacings.s5,
    paddingBottom: Spacings.s5
  },
  horizontalContainer: {
    flexDirection: 'row',
    gap: Spacings.s5
  },
  verticalContainer: {
    flexDirection: 'column',
    gap: Spacings.s3
  },
  background: {
    width: '100%',
    height: '100%'
  }
});

export default asBaseComponent<ScreenFooterProps, typeof ScreenFooter>(ScreenFooter);

import {PropsWithChildren} from 'react';
import {DimensionValue, StyleProp, ViewStyle} from 'react-native';

export enum ScreenFooterLayouts {
    HORIZONTAL = 'horizontal',
    VERTICAL = 'vertical'
}

export enum ScreenFooterBackgrounds {
    FADING = 'fading',
    SOLID = 'solid',
    TRANSPARENT = 'transparent'
}

export enum FooterAlignment {
    START = 'start',
    CENTER = 'center',
    END = 'end'
}

export enum HorizontalItemsDistribution {
    STACK = 'stack',
    SPREAD = 'spread'
}

export enum ItemsFit {
    FIT = 'fit',
    STRETCH = 'stretch',
    FIXED = 'fixed'
}

export enum KeyboardBehavior {
    STICKY = 'sticky',
    HOISTED = 'hoisted'
}

export enum ScreenFooterShadow {
    SH10 = 'sh10',
    SH20 = 'sh20',
    SH30 = 'sh30'
}

export enum ScreenFooterAnimation {
    NONE = 'none',
    SLIDE = 'slide',
    FADE = 'fade'
}

export type ScreenFooterAnimationTypeProp = ScreenFooterAnimation | `${ScreenFooterAnimation}`;

export interface AnimatedFooterStyleProps {
    /**
     * The type of animation to use when showing or hiding the footer.
     * @default 'slide'
     */
    animationType?: ScreenFooterAnimationTypeProp;
    /**
     * Duration of the show/hide animation in ms (sending 0 will disable the animation).
     * @default 200
     */
    animationDuration?: number;
}

export interface ScreenFooterProps extends AnimatedFooterStyleProps, PropsWithChildren<{}> {
    /**
     * Used as testing identifier
     */
    testID?: string;
    /**
     * The background style of the footer
     */
    backgroundType?: ScreenFooterBackgrounds | `${ScreenFooterBackgrounds}`;
    /**
     * The layout direction of footer items
     */
    layout?: ScreenFooterLayouts | `${ScreenFooterLayouts}`;
    /**
     * Cross-axis alignment:
     * - Vertical layout: controls horizontal position (left/center/right)
     * - Horizontal layout: controls vertical position (top/center/bottom)
     */
    alignment?: FooterAlignment | `${FooterAlignment}`;
    /**
     * Main-axis alignment for horizontal layout only (when distribution is STACK):
     * Controls horizontal position (left/center/right) of the stacked items
     */
    horizontalAlignment?: FooterAlignment | `${FooterAlignment}`;
    /**
     * Distribution of items in horizontal layout (stack/spread)
     */
    horizontalItemsDistribution?: HorizontalItemsDistribution | `${HorizontalItemsDistribution}`;
    /**
     * How items should fit in vertical layout (fit/fixed/stretch)
     */
    itemsFit?: ItemsFit | `${ItemsFit}`;
    /**
     * The footer's keyboard behavior.
     * When STICKY, the footer will stay at the bottom of the screen when keyboard is opened.
     * When HOISTED, the footer will be pushed up when keyboard is opened.
     */
    keyboardBehavior?: KeyboardBehavior | `${KeyboardBehavior}`;
    /**
     * Fixed width for all items (used with ItemsFit.FIXED)
     */
    itemWidth?: DimensionValue;
    /**
     * If true, the footer is visible. If false, it slides down.
     */
    visible?: boolean;
    /**
     * If true, the footer will respect the safe area (add bottom padding)
     */
    useSafeArea?: boolean;
    /**
     * Shadow preset for solid background (default: SH20)
     * Only applies when backgroundType is 'solid'
     */
    shadow?: ScreenFooterShadow | `${ScreenFooterShadow}`;
    /**
     * If true, hides the top divider for solid background (default: false)
     * Only applies when backgroundType is 'solid'
     */
    hideDivider?: boolean;
    /**
     * Custom style for the outer container of the footer.
     */
    containerStyle?: StyleProp<ViewStyle>;
    /**
     * Custom style for the content container that wraps the footer's children.
     * Can be used to override default padding, gap, or other layout properties.
     */
    contentContainerStyle?: StyleProp<ViewStyle>;
    /**
     * Is this an Android device that supports edge-to-edge
     * Defaults to true for Android with version 35 and above, undefined for others
     */
    isAndroidEdgeToEdge?: boolean;
}

import {useAnimatedKeyboard, useAnimatedStyle, useSharedValue, withTiming} from 'react-native-reanimated';
import {StyleSheet, ViewStyle} from 'react-native';
import {AnimatedFooterStyleProps, ScreenFooterProps} from './types';
import {Constants} from '../../commons/new';
import {useEffect, useMemo, useState} from 'react';

const androidVersion = Constants.getAndroidVersion();
const useAnimatedFooterStyle = (
  props: AnimatedFooterStyleProps &
    Pick<ScreenFooterProps, 'keyboardBehavior' | 'visible' | 'isAndroidEdgeToEdge' | 'containerStyle'>
) => {
  const {
    animationType: animationTypeProp = 'slide',
    animationDuration: animationDurationProp = 200,
    keyboardBehavior,
    visible,
    isAndroidEdgeToEdge = !!androidVersion && androidVersion >= 35 ? true : undefined,
    containerStyle: containerStyleOverride
  } = props;

  const animationType = animationDurationProp === 0 ? 'none' : animationTypeProp;
  const animationDuration = animationType === 'none' ? 0 : animationDurationProp;

  const keyboard = useAnimatedKeyboard({
    isNavigationBarTranslucentAndroid: isAndroidEdgeToEdge,
    isStatusBarTranslucentAndroid: isAndroidEdgeToEdge
  });

  const [height, setHeight] = useState(0);
  const animatedValue = useSharedValue(animationType !== 'slide' && visible ? 1 : 0);

  useEffect(() => {
    if (animationType === 'slide') {
      animatedValue.value = withTiming(visible ? 0 : height, {duration: animationDuration});
    } else {
      animatedValue.value = withTiming(visible ? 1 : 0, {duration: animationDuration});
    }
  }, [visible, height, animationDuration, animatedValue, animationType]);

  const animatedStyle = useAnimatedStyle(() => {
    let style: ViewStyle = {};
    let translateY = 0;
    if (animationType === 'slide') {
      translateY = animatedValue.value;
    } else {
      style = {opacity: animatedValue.value};
    }

    if (keyboardBehavior === 'sticky' && Constants.isAndroid) {
      translateY += keyboard.height.value;
    }

    if (translateY !== 0) {
      style.transform = [{translateY}];
    }

    return style;
  });

  const containerStyle = useMemo(() => {
    return [styles.container, animatedStyle, containerStyleOverride];
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [containerStyleOverride]);

  return {containerStyle, setHeight};
};

export default useAnimatedFooterStyle;

const styles = StyleSheet.create({
  container: {
    position: 'absolute',
    bottom: 0,
    left: 0,
    right: 0,
    zIndex: 50
  }
});

import _ from 'lodash';
import React, {Component, useCallback} from 'react';
import {
  Animated,
  FlatListProps,
  ScrollViewProps,
  ImageSourcePropType,
  NativeSyntheticEvent,
  NativeScrollEvent,
  LayoutChangeEvent
} from 'react-native';
import {ScrollView, FlatList, gestureHandlerRootHOC} from 'react-native-gesture-handler';
import {Colors} from '../../style';
import {Constants, asBaseComponent, forwardRef, ForwardRefInjectedProps} from '../../commons/new';
import {ComponentStatics} from '../../typings/common';
import View from '../view';
import Image from '../image';
import Assets from '../../assets';

export type ListProps =
  | (FlatListProps<any> & {
      /**
       * Whether to use a FlatList. NOTE: you must pass 'data' and 'renderItem' props as well
       */
      useList: true;
    })
  | (ScrollViewProps & {
      /**
       * Whether to use a ScrollView. NOTE: you must pass 'contentContainerStyle' prop as well
       */
      useList?: false;
    });

export type ScrollBarProps = ListProps & {
  /**
   * The element to use as a container, instead of a View
   */
  containerView?: React.ComponentClass;
  /**
   * The props to pass the container
   */
  containerProps?: object;
  /**
   * The component's height
   */
  height?: number;
  /**
   * The gradient's height, defaults to the component's height
   */
  gradientHeight?: number;
  /**
   * The gradient's width
   */
  gradientWidth?: number;
  /**
   * The gradient's margins for the edge
   */
  gradientMargins?: number;
  /**
   * The gradient's tint color
   */
  gradientColor?: string;
  /**
   * The gradient's image, instead of the default image.
   * NOTE: pass an image for the right-hand side and it will be flipped to match the left-hand side
   */
  gradientImage?: ImageSourcePropType;
  /**
   * The index to currently focus on
   */
  focusIndex?: number;
};

type Props = ScrollBarProps & ForwardRefInjectedProps;

type State = {
  gradientOpacity: Animated.Value;
  gradientOpacityLeft: Animated.Value;
};

const GRADIENT_WIDTH = 76;

/**
 * @description: Scrollable container with animated gradient overlay for horizontal scroll
 * @extends: ScrollView / FlatList
 */

class ScrollBar extends Component<Props, State> {
  static displayName = 'IGNORE';

  static defaultProps = {
    gradientWidth: GRADIENT_WIDTH,
    gradientMargins: 0,
    gradientColor: Colors.$backgroundDefault,
    focusIndex: 0
  };

  static Item: typeof Item;

  constructor(props: Props) {
    super(props);

    this.state = {
      gradientOpacity: new Animated.Value(0),
      gradientOpacityLeft: new Animated.Value(0)
    };
  }

  private scrollbar: any = undefined;
  private itemsLayouts: any = {};
  private contentOffset = 0;
  private scrollContentWidth = 0;
  private containerWidth = 0;

  componentDidUpdate(prevProps: Props) {
    const {focusIndex} = this.props;
    if (prevProps.focusIndex !== focusIndex) {
      this.focusIndex(focusIndex);
    }
  }

  focusIndex = (index = 0) => {
    const focusedItemLayout = this.itemsLayouts[index];
    if (focusedItemLayout) {
      const {x, width} = focusedItemLayout;
      if (x < this.contentOffset) {
        this.scrollbar.scrollTo({x: x - width});
      } else if (x + width > this.contentOffset + this.containerWidth) {
        const offsetChange = Math.max(0, x - (this.contentOffset + this.containerWidth));
        this.scrollbar.scrollTo({x: this.contentOffset + offsetChange + width});
      }
    }
  };

  animateGradientOpacity = (offsetX: number, contentWidth: number, containerWidth: number) => {
    const overflow = contentWidth - containerWidth;
    const newValue = offsetX > 0 && offsetX >= overflow - 1 ? 0 : 1;
    const newValueLeft = offsetX > 0 ? 1 : 0;

    Animated.parallel([
      Animated.spring(this.state.gradientOpacity, {
        toValue: newValue,
        speed: 20,
        useNativeDriver: true
      }),
      Animated.spring(this.state.gradientOpacityLeft, {
        toValue: newValueLeft,
        speed: 20,
        useNativeDriver: true
      })
    ]).start();
  };

  onScroll = (event: NativeSyntheticEvent<NativeScrollEvent>) => {
    const {layoutMeasurement, contentOffset, contentSize} = event.nativeEvent;
    this.contentOffset = contentOffset.x;
    const offsetX = contentOffset.x;
    const contentWidth = contentSize.width;
    const containerWidth = layoutMeasurement.width;

    this.animateGradientOpacity(offsetX, contentWidth, containerWidth);

    this.props.onScroll?.(event);
  };

  onContentSizeChange = (contentWidth: number, contentHeight: number) => {
    if (this.scrollContentWidth !== contentWidth) {
      this.scrollContentWidth = contentWidth;

      // race condition - won't pass if onLayout() was not called before
      if (contentWidth > this.containerWidth) {
        this.setState({gradientOpacity: new Animated.Value(1)});
      }

      this.props.onContentSizeChange?.(contentWidth, contentHeight);
    }
  };

  onLayout = (event: LayoutChangeEvent) => {
    this.containerWidth = event.nativeEvent.layout.width;

    this.props.onLayout?.(event);
    // 1 - for race condition, in case onContentSizeChange() is called before
    // 0 - for containerWidth change, when onContentSizeChange() is called first
    this.setState({gradientOpacity: new Animated.Value(this.scrollContentWidth > this.containerWidth ? 1 : 0)});
  };

  onItemLayout = ({layout, index}: any) => {
    this.itemsLayouts[index] = layout;

    const {children, focusIndex} = this.props;
    if (children && _.keys(this.itemsLayouts).length === _.keys(children).length) {
      this.focusIndex(focusIndex);
    }
  };

  renderScrollable() {
    const {useList, forwardedRef, children} = this.props;
    const Component: any = useList ? FlatList : ScrollView;

    return (
      <Component
        scrollEventThrottle={100}
        {...this.props}
        ref={(r: any) => {
          this.scrollbar = r;
          if (_.isFunction(forwardedRef)) {
            forwardedRef(r);
          } else if (_.isObject(forwardedRef)) {
            //@ts-ignore
            forwardedRef.current = r;
          }
        }}
        horizontal
        showsHorizontalScrollIndicator={false}
        onScroll={this.onScroll}
        onContentSizeChange={this.onContentSizeChange}
      >
        {children &&
          React.Children.map(children, (child, index) => {
            return (
              <Item onLayout={this.onItemLayout} index={index}>
                {child}
              </Item>
            );
          })}
      </Component>
    );
  }

  renderGradient(left: boolean) {
    const {gradientOpacity, gradientOpacityLeft} = this.state;
    const {gradientWidth, gradientHeight, gradientMargins, height, gradientColor, gradientImage} = this.props;
    const imageTransform = Constants.isRTL ? (left ? undefined : [{scaleX: -1}]) : left ? [{scaleX: -1}] : undefined;
    const heightToUse = gradientHeight || height || '100%';
    return (
      <Animated.View
        pointerEvents="none"
        style={{
          opacity: left ? gradientOpacityLeft : gradientOpacity,
          width: gradientWidth,
          height: heightToUse,
          position: 'absolute',
          right: !left ? gradientMargins : undefined,
          left: left ? gradientMargins : undefined
        }}
      >
        <Image
          source={gradientImage || Assets.internal.images.gradientOverlay}
          style={{
            width: gradientWidth,
            height: heightToUse,
            tintColor: gradientColor,
            transform: imageTransform
          }}
          resizeMode={'stretch'}
        />
      </Animated.View>
    );
  }

  render() {
    const {containerView, containerProps} = this.props;
    const Container: any = containerView || View;

    return (
      <Container row {...containerProps} onLayout={this.onLayout}>
        {this.renderScrollable()}
        {this.renderGradient(false)}
        {this.renderGradient(true)}
      </Container>
    );
  }
}

const Item = ({children, index, onLayout}: any) => {
  const onItemLayout = useCallback(({nativeEvent: {layout}}: LayoutChangeEvent) => {
    onLayout({layout, index});
  },
  [children]);

  return (
    <View flexG onLayout={onItemLayout}>
      {children}
    </View>
  );
};

Item.displayName = 'IGNORE';
ScrollBar.Item = Item;

export default asBaseComponent<ScrollBarProps, ComponentStatics<typeof ScrollBar>>(forwardRef(gestureHandlerRootHOC(ScrollBar)));

import _ from 'lodash';
import React, {useImperativeHandle, forwardRef, ForwardedRef, useEffect, useRef, useState} from 'react';
import {StyleSheet, Animated, TextInput, ActivityIndicator} from 'react-native';
import {SearchInputPresets, SearchInputProps, SearchInputRef} from './types';
import {Colors, BorderRadiuses, Spacings, Typography} from '../../style';
import {Constants, asBaseComponent} from '../../commons/new';
import Button from '../button';
import Icon from '../icon';
import View from '../view';
import Assets from '../../assets';

const ICON_SIZE = 24;
const INPUT_HEIGHT = 60;
const TOP_INPUT_HEIGHT = Constants.isIOS ? 40 : 56;
const PROMINENT_INPUT_HEIGHT = 48;
const INVERTED_TEXT_COLOR = Colors.$textDefaultLight;
const INVERTED_ICON_COLOR = Colors.$iconDefaultLight;
const HIT_SLOP_VALUE = 20;

const SearchInput = forwardRef((props: SearchInputProps, ref: ForwardedRef<any>) => {
  const {
    preset = SearchInputPresets.DEFAULT,
    onDismiss,
    useSafeArea,
    invertColors,
    testID,
    showLoader,
    loaderProps,
    value: controlledValue,
    onChangeText,
    onClear,
    containerStyle,
    customRightElement,
    style,
    inaccessible
  } = props;
  const currentAnimatedValue = useRef<ReturnType<typeof Animated.timing> | undefined>(undefined);
  const searchInputRef = useRef<TextInput>(null);
  const [hasValue, setHasValue] = useState(Boolean(controlledValue));
  const [value, setValue] = useState(controlledValue);
  const [valueState] = useState(new Animated.Value(_.isEmpty(controlledValue) ? 0 : 1));
  const [isAnimatingClearButton, setIsAnimatingClearButton] = useState(!_.isEmpty(controlledValue));

  useImperativeHandle(ref, () => {
    return {
      blur: () => searchInputRef.current?.blur(),
      focus: () => searchInputRef.current?.focus(),
      clear: () => {
        searchInputRef.current?.clear();
        onChangeText?.('');
        onClear?.();
      }
    };
  });

  useEffect(() => {
    if (controlledValue !== value) {
      setValue(controlledValue);
      setHasValue(Boolean(controlledValue));
    }
  }, [controlledValue]);

  useEffect(() => {
    if (hasValue) {
      animatedValueState(1);
    } else {
      animatedValueState(0);
    }
  }, [hasValue]);

  useEffect(() => {
    return () => {
      currentAnimatedValue.current?.stop();
    };
  }, []);

  const animatedValueState = (value: number) => {
    setIsAnimatingClearButton(true);
    if (currentAnimatedValue.current) {
      currentAnimatedValue.current.stop();
    }
    currentAnimatedValue.current = Animated.timing(valueState, {
      toValue: value,
      duration: 160,
      useNativeDriver: true
    });

    currentAnimatedValue.current.start(() => {
      if (!hasValue) {
        setIsAnimatingClearButton(false);
      }
    });
  };

  const getHeight = () => {
    const isProminent = preset === SearchInputPresets.PROMINENT;
    if (isProminent) {
      return PROMINENT_INPUT_HEIGHT;
    }
    return useSafeArea ? TOP_INPUT_HEIGHT : INPUT_HEIGHT;
  };

  const onChangeTextHandler = (text: string) => {
    console.log(`onChangeTextHandler, text:`, text);
    onChangeText?.(text);
    setValue(text);
    setHasValue(!_.isEmpty(text));
  };

  const clearInput = () => {
    searchInputRef?.current?.clear();
    onChangeTextHandler('');
    onClear?.();
  };

  const renderClearButton = () => {
    const transform = [
      {
        translateY: valueState.interpolate({
          inputRange: [0, 1],
          outputRange: [50, 1]
        })
      }
    ];

    const clearButtonStyle = !isDismissible() && isAnimatingClearButton && styles.clearButton;
    const iconStyle = {tintColor: invertColors ? INVERTED_ICON_COLOR : Colors.grey40, width: 12, height: 12};
    return (
      <Animated.View style={[{transform}, clearButtonStyle]}>
        <Button
          link
          grey10
          text80
          iconSource={Assets.internal.icons.x}
          iconStyle={iconStyle}
          onPress={clearInput}
          hitSlop={HIT_SLOP_VALUE}
          accessible={Boolean(hasValue)}
          accessibilityLabel={'clear'}
          testID={`${testID}.clearButton`}
        />
      </Animated.View>
    );
  };

  const renderCancelButton = () => {
    const {cancelButtonProps} = props;
    if (onDismiss) {
      return (
        <Button
          style={styles.cancelButton}
          link
          color={invertColors ? INVERTED_TEXT_COLOR : undefined}
          $textDefault
          text65M
          {...cancelButtonProps}
          onPress={onDismiss}
          testID={`${testID}.cancelButton`}
        />
      );
    }
  };

  const renderTextInput = () => {
    const {placeholder} = props;
    const height = getHeight();
    const placeholderTextColor = invertColors ? INVERTED_TEXT_COLOR : Colors.$textDefault;
    const selectionColor = invertColors ? INVERTED_TEXT_COLOR : Colors.$textDefault;
    return (
      <View style={[styles.inputContainer, {height}]}>
        <TextInput
          accessibilityRole={'search'}
          placeholder={placeholder}
          placeholderTextColor={placeholderTextColor}
          underlineColorAndroid="transparent"
          selectionColor={selectionColor}
          ref={searchInputRef}
          value={value}
          allowFontScaling={false}
          style={[
            styles.input,
            containerStyle,
            invertColors && {color: INVERTED_TEXT_COLOR},
            (!isDismissible() || isAnimatingClearButton) && styles.emptyInput
          ]}
          onChangeText={onChangeTextHandler}
          testID={testID}
        />
        {isAnimatingClearButton && renderClearButton()}
        {isDismissible() && renderCancelButton()}
        {!isDismissible() && customRightElement}
      </View>
    );
  };

  const isDismissible = () => {
    return typeof onDismiss !== 'undefined';
  };

  const renderIcon = (icon: any, left = true) => {
    const invertedColor = invertColors ? {tintColor: INVERTED_ICON_COLOR} : undefined;
    return (
      <View>
        <Icon
          tintColor={invertedColor?.tintColor}
          style={[styles.icon, invertedColor, left && styles.leftIcon]}
          source={icon}
          size={ICON_SIZE}
        />
      </View>
    );
  };

  const renderLoader = () => {
    const {customLoader} = props;
    return <View>{customLoader ? customLoader : <ActivityIndicator style={styles.loader} {...loaderProps}/>}</View>;
  };

  const topInputTopMargin = useSafeArea && {marginTop: Constants.isIOS ? Constants.statusBarHeight : 0};
  const isProminent = preset === SearchInputPresets.PROMINENT;

  return (
    <View
      inaccessible={inaccessible}
      row
      centerV
      style={[style, isProminent && styles.prominentContainer, topInputTopMargin]}
      testID={`${testID}.searchBox`}
    >
      {showLoader ? renderLoader() : renderIcon(Assets.internal.icons.search)}
      {renderTextInput()}
    </View>
  );
});

