const CONTAINER_BORDER_WIDTH = 1;
const TIMING_CONFIG = {
  duration: 300,
  easing: Easing.bezier(0.33, 1, 0.68, 1)
};

export enum SegmentedControlPreset {
  DEFAULT = 'default',
  FORM = 'form'
}

export {SegmentedControlItemProps};
export type SegmentedControlProps = {
