  /**
   * A key for the duplicated SkeletonViews.
   * This is needed because the `key` prop is not accessible.
   */
  timesKey?: string;
  /**
   * The height of the skeleton view
   */
  height?: number;
  /**
   * The width of the skeleton view
   */
  width?: number;
  /**
   * The colors of the skeleton view, the array length has to be >=2
   * default: [Colors.grey70, Colors.grey60, Colors.grey70]
   */
  colors?: string[];
  /**
   * The border radius of the skeleton view
   */
  borderRadius?: number;
  /**
   * Whether the skeleton is a circle (will override the borderRadius)
   */
  circle?: boolean;
  /**
   * Additional style to the skeleton view
   */
  shimmerStyle?: StyleProp<ViewStyle>;
  /**
   * Override container styles
   */
  style?: StyleProp<ViewStyle>;
  /**
   * Used to locate this view in end-to-end tests
   */
  testID?: string;
  children?: React.ReactNode;
}

interface SkeletonState {
  isAnimating: boolean;
  opacity: Animated.Value;
}

/**
 * @description: Allows showing a temporary skeleton view while your real view is loading.
 * @example: https://github.com/wix/react-native-ui-lib/blob/master/demo/src/screens/componentScreens/SkeletonViewScreen.tsx
 * @image: https://github.com/wix/react-native-ui-lib/blob/master/demo/showcase/Skeleton/Skeleton.gif?raw=true
 * @notes: View requires installing the 'react-native-shimmer-placeholder' and 'react-native-linear-gradient' library
 */
class SkeletonView extends Component<SkeletonViewProps, SkeletonState> {
  static displayName = 'SkeletonView';
  static defaultProps = {
    size: Size.SMALL,
    // listProps: {size: Size.SMALL}, TODO: once size is deprecated remove it and add this
    borderRadius: BorderRadiuses.br10
  };

  static templates: typeof Template = Template;
  static sizes: typeof Size = Size;
  static contentTypes: typeof ContentType = ContentType;

  fadeInAnimation?: Animated.CompositeAnimation;
  contentAccessibilityProps?: AccessibilityProps;
  listItemAccessibilityProps?: AccessibilityProps;

  setAccessibilityProps(template?: SkeletonViewProps['template']) {
    const isListItem = template === Template.LIST_ITEM;
    const accessibilityProps = {
      accessible: true,
      accessibilityLabel: isListItem ? 'Loading list item' : 'Loading content'
    };

    if (isListItem) {
      this.listItemAccessibilityProps = accessibilityProps;
    } else {
      this.contentAccessibilityProps = accessibilityProps;
    }
  }

  constructor(props: SkeletonViewProps) {
    super(props);

    this.state = {
      isAnimating: props.showContent === false,
      opacity: new Animated.Value(0)
    };

    if (_.isUndefined(LinearGradientPackage?.default)) {
      LogService.error(`RNUILib SkeletonView's requires installing "react-native-linear-gradient" dependency`);
    } else if (_.isUndefined(createShimmerPlaceholder)) {
      LogService.error(`RNUILib SkeletonView's requires installing "react-native-shimmer-placeholder" dependency`);
    } else if (ShimmerPlaceholder === undefined) {
      ShimmerPlaceholder = createShimmerPlaceholder(LinearGradient);
    }

    this.setAccessibilityProps(props.template);
  }

  componentDidMount() {
    if (this.state.isAnimating) {
      this.fadeInAnimation = this.fade(true);
    }
  }

  componentDidUpdate(prevProps: SkeletonViewProps) {
    if (this.props.showContent && !prevProps.showContent) {
      this.fadeInAnimation?.stop();
      this.fade(false, this.showChildren);
    }
  }

  fade(isFadeIn: boolean, onAnimationEnd?: Animated.EndCallback) {
    const animation = Animated.timing(this.state.opacity, {
      toValue: isFadeIn ? 1 : 0,
      easing: Easing.ease,
      duration: ANIMATION_DURATION,
      useNativeDriver: true
    });

    animation.start(onAnimationEnd);
    return animation;
  }

  showChildren = () => {
    this.setState({isAnimating: false});
  };

  getDefaultSkeletonProps = (input?: {circleOverride: boolean; style: StyleProp<ViewStyle>}) => {
    const {circleOverride, style} = input || {};
    const {circle, colors, width, height = 0, shimmerStyle} = this.props;
    let {borderRadius} = this.props;
    let size;

    if (circle || circleOverride) {
      borderRadius = BorderRadiuses.br100;
      size = Math.max(width || 0, height);
    }

    return {
      shimmerColors: colors || [Colors.$backgroundNeutral, Colors.$backgroundNeutralMedium, Colors.$backgroundNeutral],
      isReversed: Constants.isRTL,
      style: [{borderRadius}, style],
      width: size || width,
      height: size || height,
      shimmerStyle
    };
  };

  get contentSize() {
    const {listProps} = this.props;
    return listProps?.size === Size.LARGE ? 48 : 40;
  }

  renderListItemLeftContent = () => {
    const {listProps} = this.props;
    const contentType = listProps?.contentType;
    if (contentType) {
      const circleOverride = contentType === ContentType.AVATAR;
      const style = {marginRight: listProps?.size === Size.LARGE ? 16 : 14};
      return (
        <ShimmerPlaceholder
          {...this.getDefaultSkeletonProps({circleOverride, style})}
          width={this.contentSize}
          height={this.contentSize}
        />
      );
    }
  };

  renderStrip = (isMain: boolean, length: number, marginTop: number) => {
    return (
      <ShimmerPlaceholder
        {...this.getDefaultSkeletonProps()}
        width={length}
        height={isMain ? 12 : 8}
        style={[{marginTop}]}
      />
    );
  };

  renderListItemContentStrips = () => {
    const {listProps} = this.props;
    const size = listProps?.size;
    const customLengths = listProps?.contentType === ContentType.AVATAR ? [undefined, 50] : undefined;
    const height = size === Size.LARGE ? 95 : 75;
    const lengths = _.merge([90, 180, 160], customLengths);
    const topMargins = [0, size === Size.LARGE ? 16 : 8, 8];
    return (
      <View flex height={height} centerV style={!listProps?.hideSeparator && Dividers.d10} row>
        <View>
          {this.renderStrip(true, lengths[0], topMargins[0])}
          {this.renderStrip(false, lengths[1], topMargins[1])}
          {size === Size.LARGE && this.renderStrip(false, lengths[2], topMargins[2])}
        </View>
        {listProps?.renderEndContent?.()}
      </View>
    );
  };

  getListItemStyle = memoize(style => {
    return [styles.listItem, style];
  });

  renderListItemTemplate = () => {
    const {style, ...others} = this.props;

    return (
      <View style={this.getListItemStyle(style)} {...this.listItemAccessibilityProps} {...others}>
        {this.renderListItemLeftContent()}
        {this.renderListItemContentStrips()}
      </View>
    );
  };

  renderTextContentTemplate = () => {
    return (
      <View {...this.contentAccessibilityProps} {...this.props}>
        {this.renderStrip(true, 235, 0)}
        {this.renderStrip(true, 260, 12)}
        {this.renderStrip(true, 190, 12)}
      </View>
    );
  };

  renderTemplate = () => {
    const {template} = this.props;
    switch (template) {
      case Template.LIST_ITEM:
        return this.renderListItemTemplate();
      case Template.TEXT_CONTENT:
        return this.renderTextContentTemplate();
      default:
        // just so we won't crash
        return this.renderAdvanced();
    }
  };

  renderAdvanced = () => {
    const {children, renderContent, showContent, style, testID, ...others} = this.props;
    const data = showContent && _.isFunction(renderContent) ? renderContent(this.props) : children;

    return (
      <View style={style} {...this.contentAccessibilityProps} testID={testID} {...others}>
        <ShimmerPlaceholder {...this.getDefaultSkeletonProps()} testID={`${testID}.shimmer`} {...others}>
          {showContent && data}
        </ShimmerPlaceholder>
      </View>
    );
  };

  renderWithFading = (skeleton: any) => {
    const {isAnimating} = this.state;
    const {children, renderContent, customValue} = this.props;

    if (isAnimating) {
      return (
        <Animated.View
          style={{
            opacity: this.state.opacity
          }}
          pointerEvents="none"
        >
          {skeleton}
        </Animated.View>
      );
    } else if (_.isFunction(renderContent)) {
      return renderContent(customValue);
    } else {
      return children;
    }
  };

  renderSkeleton() {
    const {template, showContent, children, renderContent} = this.props;
    let skeleton;
    if (template) {
      skeleton = this.renderTemplate();
    } else {
      skeleton = this.renderAdvanced();
    }

    if (_.isUndefined(showContent) || (_.isUndefined(children) && _.isUndefined(renderContent))) {
      return skeleton;
    } else {
      return this.renderWithFading(skeleton);
    }
  }

  renderNothing = () => null;

  render() {
    if (_.isUndefined(LinearGradientPackage?.default) || _.isUndefined(createShimmerPlaceholder)) {
      return null;
    }

    const {
      times,
      timesKey,
      renderContent,
      showContent,
      customValue,
      template,
      listProps,
      height,
      width,
      colors,
      borderRadius,
      circle,
      style,
      testID,
      ...others
    } = this.props;

    const passedProps = {
      showContent,
      renderContent,
      customValue,
      template,
      listProps,
      height,
      width,
      colors,
      borderRadius,
      circle,
      style,
      testID
    };

    if (times) {
      return (
        <View {...others}>
          {_.times(times, index => {
            const key = timesKey ? `${timesKey}-${index}` : `${index}`;
            const _listProps = {
              ...listProps,
              hideSeparator: listProps?.hideSeparator || (!listProps?.showLastSeparator && index === times - 1)
            };
            return (
              <SkeletonView
                {...passedProps}
                listProps={_listProps}
                key={key}
                testID={`${testID}-${index}`}
                renderContent={index === 0 ? renderContent : this.renderNothing}
                times={undefined}
              />
            );
          })}
        </View>
      );
    } else {
      return this.renderSkeleton();
    }
  }
}

export default SkeletonView as React.ComponentClass<SkeletonViewProps> & ComponentStatics<typeof SkeletonView>;

const styles = StyleSheet.create({
  listItem: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingLeft: Spacings.s5
  }
});

import _ from 'lodash';
import React, {forwardRef, useRef} from 'react';
import {
  StyleSheet,
  StyleProp,
  ViewStyle,
  ViewProps,
  View as RNView,
  Animated,
  GestureResponderEvent
} from 'react-native';
import {useCombinedRefs} from 'hooks';
import {Colors} from '../../style';

export interface ThumbProps extends ViewProps {
  /**
   * The thumb style
   */
  thumbStyle?: ViewStyle;
  /**
   * The active (during press) thumb style
   */
  activeThumbStyle?: ViewStyle;
  /**
   * If true the Slider will not change it's style on press
   */
  disableActiveStyling?: boolean;
  /**
   * Defines how far a touch event can start away from the thumb.
   */
  thumbHitSlop?: ViewProps['hitSlop'];
  /**
   * Thumb color
   */
  thumbTintColor?: string;
  /**
   * If true the Slider will be disabled and will appear in disabled color
   */
  disabled?: boolean;
  /** ref to thumb component */
  ref?: React.RefObject<RNView | null>;
}
type ThumbStyle = {style?: StyleProp<ViewStyle>; left?: StyleProp<number>};

const THUMB_SIZE = 24;
const BORDER_WIDTH = 6;
const SHADOW_RADIUS = 4;
const DEFAULT_COLOR = Colors.$backgroundDisabled;
const ACTIVE_COLOR = Colors.$backgroundPrimaryHeavy;

const Thumb = forwardRef((props: ThumbProps, ref: any) => {
  const {
    disabled,
    thumbStyle,
    activeThumbStyle,
    disableActiveStyling,
    thumbTintColor,
    thumbHitSlop,
    onTouchStart,
    onTouchEnd,
    ...others
  } = props;

  const thumbRef = useCombinedRefs(ref);

  /** Scaling thumb */

  const _onTouchStart = (e: GestureResponderEvent) => {
    updateThumbStyle(true);
    onTouchStart?.(e);
  };

  const _onTouchEnd = (e: GestureResponderEvent) => {
    updateThumbStyle(false);
    onTouchEnd?.(e);
  };

  const thumbStyles: ThumbStyle = {};
  const thumbScaleAnimation = useRef(new Animated.Value(1));
  const thumbAnimationConstants = {
    duration: 100,
    defaultScaleFactor: 1.5
  };

  const updateThumbStyle = (start: boolean) => {
    if (!disableActiveStyling) {
      const style = thumbStyle || styles.thumb;
      const activeStyle = activeThumbStyle || styles.activeThumb;
      const activeOrInactiveStyle = !disabled ? (start ? activeStyle : style) : {};

      thumbStyles.style = _.omit(activeOrInactiveStyle, 'height', 'width');
      //@ts-expect-error
      thumbRef.current?.setNativeProps?.(thumbStyles);

      scaleThumb(start);
    }
  };

  const calculateThumbScale = () => {
    if (disabled || disableActiveStyling) {
      return 1;
    }

    const {defaultScaleFactor} = thumbAnimationConstants;
    if (!activeThumbStyle || !thumbStyle) {
      return defaultScaleFactor;
    }

    const scaleRatioFromSize = Number(activeThumbStyle.height) / Number(thumbStyle.height);
    return scaleRatioFromSize || defaultScaleFactor;
  };

  const animateScale = (toValue: number) => {
    const {duration} = thumbAnimationConstants;
    Animated.timing(thumbScaleAnimation.current, {
      toValue,
      duration,
      useNativeDriver: true
    }).start();
  };

  const scaleThumb = (start: boolean) => {
    const scaleFactor = start ? calculateThumbScale() : 1;
    animateScale(scaleFactor);
  };

  return (
    <Animated.View
    // @ts-expect-error
      ref={thumbRef}
      {...others}
      hitSlop={thumbHitSlop}
      onTouchStart={_onTouchStart}
      onTouchEnd={_onTouchEnd}
      style={[
        styles.thumb,
        disabled && styles.disabledThumb,
        thumbStyle,
        {
          backgroundColor: disabled ? DEFAULT_COLOR : thumbTintColor || ACTIVE_COLOR
        },
        {
          transform: [
            {
              scale: thumbScaleAnimation.current
            }
          ]
        }
      ]}
    />
  );
});

export default Thumb;

const styles = StyleSheet.create({
  thumb: {
    position: 'absolute',
    width: THUMB_SIZE,
    height: THUMB_SIZE,
    borderRadius: THUMB_SIZE / 2,
    borderWidth: BORDER_WIDTH,
    borderColor: Colors.white,
    shadowColor: Colors.rgba(Colors.black, 0.3),
    shadowOffset: {width: 0, height: 0},
    shadowOpacity: 0.9,
    shadowRadius: SHADOW_RADIUS,
    elevation: 2
  },
  disabledThumb: {
    borderColor: Colors.$backgroundElevated
  },
  activeThumb: {
    width: THUMB_SIZE + 16,
    height: THUMB_SIZE + 16,
    borderRadius: (THUMB_SIZE + 16) / 2,
    borderWidth: BORDER_WIDTH
  }
});

import _ from 'lodash';
import React, {PureComponent} from 'react';
import {
  StyleSheet,
  PanResponder,
  AccessibilityInfo,
  Animated,
  StyleProp,
  ViewStyle,
  PanResponderGestureState,
  GestureResponderEvent,
  LayoutChangeEvent,
  AccessibilityActionEvent,
  AccessibilityRole,
  View as RNView
} from 'react-native';
import {Constants, asBaseComponent} from '../../commons/new';
import {extractAccessibilityProps} from '../../commons/modifiers';
import {Colors} from '../../style';
import View from '../view';
import IncubatorSlider from '../../incubator/slider';
import {SliderProps} from './types';
import Thumb from './Thumb';

const TRACK_SIZE = 6;
const THUMB_SIZE = 24;
const SHADOW_RADIUS = 4;
const DEFAULT_COLOR = Colors.$backgroundDisabled;
const ACTIVE_COLOR = Colors.$backgroundPrimaryHeavy;
const INACTIVE_COLOR = Colors.$backgroundNeutralMedium;
const MIN_RANGE_GAP = 4;

type InternalSliderProps = SliderProps & typeof defaultProps;

interface State {
  containerSize: Measurements;
  trackSize: Measurements;
  thumbSize: Measurements;
  thumbActiveAnimation: Animated.Value;
  measureCompleted: boolean;
}

type Measurements = {
  width: number;
  height: number;
};

type ThumbStyle = {style?: StyleProp<ViewStyle>; left?: number};

type MinTrackStyle = {style?: StyleProp<ViewStyle>; width?: number; left?: number};

type MeasuredVariableName = 'containerSize' | 'trackSize' | 'thumbSize';

const defaultProps = {
  value: 0,
  minimumValue: 0,
  maximumValue: 1,
  step: 0,
  thumbHitSlop: {top: 10, bottom: 10, left: 24, right: 24},
  useGap: true
};

/**
 * @description: A Slider component
 * @example: https://github.com/wix/react-native-ui-lib/blob/master/demo/src/screens/componentScreens/SliderScreen.tsx
 * @gif: https://github.com/wix/react-native-ui-lib/blob/master/demo/showcase/Slider/Slider.gif?raw=true
 */
class Slider extends PureComponent<InternalSliderProps, State> {
  static displayName = 'Slider';

  static defaultProps = defaultProps;

  private thumb = React.createRef<RNView>();
  private minThumb = React.createRef<RNView>();
  private activeThumbRef: React.RefObject<RNView | null>;
  private panResponder;

  private minTrack = React.createRef<RNView>();
  private _minTrackStyles: MinTrackStyle = {};

  private _x = 0;
  private _x_min = 0;
  private lastDx = 0;

  private initialValue = this.getRoundedValue(this.getInitialValue());
  private minInitialValue = this.getRoundedValue(this.props.initialMinimumValue || this.props.minimumValue);
  private lastValue = this.initialValue;
  private lastMinValue = this.minInitialValue;

  private _thumbStyles: ThumbStyle = {};
  private _minThumbStyles: ThumbStyle = {left: this.minInitialValue};

  private initialThumbSize: Measurements = {width: THUMB_SIZE, height: THUMB_SIZE};
  private containerSize: Measurements | undefined;
  private trackSize: Measurements | undefined;
  private thumbSize: Measurements | undefined;
  private dimensionsChangeListener: any;

  private didMount: boolean;

  constructor(props: InternalSliderProps) {
    super(props);

    this.activeThumbRef = this.thumb;
    this.didMount = false;

    this.state = {
      containerSize: {width: 0, height: 0},
      trackSize: {width: 0, height: 0},
      thumbSize: {width: 0, height: 0},
      thumbActiveAnimation: new Animated.Value(1),
      measureCompleted: false
    };

    this.checkProps(props);

    this.panResponder = PanResponder.create({
      onMoveShouldSetPanResponder: this.handleMoveShouldSetPanResponder,
      onPanResponderGrant: this.handlePanResponderGrant,
      onPanResponderMove: this.handlePanResponderMove,
      onPanResponderRelease: this.handlePanResponderEnd,
      onStartShouldSetPanResponder: () => true,
      onPanResponderEnd: () => true,
      onPanResponderTerminationRequest: () => false
    });
  }

  reset() {
    // NOTE: used with ref
    this.lastValue = this.initialValue;
    this.lastMinValue = this.minInitialValue;
    this.lastDx = 0;

    this.setActiveThumb(this.thumb);
    this.set_x(this.getXForValue(this.initialValue));
    this.moveTo(this._x);

    if (this.props.useRange) {
      this.setActiveThumb(this.minThumb);
      this.set_x(this.getXForValue(this.minInitialValue));
      this.moveMinTo(this._x_min);
    }

    this.props.onReset?.();
  }

  getInitialValue() {
    const {useRange, initialMaximumValue, value, maximumValue} = this.props;
    return useRange ? initialMaximumValue || maximumValue : value;
  }

  checkProps(props: InternalSliderProps) {
    const {useRange, minimumValue, maximumValue, value} = props;
    if (minimumValue > maximumValue) {
      console.warn('Slider minimumValue must be lower than maximumValue');
    }
    if (!useRange && (value < minimumValue || value > maximumValue)) {
      console.warn('Slider value is not in range');
    }
  }

  getAccessibilityProps() {
    const {disabled} = this.props;

    return {
      accessibilityLabel: 'Slider',
      accessible: true,
      accessibilityRole: 'adjustable' as AccessibilityRole,
      accessibilityState: disabled ? {disabled} : undefined,
      accessibilityActions: [
        {name: 'increment', label: 'increment'},
        {name: 'decrement', label: 'decrement'}
      ],
      ...extractAccessibilityProps(this.props)
    };
  }

  componentDidUpdate(prevProps: SliderProps, prevState: State) {
    const {useRange, value, initialMinimumValue} = this.props;

    if (!useRange && prevProps.value !== value) {
      this.initialValue = this.getRoundedValue(value);

      // set position for new value
      this._x = this.getXForValue(this.initialValue);
      this.moveTo(this._x);
    }

    if (prevState.measureCompleted !== this.state.measureCompleted) {
      this.initialThumbSize = this.state.thumbSize; // for thumb enlargement

      // set initial position
      this._x = this.getXForValue(this.initialValue);
      this._x_min = this.getXForValue(this.minInitialValue);
      this.moveTo(this._x);

      if (useRange && initialMinimumValue) {
        this.moveMinTo(this._x_min);
      }

      this.didMount = true;
    }
  }

  componentDidMount() {
    this.dimensionsChangeListener = Constants.addDimensionsEventListener(this.onOrientationChanged);
  }

  componentWillUnmount() {
    Constants.removeDimensionsEventListener(this.dimensionsChangeListener || this.onOrientationChanged);
  }

  /* Gesture Recognizer */

  handleMoveShouldSetPanResponder = () => {
    return true;
  };

  handlePanResponderGrant = () => {
    this.lastDx = 0;
    this.onSeekStart();
  };

  handlePanResponderMove = (_e: GestureResponderEvent, gestureState: PanResponderGestureState) => {
    const {disabled} = this.props;
    if (disabled) {
      return;
    }
    // dx = accumulated distance since touch start
    const dx = gestureState.dx * (Constants.isRTL && !this.disableRTL ? -1 : 1);
    this.update(dx - this.lastDx);
    this.lastDx = dx;
  };

  handlePanResponderEnd = () => {
    this.bounceToStep();
    this.onSeekEnd();
  };

  /* Actions */

  setActiveThumb = (ref: React.RefObject<RNView | null>) => {
    this.activeThumbRef = ref;
  };

  get_x() {
    if (this.isDefaultThumbActive()) {
      return this._x;
    } else {
      return this._x_min;
    }
  }

  set_x(x: number) {
    if (this.isDefaultThumbActive()) {
      this._x = x;
    } else {
      this._x_min = x;
    }
  }

  update(dx: number) {
    // calc x in range (instead of: this._x += dx)
    let x = this.get_x();
    x += dx;
    x = Math.max(Math.min(x, this.state.trackSize.width), 0);

    this.set_x(x);
    this.moveTo(x);
    if (!this.props.useRange) {
      this.updateValue(x);
    }
  }

  bounceToStep() {
    if (this.props.step > 0) {
      const value = this.getValueForX(this.get_x());
      const roundedValue = this.getRoundedValue(value);
      const x = this.getXForValue(roundedValue);

      this.set_x(x);
      this.moveTo(x);
    }
  }

  updateValue(x: number) {
    const value = this.getValueForX(x);

    if (this.props.useRange) {
      this.onRangeChange(value);
    } else {
      this.onValueChange(value);
    }
  }

  moveTo(x: number) {
    if (this.isDefaultThumbActive()) {
      if (this.thumb.current) {
        const {useRange, useGap} = this.props;
        const {trackSize, thumbSize} = this.state;

        const nonOverlappingTrackWidth = trackSize.width - this.initialThumbSize.width;
        const _x = this.shouldForceLTR ? trackSize.width - x : x; // adjust for RTL
        const left = trackSize.width === 0 ? _x : (_x * nonOverlappingTrackWidth) / trackSize.width; // do not render above prefix\suffix icon\text

        if (useRange) {
          const minThumbPosition = this._minThumbStyles?.left as number;
          if (
            (useGap && left > minThumbPosition + thumbSize.width + MIN_RANGE_GAP) ||
            (!useGap && left >= minThumbPosition)
          ) {
            this._thumbStyles.left = left;

            const width = left - minThumbPosition;
            this._minTrackStyles.width = width;

            if (this.didMount) {
              this.updateValue(x);
            }
          }
        } else {
          this._thumbStyles.left = left;
          this._minTrackStyles.width = Math.min(trackSize.width, x);
        }

        this.thumb.current?.setNativeProps?.(this._thumbStyles);
        this.minTrack.current?.setNativeProps?.(this._minTrackStyles);
      }
    } else {
      this.moveMinTo(x);
    }
  }

  moveMinTo(x: number) {
    const {useGap} = this.props;
    const {trackSize, thumbSize} = this.state;

    if (this.minThumb.current) {
      const nonOverlappingTrackWidth = trackSize.width - this.initialThumbSize.width;
      const _x = this.shouldForceLTR ? nonOverlappingTrackWidth - x : x; // adjust for RTL
      const left = trackSize.width === 0 ? _x : (_x * nonOverlappingTrackWidth) / trackSize.width; // do not render above prefix\suffix icon\text

      const maxThumbPosition = this._thumbStyles?.left as number;
      if (
        (useGap && left < maxThumbPosition - thumbSize.width - MIN_RANGE_GAP) ||
        (!useGap && left <= maxThumbPosition)
      ) {
        this._minThumbStyles.left = left;

        this._minTrackStyles.width = maxThumbPosition - x;
        this._minTrackStyles.left = x;

        this.minThumb.current?.setNativeProps?.(this._minThumbStyles);
        this.minTrack.current?.setNativeProps?.(this._minTrackStyles);

        if (this.didMount) {
          this.updateValue(x);
        }
      }
    }
  }

  updateTrackStepAndStyle = ({nativeEvent}: GestureResponderEvent) => {
    const {step, useRange} = this.props;
    const {trackSize} = this.state;

    const newX = Constants.isRTL && !this.disableRTL ? trackSize.width - nativeEvent.locationX : nativeEvent.locationX;

    if (useRange) {
      if (this.isDefaultThumbActive() && this._minThumbStyles?.left && newX < this._minThumbStyles?.left) {
        // new x is smaller then min but the active thumb is the max
        this.setActiveThumb(this.minThumb);
      } else if (!this.isDefaultThumbActive() && this._thumbStyles.left && newX > this._thumbStyles.left) {
        // new x is bigger then max but the active thumb is the min
        this.setActiveThumb(this.thumb);
      }
    }

    this.set_x(newX);

    if (!useRange) {
      this.updateValue(this.get_x());
    }

    if (step > 0) {
      this.bounceToStep();
    } else {
      this.moveTo(this.get_x());
    }
  };

  /** Values */

  get disableRTL() {
    const {disableRTL, useRange} = this.props;
    if (useRange) {
      // block forceRTL on range slider
      return false;
    }
    return disableRTL;
  }

  shouldForceLTR = Constants.isRTL && this.disableRTL;

  isDefaultThumbActive = () => {
    return this.activeThumbRef === this.thumb;
  };

  getRoundedValue(value: number) {
    const {step} = this.props;
    const v = this.getValueInRange(value);
    return step > 0 ? Math.round(v / step) * step : v;
  }

  getValueInRange(value: number) {
    const {minimumValue, maximumValue} = this.props;
    const v = value < minimumValue ? minimumValue : value > maximumValue ? maximumValue : value;
    return v;
  }

  getXForValue(value: number) {
    const {minimumValue} = this.props;
    const range = this.getRange();
    const relativeValue = minimumValue - value;
    const v = minimumValue < 0 ? Math.abs(relativeValue) : value - minimumValue; // for negatives
    const ratio = v / range;
    const x = ratio * this.state.trackSize.width;
    return x;
  }

  getValueForX(x: number) {
    const {maximumValue, minimumValue, step} = this.props;
    const ratio = x / (this.state.trackSize.width - this.initialThumbSize.width / 2);
    const range = this.getRange();

    if (step) {
      return Math.max(minimumValue, Math.min(maximumValue, minimumValue + Math.round((ratio * range) / step) * step));
    } else {
      return Math.max(minimumValue, Math.min(maximumValue, ratio * range + minimumValue));
    }
  }

  getRange() {
    const {minimumValue, maximumValue} = this.props;
    const range = maximumValue - minimumValue;
    return range;
  }

  /* Events */

  onOrientationChanged = () => {
    this.initialValue = this.lastValue;
    this.minInitialValue = this.lastMinValue;
    this.setState({measureCompleted: false});
  };

  onRangeChange = (value: number) => {
    if (this.isDefaultThumbActive()) {
      this.lastValue = value;
    } else {
      this.lastMinValue = value;
    }

    let values = {min: this.lastMinValue, max: this.lastValue};

    if (Constants.isRTL && this.props.disableRTL) {
      // forceRTL for range slider
      const {maximumValue} = this.props;
      values = {min: maximumValue - this.lastValue, max: maximumValue - this.lastMinValue};
    }

    this.props.onRangeChange?.(values);
  };

  onValueChange = (value: number) => {
    this.lastValue = value;
    this.props.onValueChange?.(value);
  };

  onSeekStart() {
    this.props.onSeekStart?.();
  }

  onSeekEnd() {
    this.props.onSeekEnd?.();
  }

  onContainerLayout = (nativeEvent: LayoutChangeEvent) => {
    this.handleMeasure('containerSize', nativeEvent);
  };

  onTrackLayout = (nativeEvent: LayoutChangeEvent) => {
    this.setState({measureCompleted: false});
    this.handleMeasure('trackSize', nativeEvent);
  };

  onThumbLayout = (nativeEvent: LayoutChangeEvent) => {
    this.handleMeasure('thumbSize', nativeEvent);
  };

  handleTrackPress = (event: GestureResponderEvent) => {
    if (this.props.disabled) {
      return;
    }
    this.onSeekStart();
    this.updateTrackStepAndStyle(event);
    this.onSeekEnd();
  };

  handleMeasure = (name: MeasuredVariableName, {nativeEvent}: LayoutChangeEvent) => {
    const {width, height} = nativeEvent.layout;
    const size = {width, height};
    const currentSize = this[name];

    if (currentSize && width === currentSize.width && height === currentSize.height) {
      return;
    }
    this[name] = size;
    if (this.containerSize && this.thumbSize && this.trackSize) {
      this.setState({
        containerSize: this.containerSize,
        trackSize: this.trackSize,
        thumbSize: this.thumbSize
      },
      () => {
        this.setState({measureCompleted: true});
      });
    }
  };

  onAccessibilityAction = (event: AccessibilityActionEvent) => {
    const {maximumValue, minimumValue, step} = this.props;
    const value = this.getValueForX(this._x);
    let newValue;

    switch (event.nativeEvent.actionName) {
      case 'increment':
        newValue = value !== maximumValue ? value + step : value;
        break;
      case 'decrement':
        newValue = value !== minimumValue ? value - step : value;
        break;
      default:
        newValue = value;
        break;
    }

    this._x = this.getXForValue(newValue);
    this.updateValue(this._x);
    this.moveTo(this._x);
    AccessibilityInfo.announceForAccessibility?.(`New value ${newValue}`);
  };

  onMinTouchStart = () => {
    this.setActiveThumb(this.minThumb);
  };

  onTouchStart = () => {
    this.setActiveThumb(this.thumb);
  };

  getThumbProps = () => {
    const {thumbStyle, activeThumbStyle, disableActiveStyling, disabled, thumbTintColor, thumbHitSlop} = this.props;
    const {thumbSize} = this.state;
    const verticalHitslop = Math.max(0, (48 - thumbSize.height) / 2);
    const horizontalHitslop = Math.max(0, (48 - thumbSize.width) / 2);

    const calculatedHitSlop = thumbSize.width > 0
      ? {
        top: verticalHitslop,
        bottom: verticalHitslop,
        left: horizontalHitslop,
        right: horizontalHitslop
      }
      : undefined;

    return {
      disabled,
      thumbTintColor,
      thumbStyle,
      activeThumbStyle,
      disableActiveStyling,
      thumbHitSlop: thumbHitSlop ?? calculatedHitSlop,
      onLayout: this.onThumbLayout
    };
  };

  /* Renders */
  renderMinThumb = () => {
    return (
      <Thumb
        {...this.getThumbProps()}
        ref={this.minThumb}
        onTouchStart={this.onMinTouchStart}
        {...this.panResponder.panHandlers}
      />
    );
  };

  renderThumb = () => {
    return (
      <Thumb
        {...this.getThumbProps()}
        ref={this.thumb}
        onTouchStart={this.onTouchStart}
        {...this.panResponder.panHandlers}
      />
    );
  };

  renderTrack() {
    const {
      trackStyle,
      renderTrack,
      disabled,
      minimumTrackTintColor = ACTIVE_COLOR,
      maximumTrackTintColor = DEFAULT_COLOR
    } = this.props;

    return _.isFunction(renderTrack) ? (
      <View style={[styles.track, {backgroundColor: maximumTrackTintColor}, trackStyle]} onLayout={this.onTrackLayout}>
        {renderTrack()}
      </View>
    ) : (
      <View>
        <View
          style={[
            styles.track,
            trackStyle,
            {
              backgroundColor: disabled ? INACTIVE_COLOR : maximumTrackTintColor
            }
          ]}
          onLayout={this.onTrackLayout}
        />
        <View
          ref={this.minTrack}
          style={[
            styles.track,
            trackStyle,
            styles.minimumTrack,
            this.shouldForceLTR && styles.trackDisableRTL,
            {
              backgroundColor: disabled ? DEFAULT_COLOR : minimumTrackTintColor
            }
          ]}
        />
      </View>
    );
  }

  renderRangeThumb() {
    const {useRange, useGap} = this.props;
    if (useRange) {
      if (useGap) {
        return this.renderMinThumb();
      }
      return <View style={{zIndex: this.isDefaultThumbActive() ? 0 : 1, top: '-50%'}}>{this.renderMinThumb()}</View>;
    }
  }

  render() {
    const {containerStyle, testID, migrate} = this.props;

    if (migrate) {
      return <IncubatorSlider {...this.props}/>;
    }

    return (
      <View
        style={[styles.container, containerStyle]}
        onLayout={this.onContainerLayout}
        onAccessibilityAction={this.onAccessibilityAction}
        testID={testID}
        {...this.getAccessibilityProps()}
      >
        {this.renderTrack()}
        <View style={styles.touchArea} onTouchEnd={this.handleTrackPress}/>
        {this.renderRangeThumb()}
        {this.renderThumb()}
      </View>
    );
  }
}

