import {isUndefined} from 'lodash';
import React, {PureComponent} from 'react';
import {StyleSheet, AccessibilityInfo, AccessibilityProps, AccessibilityActionEvent} from 'react-native';
import {Typography, Spacings, Colors, Shadows, BorderRadiuses} from '../../style';
import {asBaseComponent} from '../../commons/new';
import View from '../view';
import Text from '../text';
import Button from '../button';
import Assets from '../../assets';

enum ActionType {
  MINUS = 'minus',
  PLUS = 'plus'
}

export type StepperType = 'default' | 'floating';

const DEFAULT_STEP = 1;

interface Props {
  /**
   * Stepper style type
   */
  type?: StepperType;
  /**
   * Stepper value.
   */
  value?: number;
  /**
   * Minimum value.
   */
  minValue?: number;
  /**
   * Maximum value.
   */
  maxValue?: number;
  /**
   * The step to increase and decrease by (default is 1)
   */
  step?: number;
  /**
   * On value change callback function
   */
  onValueChange?: (value: number, testID?: string) => void;
  /**
   * disables interaction with the stepper
   */
  disabled?: boolean;
  /**
   * Renders a small sized Stepper
   */
  small?: boolean;
  /**
   * Component accessibility label
   */
  accessibilityLabel?: string;
  /**
   * Test id for component
   */
  testID?: string;
}
export type StepperProps = Props;

interface State {
  currentValue: number;
}

/**
 * @description: A stepper component
 * @example: https://github.com/wix/react-native-ui-lib/blob/master/demo/src/screens/componentScreens/StepperScreen.js
 */
class Stepper extends PureComponent<Props, State> {
  constructor(props: Props) {
    super(props);

    const {value, minValue = 0, maxValue = 1, testID} = props;
    let initialValue = 0;
    if (minValue) {
      initialValue = minValue;
    }
    if (value !== undefined) {
      initialValue = value;
    }

    this.state = {
      currentValue: initialValue
    };

    if (initialValue < minValue) {
      console.warn(`Stepper: ${testID}'s minimum value: ${minValue} is greater than current value: ${initialValue}`);
    }
    if (initialValue > maxValue) {
      console.warn(`Stepper: ${testID}'s maximum value: ${maxValue} is less than current value: ${initialValue}`);
    }
    if (minValue > maxValue) {
      console.warn(`Stepper: ${testID}'s minimum value: ${minValue} is greater than the maximum value: ${maxValue}`);
    }
  }

  static getDerivedStateFromProps(nextProps: Props, prevState: State) {
    if (!isUndefined(nextProps.value) && prevState.currentValue !== nextProps.value) {
      return {currentValue: nextProps.value};
    }
    return null;
  }

  getAccessibilityProps(): AccessibilityProps {
    const {currentValue} = this.state;
    const {accessibilityLabel} = this.props;
    const labelSuffix = `value = ${currentValue}`;

    return {
      accessibilityLabel: accessibilityLabel ? `${accessibilityLabel}, ${labelSuffix}` : `Stepper, ${labelSuffix}`,
      accessible: true,
      accessibilityRole: 'adjustable',
      accessibilityActions: [{name: 'decrement'}, {name: 'increment'}],
      onAccessibilityAction: this.onAccessibilityAction
    };
  }

  onAccessibilityAction = (event: AccessibilityActionEvent) => {
    const {currentValue} = this.state;
    const {step = DEFAULT_STEP} = this.props;
    const eventMsgContext = event.nativeEvent.actionName === 'decrement' ? 'Minimum' : 'Maximum';
    const stepperLimitMsg = `${eventMsgContext} stepper value, ${currentValue}, reached`;

    switch (event.nativeEvent.actionName) {
      case 'decrement':
        this.accessibilityActionHandler(ActionType.MINUS, currentValue - step, stepperLimitMsg);
        break;
      case 'increment':
        this.accessibilityActionHandler(ActionType.PLUS, currentValue + step, stepperLimitMsg);
        break;
      default:
        break;
    }
  };

  accessibilityActionHandler(actionType: ActionType, newStepperValue: number, actionLimitMsg: string) {
    if (this.allowStepChange(actionType)) {
      this.handleStepChange(actionType);
      AccessibilityInfo.announceForAccessibility?.(newStepperValue.toString());
    } else {
      AccessibilityInfo.announceForAccessibility?.(actionLimitMsg);
    }
  }

  allowStepChange(actionType: ActionType) {
    const {minValue, maxValue} = this.props;
    const {currentValue} = this.state;

    if (actionType === ActionType.PLUS) {
      return maxValue === undefined || currentValue < maxValue;
    }
    if (actionType === ActionType.MINUS) {
      return minValue === undefined || currentValue > minValue;
    }
  }

  handleStepChange(actionType: ActionType) {
    const {testID, step = DEFAULT_STEP} = this.props;
    const {currentValue} = this.state;
    let newCurrent = currentValue;

    if (actionType === ActionType.MINUS) {
      newCurrent = currentValue - step;
    } else {
      newCurrent = currentValue + step;
    }

    this.setState({currentValue: newCurrent});
    this.props.onValueChange?.(newCurrent, testID);
  }

  renderButton(actionType: ActionType) {
    const {type, disabled, small, testID} = this.props;
    const allowStepChange = this.allowStepChange(actionType);
    const isFloatingStepper = type === 'floating';
    const minusButton = isFloatingStepper
      ? Assets.internal.icons.minusSmall
      : small
        ? Assets.internal.icons.minusOutlineSmall
        : Assets.internal.icons.minusOutline;
    const plusButton = isFloatingStepper
      ? Assets.internal.icons.plusSmall
      : small
        ? Assets.internal.icons.plusOutlineSmall
        : Assets.internal.icons.plusOutline;

    return (
      <Button
        link
        color={isFloatingStepper ? Colors.$iconDefault : undefined}
        iconSource={actionType === ActionType.MINUS ? minusButton : plusButton}
        disabled={disabled || !allowStepChange}
        onPress={() => this.handleStepChange(actionType)}
        testID={actionType === ActionType.MINUS ? `${testID}.minusStep` : `${testID}.plusStep`}
      />
    );
  }

  render() {
    const {type, disabled, testID} = this.props;
    const {currentValue} = this.state;

    return (
      <View row centerV {...this.getAccessibilityProps()} style={type === 'floating' && styles.containerFloating}>
        {this.renderButton(ActionType.MINUS)}
        <Text
          $textDefault
          $textDisabled={disabled}
          style={[Typography.text70M, type === 'floating' ? styles.textFloating : styles.textDefault]}
          testID={`${testID}.currentValue`}
          recorderTag={'unmask'}
        >
          {currentValue}
        </Text>
        {this.renderButton(ActionType.PLUS)}
      </View>
    );
  }
}

const styles = StyleSheet.create({
  containerFloating: {
    borderRadius: BorderRadiuses.br100,
    backgroundColor: Colors.$backgroundElevated,
    borderWidth: 1,
    borderColor: Colors.$outlineDefault,
    paddingHorizontal: Spacings.s3,
    paddingVertical: Spacings.s1,
    ...Shadows.sh10.bottom
  },
  textDefault: {
    marginHorizontal: Spacings.s5
  },
  textFloating: {
    marginHorizontal: Spacings.s2,
    minWidth: Spacings.s6,
    textAlign: 'center'
  }
});

export default asBaseComponent<Props>(Stepper);

import React, {useEffect, useState} from 'react';
import {StyleSheet} from 'react-native';
import Image from '../image';
import {isSvg, isSvgUri, isBase64ImageContent} from '../../utils/imageUtils';

const PostCssPackage = require('../../optionalDependencies').PostCssPackage;

const DEFAULT_SIZE = 16;
export interface SvgImageProps {
  /**
   * the asset tint
   */
  tintColor?: string | null;
  data: any; // TODO: I thought this should be string | React.ReactNode but it doesn't work properly
  style?: object[];
  height?: number;
  width?: number;
  id?: string;
}

function SvgImage(props: SvgImageProps) {
  const {id, data, style = [], tintColor, width, height, ...others} = props;
  const [className] = useState(`svg-${id ? id : new Date().getTime().toString()}`);
  const [svgStyleCss, setSvgStyleCss] = useState<string | undefined>(undefined);

  useEffect(() => {
    if (PostCssPackage) {
      const {postcss, cssjs} = PostCssPackage;
      const styleObj: Record<string, any> = StyleSheet.flatten(style);
      postcss()
        .process({width, height, ...styleObj}, {parser: cssjs})
        .then((style: {css: any}) => {
          const svgPathCss = styleObj?.tintColor ? `path {fill: ${styleObj?.tintColor}}` : '';
          setSvgStyleCss(`.${className} > svg {${style.css}; ${svgPathCss}}`);
        });
    }
  }, [style, className, width, height]);

  if (isSvgUri(data)) {
    return <img {...others} src={data.uri} style={StyleSheet.flatten(style)}/>;
  } else if (isBase64ImageContent(data)) {
    if (tintColor) {
      return (
        <Image
          source={{uri: data}}
          width={DEFAULT_SIZE}
          height={DEFAULT_SIZE}
          style={[style, {tintColor}]}
          {...others}
        />
      );
    }
    return <img {...others} src={data} style={StyleSheet.flatten(style)}/>;
  } else if (data && svgStyleCss) {
    const svgStyleTag = `<style> ${svgStyleCss} </style>`;
    return (
      <div
        style={{
          display: 'flex',
          justifyContent: 'center',
          flexShrink: 0
        }}
        className={className}
        // eslint-disable-next-line react/no-danger
        dangerouslySetInnerHTML={{__html: svgStyleTag + data}}
      />
    );
  }
  return null;
}

SvgImage.displayName = 'IGNORE';
SvgImage.isSvg = isSvg;

export default SvgImage;

import React, {Component} from 'react';
import {StyleSheet, Animated, Easing, StyleProp, ViewStyle, ColorValue} from 'react-native';
import {Colors, BorderRadiuses} from '../../style';
import {Constants, asBaseComponent} from '../../commons/new';
import TouchableOpacity, {TouchableOpacityProps} from '../touchableOpacity';

const INNER_PADDING = 2;
const DEFAULT_WIDTH = 42;
const DEFAULT_HEIGHT = 24;
const DEFAULT_THUMB_SIZE = 20;

export type SwitchProps = TouchableOpacityProps & {
  /**
   * The value of the switch. If true the switch will be turned on. Default value is false
   */
  value?: boolean;
  /**
   * Invoked with the new value when the value changes
   */
  onValueChange?: (value: boolean) => void;
  /**
   * Whether the switch should be disabled
   */
  disabled?: boolean;
  /**
   * The Switch width
   */
  width?: number;
  /**
   * The Switch height
   */
  height?: number;
  /**
   * The Switch background color when it's turned on
   */
  onColor?: ColorValue;
  /**
   * The Switch background color when it's turned off
   */
  offColor?: ColorValue;
  /**
   * The Switch background color when it's disabled
   */
  disabledColor?: ColorValue;
  /**
   * The Switch's thumb color
   */
  thumbColor?: ColorValue;
  /**
   * The Switch's thumb size (width & height)
   */
  thumbSize?: number;
  /**
   * The Switch's thumb style
   */
  thumbStyle?: StyleProp<ViewStyle>;
  style?: StyleProp<ViewStyle>;
  testID?: string;
  id?: string;
}

/**
 * @description: Switch component for toggling boolean value related to some context
 * @example: https://github.com/wix/react-native-ui-lib/blob/master/demo/src/screens/componentScreens/SwitchScreen.tsx
 * @gif: https://github.com/wix/react-native-ui-lib/blob/master/demo/showcase/Switch/Switch.gif?raw=true
 */
class Switch extends Component<SwitchProps> {
  static displayName = 'Switch';

  state = {
    thumbPosition: new Animated.Value(this.props.value ? 1 : 0)
  };

  styles = createStyles(this.props);

  componentDidUpdate(prevProps: SwitchProps) {
    const {value} = this.props;
    if (prevProps.value !== value) {
      this.toggle(value);
    }
  }

  getAccessibilityProps() {
    const {disabled, value} = this.props;

    return {
      accessible: true,
      accessibilityRole: 'switch',
      accessibilityState: {disabled, checked: value}
    };
  }

  toggle(value?: boolean) {
    const {thumbPosition} = this.state;

    Animated.timing(thumbPosition, {
      toValue: value ? 1 : 0,
      duration: 200,
      easing: Easing.bezier(0.77, 0.0, 0.175, 1.0),
      useNativeDriver: true
    }).start();
  }

  onPress = () => {
    const {disabled} = this.props;

    if (!disabled) {
      this.props.onValueChange?.(!this.props.value);
    }
  };

  calcThumbOnPosition() {
    const props = this.props;
    const width = props.width || DEFAULT_WIDTH;
    const thumbSize = props.thumbSize || DEFAULT_THUMB_SIZE;
    let position = width - (2 * INNER_PADDING + thumbSize);
    position *= Constants.isRTL ? -1 : 1;
    return position;
  }

  getSwitchStyle() {
    const {value, onColor, offColor, style: propsStyle, disabled, disabledColor} = this.props;
    const style: SwitchProps['style'] = [this.styles.switch];

    if (disabled) {
      style.push(disabledColor ? {backgroundColor: disabledColor} : this.styles.switchDisabled);
    } else if (value) {
      style.push(onColor ? {backgroundColor: onColor} : this.styles.switchOn);
    } else {
      style.push(offColor ? {backgroundColor: offColor} : this.styles.switchOff);
    }

    style.push(propsStyle);
    return style;
  }

  renderThumb() {
    const {thumbStyle} = this.props;
    const {thumbPosition} = this.state;

    const interpolatedTranslateX = thumbPosition.interpolate({
      inputRange: [0, 1],
      outputRange: [0, this.calcThumbOnPosition()]
    });

    const thumbPositionStyle = {
      transform: [{translateX: interpolatedTranslateX}]
    };

    return <Animated.View style={[this.styles.thumb, thumbPositionStyle, thumbStyle]}/>;
  }

  getAccessibleHitSlop() {
    const {width = DEFAULT_WIDTH, height = DEFAULT_HEIGHT} = this.props;
    const verticalPadding = Math.max(0, (48 - height) / 2);
    const horizontalPadding = Math.max(0, (48 - width) / 2);

    return {
      top: verticalPadding,
      bottom: verticalPadding,
      left: horizontalPadding,
      right: horizontalPadding
    };
  }

  render() {
    const {...others} = this.props;

    return (
      // @ts-ignore
      <TouchableOpacity
        {...this.getAccessibilityProps()}
        activeOpacity={1}
        hitSlop={this.getAccessibleHitSlop()}
        {...others}
        style={this.getSwitchStyle()}
        onPress={this.onPress}
      >
        {this.renderThumb()}
      </TouchableOpacity>
    );
  }
}

function createStyles({
  width = DEFAULT_WIDTH,
  height = DEFAULT_HEIGHT,
  onColor = Colors.$backgroundPrimaryHeavy,
  offColor = Colors.$backgroundNeutralHeavy,
  disabledColor = Colors.$backgroundDisabled,
  thumbColor = Colors.$iconDefaultLight,
  thumbSize = DEFAULT_THUMB_SIZE
}: SwitchProps) {
  return StyleSheet.create({
    switch: {
      width,
      height,
      borderRadius: BorderRadiuses.br100,
      justifyContent: 'center',
      padding: INNER_PADDING
    },
    switchOn: {
      backgroundColor: onColor
    },
    switchOff: {
      backgroundColor: offColor
    },
    switchDisabled: {
      backgroundColor: disabledColor
    },
    thumb: {
      width: thumbSize,
      height: thumbSize,
      borderRadius: thumbSize / 2,
      backgroundColor: thumbColor
    }
  });
}

export default asBaseComponent<SwitchProps>(Switch);

import {ViewStyle} from 'react-native';
import {useComponentDriver, ComponentProps} from '../../testkit/new/Component.driver';
import {usePressableDriver} from '../../testkit/new/usePressable.driver';

export const SwitchDriver = (props: ComponentProps) => {
  const driver = usePressableDriver(useComponentDriver(props));

  const getStyle = () => driver.getElement().props.style as ViewStyle;
  const isDisabled = () => driver.getElement().props.accessibilityState?.disabled === true;
  const isChecked = () => driver.getElement().props.accessibilityState?.checked;

  return {...driver, getStyle, isDisabled, isChecked};
};

import React, {useCallback, useContext, useMemo, useEffect} from 'react';
import {NativeSyntheticEvent, NativeScrollEvent, ScrollViewProps} from 'react-native';
import TabBarContext from './TabBarContext';
import Reanimated, {
  runOnJS,
  useAnimatedReaction,
  useAnimatedRef,
  useAnimatedScrollHandler,
  useSharedValue
} from 'react-native-reanimated';
import {Constants} from '../../commons/new';

const FIX_RTL = Constants.isRTL;

/**
 * @description: TabController's Page Carousel
 * @example: https://github.com/wix/react-native-ui-lib/blob/master/demo/src/screens/componentScreens/TabControllerScreen/index.tsx
 * @notes: You must pass `asCarousel` flag to TabController and render your TabPages inside a PageCarousel
 */
function PageCarousel(props: ScrollViewProps) {
  const {onMomentumScrollEnd, style, ...others} = props;
  const carousel = useAnimatedRef<Reanimated.ScrollView>();
  const {
    itemsCount,
    currentPage,
    targetPage,
    pageWidth,
    // carouselOffset,
    setCurrentIndex
  } = useContext(TabBarContext);
  const initialOffset = useMemo(() => ({x: currentPage.value * pageWidth, y: 0}), []);
  const indexChangeReason = useSharedValue<'byScroll' | 'byPress' | undefined>(undefined);

  const scrollToInitial = useCallback(() => {
    if (Constants.isAndroid && currentPage.value) {
      scrollToItem(currentPage.value);
    }
  }, []);

  const calcOffset = useCallback((offset: number) => {
    'worklet';
    return FIX_RTL ? pageWidth * (itemsCount - 1) - offset : offset;
  },
  [pageWidth, itemsCount]);

  const scrollHandler = useAnimatedScrollHandler({
    onScroll: e => {
      // carouselOffset.value = e.contentOffset.x;
      const xOffset = calcOffset(e.contentOffset.x);
      const newIndex = xOffset / pageWidth;

      if (indexChangeReason.value === 'byPress') {
        // Scroll was immediate and not by gesture
        /* Round is for android when offset value has fraction */
        // targetPage.value = withTiming(Math.round(newIndex));

        indexChangeReason.value = undefined;
      } else {
        targetPage.value = newIndex;
      }
    },
    onMomentumEnd: e => {
      const xOffset = calcOffset(e.contentOffset.x);
      const newPage = Math.round(xOffset / pageWidth);
      indexChangeReason.value = 'byScroll';
      setCurrentIndex(newPage);
    }
  });

  const scrollToItem = useCallback((index: number) => {
    if (indexChangeReason.value === 'byScroll') {
      indexChangeReason.value = undefined;
    } else {
      indexChangeReason.value = 'byPress';
    }

    const actualIndex = FIX_RTL ? itemsCount - index - 1 : index;
    carousel.current?.scrollTo({x: actualIndex * pageWidth, animated: false});
  },
  [pageWidth, itemsCount]);

  useAnimatedReaction(() => {
    return currentPage.value;
  },
  (currIndex, prevIndex) => {
    if (prevIndex !== null && currIndex !== prevIndex) {
      runOnJS(scrollToItem)(currIndex);
    }
  });

  useEffect(() => {
    carousel.current?.scrollTo({x: currentPage.value * pageWidth, animated: false});
  }, [pageWidth]);

  const handleOnMomentumScrollEnd = useCallback((event: NativeSyntheticEvent<NativeScrollEvent>) => {
    onMomentumScrollEnd?.(event);
  }, [onMomentumScrollEnd]);

  const _style = useMemo(() => {
    return [{width: pageWidth}, style];
  }, [pageWidth, style]);

  return (
    <Reanimated.ScrollView
      {...others}
      style={_style}
      ref={carousel}
      horizontal
      pagingEnabled
      showsHorizontalScrollIndicator={false}
      onScroll={scrollHandler}
      scrollEventThrottle={16}
      contentOffset={initialOffset} // iOS only
      onLayout={scrollToInitial} // Android only
      onMomentumScrollEnd={handleOnMomentumScrollEnd} // TODO: workaround for useAnimatedScrollHandler.onMomentumEnd not being called (https://github.com/software-mansion/react-native-reanimated/issues/2735)
    />
  );
}

export default PageCarousel;

import _ from 'lodash';
import React, {useMemo, useContext, useState, useRef, ReactNode} from 'react';
import {StyleSheet, Platform, StyleProp, ViewStyle} from 'react-native';
import Reanimated, {runOnJS, useAnimatedReaction, useAnimatedStyle, interpolate} from 'react-native-reanimated';
import TabBarContext from './TabBarContext';
import TabBarItem, {TabControllerItemProps} from './TabBarItem';
import {
  Constants,
  asBaseComponent,
  forwardRef,
  BaseComponentInjectedProps,
  ForwardRefInjectedProps
} from '../../commons/new';
import View from '../view';
import {Colors, Spacings, Typography} from '../../style';
import FadedScrollView, {FadedScrollViewRef} from '../fadedScrollView';
import {FaderProps} from '../fader';
import useScrollToItem from './useScrollToItem';
import {useDidUpdate} from 'hooks';

const DEFAULT_HEIGHT = 48;

const DEFAULT_LABEL_STYLE = {
  ...Typography.text80M,
  letterSpacing: 0
};

const DEFAULT_SELECTED_LABEL_STYLE = {
  ...Typography.text80M,
  letterSpacing: 0
};

const DEFAULT_FADER_PROPS = {size: 76, tintColor: Colors.$backgroundElevated};

export interface TabControllerBarProps {
  /**
   * The list of tab bar items
   */
  items?: TabControllerItemProps[];
  /**
   * Tab Bar height
   */
  height?: number;
  /**
   * Show Tab Bar bottom shadow
   */
  enableShadow?: boolean;
  /**
   * custom shadow style
   */
  shadowStyle?: StyleProp<ViewStyle>;
  /**
   * custom style for the selected indicator
   */
  indicatorStyle?: StyleProp<ViewStyle>;
  /**
   * custom label style
   */
  labelStyle?: TabControllerItemProps['labelStyle'];
  /**
   * custom selected label style
   */
  selectedLabelStyle?: TabControllerItemProps['selectedLabelStyle'];
  /**
   * the default label color
   */
  labelColor?: string;
  /**
   * the selected label color
   */
  selectedLabelColor?: string;
  /**
   * whether to change the text to uppercase
   */
  uppercase?: boolean;
  /**
   * icon tint color
   */
  iconColor?: string;
  /**
   * icon selected tint color
   */
  selectedIconColor?: string;
  /**
   * TODO: rename to feedbackColor
   * Apply background color on press for TouchableOpacity
   */
  activeBackgroundColor?: string;
  /**
   * The TabBar background Color
   */
  backgroundColor?: string;
  /**
   * Props for the start \ end faders
   */
  faderProps?: Pick<FaderProps, 'size' | 'tintColor'>;
  /**
   * The TabBar container width
   */
  containerWidth?: number;
  /**
   * Pass to center selected item
   */
  centerSelected?: boolean;
  /**
   * Whether the tabBar should be spread (default: true)
   */
  spreadItems?: boolean;
  /**
   * The indicator insets (default: Spacings.s4, set to 0 to make it wide as the item)
   */
  indicatorInsets?: number;
  /**
   * Send to get a constant width of the indicator (overrides indicatorInsets)
   */
  indicatorWidth?: number;
  /**
   * Additional styles for the container
   */
  containerStyle?: StyleProp<ViewStyle>;
  /**
   * Used as a testing identifier
   */
  testID?: string;
}

type ChildProps = React.ReactElement<TabControllerItemProps>;

interface Props extends TabControllerBarProps, BaseComponentInjectedProps, ForwardRefInjectedProps {
  children?: ChildProps[] | ChildProps;
}

/**
 * @description: TabController's TabBar component
 * @example: https://github.com/wix/react-native-ui-lib/blob/master/demo/src/screens/componentScreens/TabControllerScreen/index.tsx
 */
const TabBar = (props: Props) => {
  const {
    items: propsItems,
    height,
    enableShadow,
    shadowStyle: propsShadowStyle,
    indicatorStyle,
    labelStyle = DEFAULT_LABEL_STYLE,
    selectedLabelStyle = DEFAULT_SELECTED_LABEL_STYLE,
    labelColor,
    selectedLabelColor,
    uppercase,
    iconColor,
    selectedIconColor,
    activeBackgroundColor,
    backgroundColor = Colors.$backgroundElevated,
    faderProps = DEFAULT_FADER_PROPS,
    containerWidth: propsContainerWidth,
    centerSelected,
    spreadItems = true,
    indicatorInsets = Spacings.s4,
    indicatorWidth,
    containerStyle,
    testID
  } = props;

  const tabBar = useRef<FadedScrollViewRef>(null);
  const [key, setKey] = useState<string>(generateKey(Constants.orientation, labelColor, selectedLabelColor));
  const context = useContext(TabBarContext);
  const {items: contextItems, currentPage, targetPage, containerWidth: contextContainerWidth} = context;
  const containerWidth: number = useMemo(() => {
    return propsContainerWidth || contextContainerWidth;
  }, [propsContainerWidth, contextContainerWidth]);
  const items = useMemo(() => {
    return contextItems || propsItems;
  }, [contextItems, propsItems]);
  const itemsCount = items?.length || 0;

  const {
    onItemLayout,
    itemsWidthsAnimated,
    itemsOffsetsAnimated,
    // itemsWidths,
    // itemsOffsets,
    focusIndex,
    reset,
    onContentSizeChange,
    onLayout
  } = useScrollToItem({
    // @ts-expect-error TODO: typing bug
    scrollViewRef: tabBar,
    itemsCount,
    selectedIndex: currentPage.value,
    containerWidth,
    offsetType: centerSelected ? useScrollToItem.offsetType.CENTER : useScrollToItem.offsetType.DYNAMIC
  });

  useAnimatedReaction(() => {
    return Math.round(currentPage.value);
  },
  (currIndex, prevIndex) => {
    if (prevIndex !== null && currIndex !== prevIndex) {
      runOnJS(focusIndex)(currIndex);
    }
  });

  const tabBarItems = useMemo((): ReactNode => {
    return _.map(items, (item, index) => {
      return (
        <TabBarItem
          labelColor={labelColor}
          selectedLabelColor={selectedLabelColor}
          labelStyle={labelStyle}
          selectedLabelStyle={selectedLabelStyle}
          uppercase={uppercase}
          iconColor={iconColor}
          selectedIconColor={selectedIconColor}
          backgroundColor={backgroundColor}
          activeBackgroundColor={activeBackgroundColor}
          {...item}
          {...context}
          key={`${index}_${item.label}`}
          index={index}
          onLayout={onItemLayout}
          spreadItems={spreadItems}
        />
      );
    });
  }, [
    items,
    labelColor,
    selectedLabelColor,
    labelStyle,
    selectedLabelStyle,
    uppercase,
    iconColor,
    selectedIconColor,
    backgroundColor,
    activeBackgroundColor,
    centerSelected,
    onItemLayout,
    spreadItems
  ]);

  const _indicatorTransitionStyle = useAnimatedStyle(() => {
    const value = targetPage.value;
    let width, marginHorizontal;
    if (indicatorWidth) {
      width = indicatorWidth;
      marginHorizontal = interpolate(value,
        itemsWidthsAnimated.value.map((_v: number, i: number) => i),
        itemsWidthsAnimated.value.map((v: number) => (v - indicatorWidth) / 2));
    } else {
      marginHorizontal = indicatorInsets;
      width = interpolate(value,
        itemsWidthsAnimated.value.map((_v: number, i: number) => i),
        itemsWidthsAnimated.value.map((v: number) => v - 2 * indicatorInsets));
    }

    const left = interpolate(value,
      itemsOffsetsAnimated.value.map((_v: any, i: number) => i),
      itemsOffsetsAnimated.value);

    return {
      marginHorizontal,
      width,
      left
    };
  });

  const shadowStyle = useMemo(() => {
    return enableShadow ? propsShadowStyle || styles.containerShadow : undefined;
  }, [enableShadow, propsShadowStyle]);

  const _containerStyle = useMemo(() => {
    return [styles.container, shadowStyle, {width: containerWidth}, containerStyle];
  }, [shadowStyle, containerWidth, containerStyle]);

  const tabBarContainerStyle = useMemo(() => {
    return [styles.tabBar, spreadItems && styles.spreadItems, !_.isUndefined(height) && {height}, {backgroundColor}];
  }, [height, backgroundColor]);

  const scrollViewContainerStyle = useMemo(() => {
    return {minWidth: containerWidth};
  }, [containerWidth]);

  useDidUpdate(() => {
    if (tabBar.current?.isScrollEnabled()) {
      focusIndex(currentPage.value);
    } else {
      reset();
      setKey(generateKey(Constants.orientation, labelColor, selectedLabelColor));
    }
  }, [containerWidth]);

  useDidUpdate(() => {
    setKey(generateKey(Constants.orientation, labelColor, selectedLabelColor));
  }, [labelColor, selectedLabelColor]);

  return (
    <View style={_containerStyle} key={key} bg-$backgroundElevated>
      <FadedScrollView
        ref={tabBar}
        horizontal
        showsHorizontalScrollIndicator={false}
        showStartFader
        startFaderProps={faderProps}
        showEndFader
        endFaderProps={faderProps}
        contentContainerStyle={scrollViewContainerStyle}
        testID={testID}
        onContentSizeChange={onContentSizeChange}
        onLayout={onLayout}
      >
        <View style={tabBarContainerStyle} accessibilityRole={Constants.isIOS ? 'tabbar' : 'tablist'} >{tabBarItems}</View>
        {itemsCount > 1 && (
          <Reanimated.View style={[styles.selectedIndicator, indicatorStyle, _indicatorTransitionStyle]}/>
        )}
      </FadedScrollView>
    </View>
  );
};

TabBar.displayName = 'TabController.TabBar';

const styles = StyleSheet.create({
  container: {
    zIndex: 100
  },
  tabBar: {
    height: DEFAULT_HEIGHT,
    flexDirection: 'row',
    justifyContent: 'space-between'
  },
  tab: {
    flex: 1,
    alignItems: 'center',
    justifyContent: 'center'
  },
  selectedIndicator: {
    position: 'absolute',
