interface Props extends TabControllerItemProps {
  index: number;
  targetPage: any; // TODO: typescript?
  currentPage: Reanimated.Adaptable<number>;
  onLayout?: (event: LayoutChangeEvent, index: number) => void;
}

/**
 * @description: TabController's TabBarItem
 * @example: https://github.com/wix/react-native-ui-lib/blob/master/demo/src/screens/componentScreens/TabControllerScreen/index.tsx
 * @notes: Must be rendered as a direct child of TabController.TabBar.
 */
export default function TabBarItem({
  index,
  label,
  labelColor = DEFAULT_LABEL_COLOR,
  selectedLabelColor = DEFAULT_SELECTED_LABEL_COLOR,
  labelStyle,
  labelProps,
  selectedLabelStyle,
  icon,
  badge,
  leadingAccessory,
  trailingAccessory,
  uppercase,
  activeOpacity = 0.9,
  backgroundColor = Colors.$backgroundElevated,
  activeBackgroundColor,
  testID,
  ignore,
  style,
  spreadItems,
  onPress,
  ...props
}: Props) {
  const {currentPage, setCurrentIndex} = useContext(TabBarContext);
  const itemRef = useRef(undefined);
  const itemWidth = useRef(props.width);
  const isPressed = useSharedValue(false);
  // JSON.parse(JSON.stringify is due to an issue with reanimated
  const sharedLabelStyle = useSharedValue(JSON.parse(JSON.stringify(StyleSheet.flatten(labelStyle))));
  const sharedSelectedLabelStyle = useSharedValue(JSON.parse(JSON.stringify(StyleSheet.flatten(selectedLabelStyle))));
  const [isSelected, setIsSelected] = useState(currentPage.value === index);

  // NOTE: We clone these color values in refs because they might contain a PlatformColor value
  //       which throws an error (see https://github.com/software-mansion/react-native-reanimated/issues/3164)
  const inactiveColor = useRef(_.cloneDeep(labelColor));
  const activeColor = useRef(_.cloneDeep(!ignore ? selectedLabelColor : inactiveColor.current));

  useEffect(() => {
    if (props.width) {
      props.onLayout?.({nativeEvent: {layout: {x: 0, y: 0, width: itemWidth.current, height: 0}}} as LayoutChangeEvent,
        index);
    }
  }, []);

  useAnimatedReaction(() => currentPage.value === index, (isSelected, prevIsSelected) => {
    if (isSelected !== prevIsSelected) {
      runOnJS(setIsSelected)(isSelected);
    }
  });

  const onLayout = useCallback((event: LayoutChangeEvent) => {
    const {width} = event.nativeEvent.layout;

    if (!itemWidth.current && itemRef?.current) {
      itemWidth.current = width;
      // @ts-ignore
      itemRef.current?.setNativeProps?.({style: {width, paddingHorizontal: null, flex: null}});
      props.onLayout?.(event, index);
    }
  },
  [index, props.onLayout]);

  const animatedLabelStyle = useAnimatedStyle(() => {
    const isActive = currentPage.value === index;
    return isActive ? sharedSelectedLabelStyle.value : sharedLabelStyle.value;
  }, [currentPage]);

  const animatedLabelColorStyle = useAnimatedStyle(() => {
    const isActive = currentPage.value === index;
    return {
      color: isActive ? activeColor.current : inactiveColor.current
    };
  });

  const animatedIconStyle = useAnimatedStyle(() => {
    const isActive = currentPage.value === index;
    return {
      tintColor: isActive ? activeColor.current : inactiveColor.current
    };
  });

  const pressStyle = useAnimatedStyle(() => {
    return {
      backgroundColor: isPressed.value ? activeBackgroundColor : backgroundColor,
      opacity: isPressed.value ? activeOpacity : 1
    };
  });

  const _style = useMemo(() => {
    const flex = Constants.isWeb ? (spreadItems ? 1 : undefined) : 1;
    const constantWidthStyle = itemWidth.current ? {flex: 0, width: itemWidth.current} : undefined;
    return [styles.tabItem, {flex}, style, constantWidthStyle, pressStyle];
  }, [style, spreadItems]);

  const accessibilityState = useMemo(() => ({selected: isSelected}), [isSelected]);

  const gesture = Gesture.Tap()
    .maxDuration(60000)
    .onEnd(() => {
      if (!ignore) {
        setCurrentIndex(index);
      }

      onPress && runOnJS(onPress)(index);
    })
    .onFinalize(() => {
      isPressed.value = false;
    })
    .onTouchesDown(() => {
      isPressed.value = true;
    });

  return (
    <GestureDetector gesture={gesture}>
      <View
        reanimated
        // @ts-expect-error
        ref={itemRef}
        style={_style}
        onLayout={onLayout}
        testID={testID}
        accessible
        accessibilityRole="tab"
        accessibilityState={accessibilityState}
      >
        {leadingAccessory}
        {icon && (
          <Reanimated.Image
            source={icon}
            style={[!_.isUndefined(label) && styles.tabItemIconWithLabel, animatedIconStyle]}
          />
        )}
        {!_.isEmpty(label) && (
          <Reanimated.Text
            {...labelProps}
            fsTagName={'unmask'}
            style={[styles.tabItemLabel, labelStyle, animatedLabelStyle, animatedLabelColorStyle]}
          >
            {uppercase ? _.toUpper(label) : label}
          </Reanimated.Text>
        )}
        {badge && (
          <Badge backgroundColor={Colors.$backgroundDangerHeavy} size={20} {...badge} containerStyle={styles.badge}/>
        )}
        {trailingAccessory}
      </View>
    </GestureDetector>
  );
}

const styles = StyleSheet.create({
  tabItem: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
    paddingHorizontal: Spacings.s4
  },
  tabItemLabel: {
    ...Typography.text80
  },
  tabItemIconWithLabel: {
    marginRight: 10
  },
  badge: {
    marginLeft: Spacings.s1
  }
});

import React, {PropsWithChildren, useCallback, useContext, useState, useMemo, type JSX} from 'react';
import {type StyleProp, StyleSheet, type ViewStyle} from 'react-native';
import Reanimated, {useAnimatedStyle, useAnimatedReaction, runOnJS} from 'react-native-reanimated';
// import {Freeze} from 'react-freeze';
import TabBarContext from './TabBarContext';

export interface TabControllerPageProps {
  /**
   * The index of the the TabPage
   */
  index: number;
  /**
   * Whether this page should be loaded lazily
   */
  lazy?: boolean;
  /**
   * How long to wait till lazy load complete (good for showing loader screens and when loading big pages)
   */
  lazyLoadTime?: number;
  /**
   * Render a custom loading page when lazy loading
   */
  renderLoading?: () => JSX.Element;
  /**
   * Used as a testing identifier
   */
  testID?: string;
  /**
   * add style properties to tab page
   */
  style?: StyleProp<ViewStyle>;
}

/**
 * @description: TabController's TabPage
 * @example: https://github.com/wix/react-native-ui-lib/blob/master/demo/src/screens/componentScreens/TabControllerScreen/index.tsx
 */
export default function TabPage({
  testID,
  index,
  lazy,
  renderLoading,
  style,
  lazyLoadTime = 100,
  ...props
}: PropsWithChildren<TabControllerPageProps>) {
  const {currentPage, asCarousel, nestedInScrollView, containerWidth} = useContext(TabBarContext);
  const [shouldLoad, setLoaded] = useState(!lazy);

  // TODO: RN 77 hack - remove the state in future RN\reanimated release (ticket 4838 \ https://github.com/software-mansion/react-native-reanimated/issues/8517) when fixed we should revert to the original logic (see this PR: https://github.com/wix/react-native-ui-lib/pull/3829)
  const [isActive, setIsActive] = useState(currentPage.value === index);
  // const [focused, setFocused] = useState(false);

  const lazyLoad = useCallback(() => {
    if (lazy && !shouldLoad) {
      setTimeout(() => {
        setLoaded(true);
      }, lazyLoadTime);
    }
  }, [lazy, shouldLoad]);

  useAnimatedReaction(() => {
    return currentPage.value;
  },
  (currentPage /* , previousPage */) => {
    const isActive = currentPage === index;
    runOnJS(setIsActive)(isActive);
    // const wasActive = previousPage === index;
    // const nearActive = asCarousel && (currentPage - 1 === index || currentPage + 1 === index);
    // const wasNearActive =
    //     asCarousel && previousPage !== null && (previousPage - 1 === index || previousPage + 1 === index);

    if (isActive) {
      runOnJS(lazyLoad)();
    }

    // if (isActive || nearActive) {
    //   runOnJS(setFocused)(true);
    // } else if (wasActive || wasNearActive) {
    //   runOnJS(setFocused)(false);
    // }
  },
  [currentPage, lazyLoad]);

  const animatedPageStyle = useAnimatedStyle(() => {
    if (!nestedInScrollView) {
      return {};
    }

    const isActive = Math.round(currentPage.value) === index;

    return {position: isActive ? 'relative' : 'absolute'};
  });

  const _style = useMemo(() => {
    return [
      !asCarousel && styles.page,
      animatedPageStyle,
      {width: asCarousel ? containerWidth : undefined},
      style,
      !isActive && !asCarousel ? {opacity: 0, zIndex: 0} : {opacity: 1, zIndex: 1}
    ];
  }, [asCarousel, animatedPageStyle, containerWidth, style, isActive]);

  return (
    <Reanimated.View style={_style} testID={testID}>
      {!shouldLoad && renderLoading?.()}
      {shouldLoad && props.children}
      {/* <Freeze freeze={!shouldLoad || !focused}>{props.children}</Freeze> */}
    </Reanimated.View>
  );
}

const styles = StyleSheet.create({
  page: StyleSheet.absoluteFillObject
});

import _ from 'lodash';
import {useState, useCallback, useEffect, useRef, RefObject} from 'react';
import {LayoutChangeEvent} from 'react-native';
import {useSharedValue} from 'react-native-reanimated';
import {useScrollTo, ScrollToSupportedViews, ScrollToResultProps} from 'hooks';
import {Constants} from '../../commons/new';

const FIX_RTL = Constants.isRTL;

export enum OffsetType {
  CENTER = 'CENTER',
  DYNAMIC = 'DYNAMIC',
  LEFT = 'LEFT',
  RIGHT = 'RIGHT'
}

export type ScrollToItemProps<T extends ScrollToSupportedViews> = {
  scrollViewRef?: RefObject<T | null>;
  /**
   * The number of items
   */
  itemsCount: number;
  /**
   * The selected item's index
   */
  selectedIndex?: number;
  /**
   * The container width, should update on orientation change
   */
  containerWidth: number;
  /**
   * Where would the item be located (default to CENTER)
   */
  offsetType?: OffsetType | `${OffsetType}`;
  /**
   * Add a margin to the offset (default to true)
   * This gives a better UX
   * Not relevant to OffsetType.CENTER
   */
  addOffsetMargin?: boolean;
  /**
   * How much space (padding \ margin) is there on the left\right of the items
   */
  outerSpacing?: number;
  /**
   * How much space (padding \ margin) is there between each item
   */
  innerSpacing?: number;
};

// TODO: this is what I want, is there a better way to do it?
type Offsets = {
  CENTER: number[];
  LEFT: number[];
  RIGHT: number[];
};

export type ScrollToItemResultProps<T extends ScrollToSupportedViews> = Pick<
  ScrollToResultProps<T>,
  'scrollViewRef'
> & {
  /**
   * This should be called by each ot the items' onLayout
   */
  onItemLayout: (event: LayoutChangeEvent, index: number) => void;
  /**
   * The items' width as share animated value
   */
  itemsWidthsAnimated: any; //TODO: should be SharedValue<number[]>
  /**
   * The items' offsets as share animated value
   */
  itemsOffsetsAnimated: any; //TODO: should be SharedValue<number[]>
  /**
   * Use in order to focus the item with the specified index (use when the selectedIndex is not changed)
   */
  focusIndex: (index: number, animated?: boolean) => void;
  /**
   * Use in order to reset the data.
   */
  reset: () => void;
  /**
   * onContentSizeChange callback (should be set to your onContentSizeChange).
   * Needed for RTL support on Android.
   */
  onContentSizeChange: (contentWidth: number, contentHeight: number) => void;
  /**
   * onLayout callback (should be set to your onLayout).
   * Needed for RTL support on Android.
   */
  onLayout: (event: LayoutChangeEvent) => void;
};

const useScrollToItem = <T extends ScrollToSupportedViews>(props: ScrollToItemProps<T>): ScrollToItemResultProps<T> => {
  const {
    scrollViewRef: propsScrollViewRef,
    itemsCount,
    selectedIndex,
    containerWidth,
    offsetType = OffsetType.CENTER,
    addOffsetMargin = true,
    outerSpacing = 0,
    innerSpacing = 0
  } = props;
  const itemsWidths = useRef<(number | null)[]>(_.times(itemsCount, () => null));
  const itemsWidthsAnimated = useSharedValue<number[]>(_.times(itemsCount, () => 0));
  const itemsOffsetsAnimated = useSharedValue<number[]>(_.times(itemsCount, () => 0));
  const currentIndex = useRef<number>(selectedIndex || 0);
  const [offsets, setOffsets] = useState<Offsets>({CENTER: [], LEFT: [], RIGHT: []});
  const {scrollViewRef, scrollTo, onContentSizeChange, onLayout} = useScrollTo<T>({scrollViewRef: propsScrollViewRef});

  // TODO: reset?
  //   useEffect(() => {
  //     itemsWidths.current = _.times(itemsCount, () => null);
  //   }, [itemsCount]);

  // const contentWidth = _.sum(itemsWidths);
  // TODO: const scrollEnabled = contentWidth.current > containerWidth;

  const setSnapBreakpoints = useCallback((widths: number[]) => {
    if (_.isEmpty(widths)) {
      return;
    }

    const screenCenter = containerWidth / 2;
    let index = 0;
    const centeredOffsets = [];
    let currentCenterOffset = outerSpacing;
    const leftOffsets = [];
    leftOffsets.push(outerSpacing - innerSpacing);
    const rightOffsets = [];
    rightOffsets.push(-containerWidth + widths[0] + outerSpacing + innerSpacing);
    while (index < itemsCount) {
      /* calc center, left and right offsets */
      centeredOffsets[index] = currentCenterOffset - screenCenter + widths[index] / 2;
      ++index;
      currentCenterOffset += widths[index - 1] + innerSpacing;
      leftOffsets[index] = leftOffsets[index - 1] + widths[index - 1] + innerSpacing;
      rightOffsets[index] = rightOffsets[index - 1] + widths[index] + innerSpacing;
    }

    if (addOffsetMargin) {
      index = 1;
      while (index < itemsCount - 1) {
        leftOffsets[index] -= widths[index - 1];
        rightOffsets[index] += widths[index + 1] + innerSpacing;
        ++index;
      }
    }

    setOffsets({CENTER: centeredOffsets, LEFT: leftOffsets, RIGHT: rightOffsets}); // default for DYNAMIC is CENTER

    // Update shared values
    // @ts-expect-error pretty sure this is a bug in reanimated since itemsWidthsAnimated is defined as SharedValue<number[]>
    itemsWidthsAnimated.modify((value) => {
      'worklet';
      return value.map((_, index) => widths[index]);
    });

    itemsOffsetsAnimated.modify((value) => {
      'worklet';
      value.forEach((_, index) => {
        if (index > 0) {
          value[index] = value[index - 1] + widths[index - 1];
        }
      });
      return value;
    });
  },
  [itemsCount, outerSpacing, innerSpacing, addOffsetMargin, containerWidth]);

  const onItemLayout = useCallback((event: LayoutChangeEvent, index: number) => {
    const {width} = event.nativeEvent.layout;
    itemsWidths.current[index] = width;
    if (!_.includes(itemsWidths.current, null)) {
      setSnapBreakpoints(itemsWidths.current as number[]);
    }
  },
  [setSnapBreakpoints]);

  const focusIndex = useCallback((index: number, animated = true) => {
    if (index >= 0 && offsets.CENTER.length > index) {
      const rtlIndex = FIX_RTL ? itemsCount - index - 1 : index;
      if (offsetType !== OffsetType.DYNAMIC) {
        scrollTo(offsets[offsetType][rtlIndex], animated);
      } else {
        const movingLeft = index < currentIndex.current;
        currentIndex.current = rtlIndex;
        scrollTo(movingLeft ? offsets[OffsetType.RIGHT][rtlIndex] : offsets[OffsetType.LEFT][rtlIndex], animated);
      }
    }
  },
  [offsets, offsetType, scrollTo]);

  useEffect(() => {
    if (!_.isUndefined(selectedIndex)) {
      focusIndex(selectedIndex, false);
    }
  }, [selectedIndex, focusIndex]);

  const reset = useCallback(() => {
    for (let i = 0; i < itemsCount; ++i) {
      itemsWidths.current[i] = null;
      itemsWidthsAnimated.value[i] = 0;
      itemsOffsetsAnimated.value[i] = 0;
    }

    setOffsets({CENTER: [], LEFT: [], RIGHT: []});
  }, [itemsCount]);

  return {
    scrollViewRef,
    onItemLayout,
    itemsWidthsAnimated,
    itemsOffsetsAnimated,
    focusIndex,
    reset,
    onContentSizeChange,
    onLayout
  };
};

useScrollToItem.offsetType = OffsetType;

export default useScrollToItem;

import {StyleSheet, TextStyle} from 'react-native';
import {useComponentDriver, ComponentProps, ComponentDriverOptions} from '../../testkit/new/Component.driver';
import {usePressableDriver} from '../../testkit/new/usePressable.driver';

export const TextDriver = (props: ComponentProps, options?: ComponentDriverOptions) => {
  const driver = usePressableDriver(useComponentDriver(props, options));

  const getText = () => {
    const textChildren = driver.getElement().children;
    if (textChildren.length === 0) {
      return '';
    }
    if (textChildren.length === 1 && typeof textChildren[0] === 'string') {
      return textChildren[0];
    }
    return textChildren;
  };

  const getStyle = () => {
    return StyleSheet.flatten(driver.getElement().props.style) as TextStyle;
  };

  return {...driver, getText, getStyle};
};

