import React, {useContext, useImperativeHandle, useRef} from 'react';
import {findNodeHandle, TextInput, TextInputProps} from 'react-native';
import FieldContext from './FieldContext';

const useImperativeInputHandle = (ref: React.Ref<any>, props: Pick<TextInputProps, 'onChangeText'>) => {
  const inputRef = useRef<TextInput>(undefined);
  const context = useContext(FieldContext);
  useImperativeHandle(ref, () => {
    return {
      getNodeHandle: () => inputRef.current ? findNodeHandle(inputRef.current) : null,
      isFocused: () => inputRef.current?.isFocused(),
      focus: () => inputRef.current?.focus(),
      blur: () => inputRef.current?.blur(),
      clear: () => {
        inputRef.current?.clear();
        // NOTE: This fixes an RN issue - when triggering imperative clear method, it doesn't call onChangeText
        props.onChangeText?.('');
      },
      validate: () => {
        return context.validateField();
      },
      // Note: This returns field validity without actually validating it
      isValid: () => {
        return context.checkValidity();
      }
    };
  });

  return inputRef;
};

export default useImperativeInputHandle;

import React, {useMemo} from 'react';
import {StyleSheet, ViewStyle} from 'react-native';
import View from '../view';
import Dash from '../dash';
import {LineProps, LineTypes} from './types';

const LINE_WIDTH = 2;
const ENTRY_POINT_HEIGHT = 2;

type LinePropsInternal = LineProps & {
  top?: boolean;
  style?: ViewStyle;
  testID?: string;
};

const Line = React.memo((props: LinePropsInternal) => {
  const {type, color = 'transparent', entry, top, style, width = LINE_WIDTH, testID} = props;

  const solidLineStyle = useMemo(() => {
    return [style, styles.line, {width, backgroundColor: color}];
  }, [color, style, width]);

  const dashedLineStyle = useMemo(() => {
    return [style, styles.line];
  }, [style]);

  const renderStartPoint = () => {
    if (entry) {
      return (
        <View
          style={[styles.entryPoint, {backgroundColor: color}]}
          testID={`${testID}.entryPoint`}
        />
      );
    }
  };

  const renderLine = () => {
    if (type === LineTypes.DASHED) {
      return <Dash vertical color={color} containerStyle={dashedLineStyle} testID={testID}/>;
    }
    return <View style={solidLineStyle} testID={testID}/>;
  };

  return (
    <>
      {top && renderStartPoint()}
      {renderLine()}
      {!top && renderStartPoint()}
    </>
  );
});

export default Line;

const styles = StyleSheet.create({
  entryPoint: {
    width: 12,
    height: ENTRY_POINT_HEIGHT
  },
  line: {
    overflow: 'hidden'
  }
});

import React, {useMemo} from 'react';
import {StyleSheet, LayoutChangeEvent} from 'react-native';
import {Colors, Spacings} from '../../style';
import View from '../view';
import Icon from '../icon';
import Text from '../text';
import {PointProps, PointTypes} from './types';

const POINT_SIZE = 12;
const CONTENT_POINT_SIZE = 20;
const POINT_MARGINS = Spacings.s1;
const CIRCLE_WIDTH = 2;
const OUTLINE_WIDTH = 4;
const OUTLINE_TINT = 70;
const ICON_SIZE = 16;

type PointPropsInternal = PointProps & {
  onLayout?: (event: LayoutChangeEvent) => void;
  testID?: string;
};

const Point = (props: PointPropsInternal) => {
  const {icon, iconProps, removeIconBackground, label, type, color, onLayout, testID} = props;

  const pointStyle = useMemo(() => {
    const hasOutline = type === PointTypes.OUTLINE;
    const isCircle = type === PointTypes.CIRCLE;
    const hasContent = label || icon;

    const size = hasContent ? CONTENT_POINT_SIZE : POINT_SIZE;
    const pointSize = hasOutline ? size + OUTLINE_WIDTH * 2 : size;
    const pointSizeStyle = {width: pointSize, height: pointSize, borderRadius: pointSize / 2};

    const pointColorStyle = {backgroundColor: color};

    const outlineStyle = hasOutline && 
      {borderWidth: OUTLINE_WIDTH, borderColor: color && Colors.getColorTint(color, OUTLINE_TINT)};
    const circleStyle = !hasContent && isCircle && 
      {backgroundColor: 'transparent', borderWidth: CIRCLE_WIDTH, borderColor: color};

    return [styles.point, pointSizeStyle, !removeIconBackground && pointColorStyle, outlineStyle, circleStyle];
  }, [type, color, label, removeIconBackground, icon]);

  const renderPointContent = () => {
    const {removeIconBackground, labelColor} = props;
    const tintColor = removeIconBackground ? Colors.$iconDefault : Colors.$iconDefaultLight;
    const iconSize = removeIconBackground ? undefined : ICON_SIZE;
    if (icon) {
      return (
        <Icon testID={`${testID}.icon`} tintColor={tintColor} {...iconProps} size={iconSize} source={icon}/>
      );
    } else if (label) {
      return (
        <Text testID={`${testID}.label`} recorderTag={'unmask'} $textDefaultLight subtextBold color={labelColor}>
          {label}
        </Text>
      );
    }
  };

  return (
    <View center style={pointStyle} onLayout={onLayout} testID={testID}>
      {renderPointContent()}
    </View>
  );
};

export default Point;

const styles = StyleSheet.create({
  point: {
    marginVertical: POINT_MARGINS
  }
});

import React, {useCallback, useMemo, useEffect, useState, useRef} from 'react';
import {StyleSheet, MeasureOnSuccessCallback, LayoutChangeEvent} from 'react-native';
import {Colors, Spacings} from '../../style';
import {useThemeProps} from '../../hooks';
import View from '../view';
import Point from './Point';
import Line from './Line';
import {TimelineProps, PointProps, LineProps, StateTypes, PointTypes, LineTypes, Layout} from './types';
export {
  TimelineProps,
  PointProps as TimelinePointProps,
  LineProps as TimelineLineProps,
  StateTypes as TimelineStateTypes,
  PointTypes as TimelinePointTypes,
  LineTypes as TimelineLineTypes
};

const CONTENT_CONTAINER_PADDINGS = Spacings.s2;
const ENTRY_POINT_HEIGHT = 2;

const Timeline = (props: TimelineProps) => {
  const themeProps = useThemeProps(props, 'Timeline');
  const {topLine, bottomLine, point, children, testID} = themeProps;
  const [anchorMeasurements, setAnchorMeasurements] = useState<Layout | undefined>();
  const [contentContainerMeasurements, setContentContainerMeasurements] = useState<Layout | undefined>();
  const [pointMeasurements, setPointMeasurements] = useState<Layout | undefined>();
  const contentContainerRef = useRef<any>(undefined);

  const onMeasure: MeasureOnSuccessCallback = (x, y, width, height) => {
    setAnchorMeasurements({x, y, width, height});
  };

  useEffect(() => {
    setTimeout(() => {
      if (point?.anchorRef?.current && contentContainerRef?.current && contentContainerMeasurements) {
        // point.anchorRef.current.measure?.(onMeasure); // Android always returns x, y = 0 (see: https://github.com/facebook/react-native/issues/4753)
        //@ts-expect-error
        point.anchorRef.current.measureLayout?.(contentContainerRef.current, onMeasure);
      } else if (point?.anchorRef === undefined) {
        setAnchorMeasurements(undefined);
      }
    }, 0);
  }, [point?.anchorRef, contentContainerMeasurements]);

  const visibleStyle = useMemo(() => {
    return {opacity: contentContainerMeasurements ? 1 : 0};
  }, [contentContainerMeasurements]);

  const containerStyle = useMemo(() => {
    return [styles.container, visibleStyle];
  }, [visibleStyle]);

  const getStateColor = (state?: PointProps['state']) => {
    switch (state) {
      case StateTypes.CURRENT:
        return Colors.$backgroundPrimaryHeavy;
      case StateTypes.NEXT:
        return Colors.$backgroundNeutralIdle;
      case StateTypes.ERROR:
        return Colors.$backgroundDangerHeavy;
      case StateTypes.SUCCESS:
        return Colors.$backgroundSuccessHeavy;
      default:
        return Colors.$backgroundPrimaryHeavy;
    }
  };

  const topLineHeight = useMemo(() => {
    let height = 0;
    if (contentContainerMeasurements && pointMeasurements) {
      const pointCenter = pointMeasurements.height / 2;
      const contentY = contentContainerMeasurements.y - CONTENT_CONTAINER_PADDINGS / 2;
      const anchorCenterY = anchorMeasurements ? anchorMeasurements?.y + anchorMeasurements?.height / 2 
        : contentContainerMeasurements.y + contentContainerMeasurements.height / 2;
      const entryPointHeight = topLine?.entry ? ENTRY_POINT_HEIGHT : 0;
      height = contentY + anchorCenterY - pointCenter - entryPointHeight;
    }
    return height;
  }, [anchorMeasurements, contentContainerMeasurements, pointMeasurements, topLine?.entry]);

  const topLineStyle = useMemo(() => {
    return {height: topLineHeight};
  }, [topLineHeight]);


  const onPointLayout = useCallback((event: LayoutChangeEvent) => {
    const {x, y, width, height} = event.nativeEvent.layout;
    setPointMeasurements({x, y, width, height});
  }, []);

  const onContentContainerLayout = useCallback((event: LayoutChangeEvent) => {
    const {x, y, width, height} = event.nativeEvent.layout;
    setContentContainerMeasurements({x, y, width, height});
  }, []);

  const renderTopLine = () => {
    return (
      <Line
        testID={`${testID}.topLine`}
        {...topLine}
        top
        style={topLineStyle}
        color={topLine ? topLine?.color || getStateColor(topLine?.state) : undefined}
      />
    );
  };

  const renderBottomLine = () => {
    if (bottomLine) {
      return (
        <Line
          testID={`${testID}.bottomLine`}
          {...bottomLine}
          style={styles.bottomLine}
          color={bottomLine?.color || getStateColor(bottomLine?.state)}
        />
      );
    }
  };

  return (
    <View row style={containerStyle} testID={testID}>
      <View style={styles.timelineContainer}>
        {renderTopLine()}
        <Point
          {...point}
          onLayout={onPointLayout}
          color={point?.color || getStateColor(point?.state)}
          testID={`${testID}.point`}
        />
        {renderBottomLine()}
      </View>
      <View style={styles.contentContainer} onLayout={onContentContainerLayout} ref={contentContainerRef}>
        {children}
      </View>
    </View>
  );
};

