const COLOR = Colors.white;

/**
 * @description: A toast component
 * @example: https://github.com/wix/react-native-ui-lib/blob/master/demo/src/screens/componentScreens/ToastsScreen.js
 * @gif: https://github.com/wix/react-native-ui-lib/blob/master/demo/showcase/Toast/Toast.gif?raw=true, https://github.com/wix/react-native-ui-lib/blob/master/demo/showcase/Toast/ToastAttachment.gif?raw=true
 */
export default class Toast extends PureBaseComponent {
  static displayName = 'Toast';

  static defaultProps = {
    position: 'top',
    zIndex: 100
  };

  constructor(props) {
    super(props);

    this.state = {
      toastHeight: 0,
      inAnimation: false
    };

    this.toastAnim = new Animated.Value(0);
  }

  componentDidMount() {
    const {visible} = this.props;

    if (visible) {
      this.toggleToast(visible, {delay: 100});
    }
  }

  componentDidUpdate(prevProps) {
    if (this.props.visible !== prevProps.visible) {
      this.toggleToast(this.props.visible);
    }
  }

  playAccessibilityFeatures() {
    const {visible, message, action, showDismiss} = this.props;

    if (visible) {
      if ((this.viewRef && action) || showDismiss) {
        const reactTag = findNodeHandle(this.viewRef);
        AccessibilityInfo.setAccessibilityFocus(reactTag);
      } else {
        AccessibilityInfo.announceForAccessibility(`notification ${message}`);
      }
    }
  }

  setAnimationStatus = inAnimation => this.setState({inAnimation});

  toggleToast(show, {delay} = {}) {
    Animated.timing(this.toastAnim, {
      toValue: Number(show),
      duration: 300,
      delay,
      easing: Easing.bezier(0.215, 0.61, 0.355, 1),
      useNativeDriver: true
    }).start(this.onAnimationEnd);

    this.setAnimationStatus(true);
  }

  generateStyles() {
    this.styles = createStyles(this.props);
  }

  onAnimationEnd = () => {
    const {visible} = this.props;

    if (visible) {
      this.setDismissTimer();
    } else {
      this.setAnimationStatus(false);
    }

    this.playAccessibilityFeatures();
    _.invoke(this.props, 'onAnimationEnd', visible);
  };

  setDismissTimer() {
    const {autoDismiss, onDismiss} = this.props;

    if (autoDismiss && onDismiss) {
      const timer = setTimeout(() => {
        this.onDismiss(timer);
      }, autoDismiss);
    }
  }

  onDismiss = timer => {
    if (timer) {
      clearTimeout(timer);
    }
    _.invoke(this.props, 'onDismiss');
  };

  getAbsolutePositionStyle(location) {
    return {
      position: 'absolute',
      left: 0,
      right: 0,
      [location]: 0
    };
  }

  onToastLayout = ({
    nativeEvent: {
      layout: {height}
    }
  }) => {
    if (height > this.state.toastHeight) {
      this.setState({
        toastHeight: height
      });
    }
  };

  renderMessage() {
    const {message, centerMessage, color} = this.getThemeProps();
    const textColor = color || COLOR;
    const textAlign = centerMessage ? 'center' : 'left';

    return (
      <Text
        ref={r => (this.viewRef = r)}
        style={[this.styles.message, {color: textColor, textAlign}]}
        accessibilityLabel={`notification ${message}`}
      >
        {message}
      </Text>
    );
  }

  renderAction() {
    const {showLoader, showDismiss, action, color, backgroundColor, customLoader} = this.props;
    const textColor = color || COLOR;

    // NOTE: order does matter
    if (showLoader && !showDismiss) {
      if (customLoader) {
        return (
          <View center marginR-20>
            {customLoader()}
          </View>
        );
      }

      return <ActivityIndicator size={'small'} animating color={Colors.white} style={{marginRight: 20}}/>;
    }

    if (showDismiss) {
      return (
        <Button
          link
          iconStyle={{tintColor: textColor}}
          iconSource={Assets.internal.icons.x}
          onPress={this.onDismiss}
          paddingR-20
          accessibilityLabel={'dismiss'}
          accessibilityRole={'button'}
        />
      );
    }

    if (action) {
      const actionBg = backgroundColor || Colors.rgba(Colors.$backgroundPrimaryHeavy, 0);

      return (
        <Button
          style={this.styles.action}
          backgroundColor={actionBg}
          color={textColor}
          {...action}
          labelStyle={Typography.text70BO}
          accessibilityRole={'button'}
        />
      );
    }
  }

  renderIcon() {
    const {icon, color} = this.props;
    const tintColor = color || COLOR;

    if (icon) {
      return <Icon source={icon} resizeMode={'contain'} style={this.styles.icon} tintColor={tintColor}/>;
    }
  }

  renderContent() {
    const {children} = this.getThemeProps();

    if (!_.isUndefined(children)) {
      return children;
    }

    return (
      <View row>
        <View flex style={this.styles.toastContent}>
          {this.renderIcon()}
          {this.renderMessage()}
        </View>
        {this.renderAction()}
      </View>
    );
  }

  renderAttachmentContent() {
    const {renderAttachment} = this.props;

    if (renderAttachment) {
      return <View pointerEvents={'box-none'}>{renderAttachment()}</View>;
    }
  }

  render() {
    const {toastHeight, inAnimation} = this.state;
    const {visible, backgroundColor, position, zIndex, style, renderAttachment, testID} = this.getThemeProps();
    const positionStyle = this.getAbsolutePositionStyle(position);

    if (!visible && !inAnimation) {
      if (renderAttachment) {
        return (
          <View style={[positionStyle, {zIndex}]} pointerEvents={'box-none'}>
            {this.renderAttachmentContent()}
          </View>
        );
      }
      return null;
    }

    const bg = backgroundColor || Colors.$backgroundPrimaryHeavy;
    const isTop = position === 'top';
    const positionMultiplier = isTop ? -1 : 1;
    const translateY = this.toastAnim.interpolate({
      inputRange: [0, 1],
      outputRange: [positionMultiplier * (toastHeight || 500), 0]
    });
    const opacity = this.toastAnim.interpolate({
      inputRange: [0, 0.01, 1],
      outputRange: [0, 1, 1]
    });

    return (
      <View
        animated
        testID={testID}
        style={[positionStyle, {zIndex, transform: [{translateY}]}]}
        pointerEvents={'box-none'}
      >
        {!isTop && !!toastHeight && this.renderAttachmentContent()}
        <View
          useSafeArea
          animated
          style={[{backgroundColor: bg, opacity}, style]}
          onLayout={this.onToastLayout}
          pointerEvents={visible ? 'auto' : 'none'}
        >
          {this.renderContent()}
        </View>
        {isTop && !!toastHeight && this.renderAttachmentContent()}
      </View>
    );
  }
}

function createStyles() {
  return StyleSheet.create({
    toastContent: {
      minHeight: 48,
      flexDirection: 'row',
      justifyContent: 'space-between',
      alignItems: 'center',
      paddingHorizontal: 20,
      paddingVertical: 12
    },
    message: {
      flex: 1,
      ...Typography.text70
    },
    icon: {
      width: 24,
      height: 24,
      marginRight: 16
    },
    action: {
      borderRadius: BorderRadiuses.br0,
      minWidth: undefined,
      paddingRight: 20
    }
  });
}

import _ from 'lodash';
import React, {PureComponent} from 'react';
import {
  GestureResponderEvent,
  TouchableOpacity as RNTouchableOpacity,
  TouchableOpacityProps as RNTouchableOpacityProps
} from 'react-native';
import {
  asBaseComponent,
  forwardRef,
  BaseComponentInjectedProps,
  ForwardRefInjectedProps,
  ContainerModifiers,
  BackgroundColorModifier
} from '../../commons/new';
import {RecorderProps} from '../../typings/recorderTypes';
import IncubatorTouchableOpacity from '../../incubator/TouchableOpacity';
import {ViewProps} from '../view';

export interface TouchableOpacityProps
  extends Omit<RNTouchableOpacityProps, 'style' | 'onPress' | 'onPressIn' | 'onPressOut' | 'onLongPress'>,
    ContainerModifiers,
    BackgroundColorModifier,
    RecorderProps {
  /**
   * background color for TouchableOpacity
   */
  backgroundColor?: string;
  /**
   * throttle time in MS for onPress callback
   */
  throttleTime?: number;
  /**
   * throttle options {leading, trailing}
   */
  throttleOptions?: {leading: boolean; trailing: boolean};
  /**
   * Apply background color on TouchableOpacity when active (press is on)
   */
  activeBackgroundColor?: string;
  /**
   * Will apply scale press feedback. This will enforce the useNative prop
   */
  activeScale?: number;
  /**
   * Should use a more native touchable opacity component
   */
  useNative?: boolean;
  /**
   * Custom value of any type to pass on to TouchableOpacity and receive back in onPress callback
   */
  customValue?: any;
  style?: ViewProps['style'];
  onPress?: (props?: (TouchableOpacityProps & {event: GestureResponderEvent}) | any) => void;
  onPressIn?: (
    props?: TouchableOpacityProps | GestureResponderEvent | any
  ) => void | RNTouchableOpacityProps['onPressIn'];
  onPressOut?: (
    props?: TouchableOpacityProps | GestureResponderEvent | any
  ) => void | RNTouchableOpacityProps['onPressOut'];
  onLongPress?: (
    props?: (TouchableOpacityProps & {event: GestureResponderEvent}) | any
  ) => void | RNTouchableOpacityProps['onLongPress'];
  nativeID?: string;
}

type Props = BaseComponentInjectedProps & ForwardRefInjectedProps & TouchableOpacityProps;

/**
 * @description: A wrapper for TouchableOpacity component. Support onPress, throttling and activeBackgroundColor
 * @modifiers: margins, paddings, alignments, background, borderRadius
 * @extends: TouchableOpacity
 * @extendsLink: https://reactnative.dev/docs/touchableopacity
 * @gif: https://media.giphy.com/media/xULW8AMIgw7l31zjm8/giphy.gif
 * @example: https://github.com/wix/react-native-ui-lib/blob/master/src/components/touchableOpacity/index.tsx
 */
class TouchableOpacity extends PureComponent<Props, {active: boolean}> {
  static displayName = 'TouchableOpacity';

  constructor(props: Props) {
    super(props);

    this.state = {
      active: false
    };

    const {throttleTime = 0, throttleOptions = {leading: true, trailing: false}} = props;
    this.onPress = _.throttle(this.onPress.bind(this), throttleTime, throttleOptions);
  }

  getAccessibilityInfo() {
    const {disabled} = this.props;

    return {
      accessibilityRole: 'button',
      accessibilityStates: disabled ? ['disabled'] : []
    };
  }

  onPressIn = (...args: any) => {
    if (this.props.activeBackgroundColor) {
      this.setState({active: true});
    }
    if (this.props?.customValue) {
      this.props.onPressIn?.(this.props);
    } else {
      this.props.onPressIn?.(...args);
    }
  };

  onPressOut = (...args: any) => {
    if (this.props.activeBackgroundColor) {
      this.setState({active: false});
    }
    if (this.props?.customValue) {
      this.props.onPressOut?.(this.props);
    } else {
      this.props.onPressOut?.(...args);
    }
  };

  get backgroundColorStyle() {
    const {backgroundColor: propsBackgroundColor, modifiers} = this.props;
    const backgroundColor = propsBackgroundColor || modifiers.backgroundColor;

    if (backgroundColor) {
      return {backgroundColor};
    }
  }

  get activeBackgroundStyle() {
    const {active} = this.state;
    const {activeBackgroundColor} = this.props;

    if (active && activeBackgroundColor) {
      return {backgroundColor: activeBackgroundColor};
    }
  }

  render() {
    const {useNative, activeScale, style, modifiers, forwardedRef, recorderTag, ...others} = this.props;
    const {borderRadius, paddings, margins, alignments, flexStyle} = modifiers;

    if (useNative || !_.isUndefined(activeScale)) {
      // @ts-ignore
      return <IncubatorTouchableOpacity fsTagName={recorderTag} {...this.props}/>;
    }

    return (
      // @ts-ignore
      <RNTouchableOpacity
        fsTagName={recorderTag}
        {...this.getAccessibilityInfo()}
        {...others}
        onPress={this.onPress}
        onPressIn={this.onPressIn}
        onPressOut={this.onPressOut}
        onLongPress={this.onLongPress}
        style={[
          this.backgroundColorStyle,
          borderRadius && {borderRadius},
          flexStyle,
          paddings,
          margins,
          alignments,
          style,
          this.activeBackgroundStyle
        ]}
        ref={forwardedRef}
      />
    );
  }

  onPress(event: GestureResponderEvent) {
    this.props.onPress?.({...this.props, event});
  }

  onLongPress = (event: GestureResponderEvent) => {
    this.props.onLongPress?.({...this.props, event});
  };
}

const modifiersOptions = {
  borderRadius: true,
  paddings: true,
  margins: true,
  alignments: true,
  flex: true,
  backgroundColor: true
};

export default asBaseComponent<TouchableOpacityProps>(forwardRef(TouchableOpacity), {modifiersOptions});

