import { JSX, useState, useEffect } from "react";
import { Image, ImageStyle, Pressable, StyleSheet, TextStyle, View, ViewStyle } from "react-native";
import { useTheme, useColors } from "./theme";
import Text from "./Text";
import Icon from "./Icon";

interface SpaceAroundProps {
    direction: 'row-reverse' | 'column' | 'column-reverse' | 'row';
}

function spaceAround(direction: SpaceAroundProps['direction']) {
    switch (direction) {
        case 'row-reverse':
            return { marginRight: 10 };
        case 'column':
            return { marginTop: 10 };
        case 'column-reverse':
            return { marginBottom: 10 };
        default:
            return { marginLeft: 10 };
    }
}

interface LabelProps {
    image?: string;
    label?: string;
    disabled?: boolean;
    labelStyle?: TextStyle | TextStyle[];
    imageStyle?: ImageStyle;
    flexDirection?: SpaceAroundProps['direction'];
}

function renderLabel({
    image,
    label,
    disabled,
    labelStyle,
    imageStyle,
    flexDirection,
}: LabelProps): JSX.Element | null {
    const theme = useTheme();
    const labelStyles = [
        styles(theme).textStyles,
        disabled && styles(theme).disabledLabel,
        ...(Array.isArray(labelStyle) ? labelStyle : [labelStyle]),
        flexDirection && spaceAround(flexDirection),
    ].filter(Boolean);

    const imageStyles = [imageStyle, flexDirection && spaceAround(flexDirection)].filter(Boolean);

    if (image && !label) {
        return <Image source={{ uri: image }} style={imageStyles} />;
    }
    if (!image && label) {
        return <Text style={labelStyles}>{label}</Text>;
    }
    return null;
}

interface CheckedProps {
    checked?: boolean;
    iconColor?: string;
    iconFamily?: string;
    iconName?: string;
    iconSize?: number;
}

function renderChecked({
    checked,
    iconColor,
    iconFamily,
    iconName,
    iconSize,
}: CheckedProps): JSX.Element | null {
    if (checked) {
        return (
            <Icon 
                name={iconName || 'check'} 
                family={iconFamily || 'antdesign'} 
                color={iconColor || '#000'} 
                size={iconSize || 16}
            />
        );
    }
    return null;
}

interface OnPressProps {
    checked?: boolean;
    onChange: (checked: boolean) => void;
    setChecked: (checked: boolean) => void;
}

function _onPress({
    checked,
    onChange,
    setChecked,
}: OnPressProps) {
    const current = !checked;
    onChange(current);
    setChecked(current);
}

interface CheckboxProps {
    checkboxStyle?: ViewStyle;
    color?: keyof ReturnType<typeof useColors> | string;
    disabled?: boolean;
    flexDirection?: SpaceAroundProps['direction'];
    image?: string;
    imageStyle?: ImageStyle;
    /**
     * @deprecated Use iconProps instead
     */
    iconColor?: string;
    /**
     * @deprecated Use iconProps instead
     */
    iconFamily?: string;
    /**
     * @deprecated Use iconProps instead
     */
    iconName?: string;
    /**
     * @deprecated Use iconProps instead
     */
    iconSize?: number;
    /**
     * Icon customization object (family, name, color, size, etc.)
     */
    iconProps?: {
        name?: string;
        family?: string;
        color?: string;
        size?: number;
        [key: string]: any;
    };
    checked?: boolean; // Controlled mode
    /**
     * @deprecated Use checked instead
     */
    initialValue?: boolean;
    label?: string;
    labelStyle?: TextStyle;
    labelColor?: keyof ReturnType<typeof useColors> | string;
    onChange?: (checked: boolean) => void;
    style?: ViewStyle;
    accessibilityLabel?: string;
    accessibilityHint?: string;
}

function Checkbox({
    checkboxStyle,
    color = 'primary',
    disabled = false,
    flexDirection = 'row',
    image,
    imageStyle,
    iconColor = '#fff', // deprecated
    iconFamily = 'FontAwesome', // deprecated
    iconName = 'check', // deprecated
    iconSize = 15, // deprecated
    iconProps = {},
    checked: controlledChecked,
    initialValue = false,
    label,
    labelStyle,
    labelColor,
    onChange = () => {},
    style,
    accessibilityLabel,
    accessibilityHint,
}: CheckboxProps): JSX.Element {
    const theme = useTheme();
    const colors = useColors();

    // Support both controlled and uncontrolled modes
    const isControlled = controlledChecked !== undefined;
    const [internalChecked, setInternalChecked] = useState(initialValue);
    const checked = isControlled ? controlledChecked : internalChecked;

    // Update internal state if controlledChecked changes (for controlled mode)
    useEffect(() => {
        if (isControlled && controlledChecked !== undefined) {
            setInternalChecked(controlledChecked);
        }
    }, [controlledChecked, isControlled]);

    const colorStyle = color 
        ? colors[color as keyof typeof colors] || color
        : colors.primary;
    const resolvedLabelColor = labelColor
        ? colors[labelColor as keyof typeof colors] || labelColor
        : colors.text;

    const checkBoxContainerStyle = [
        styles(theme).container, 
        flexDirection && { flexDirection }, 
        style
    ].filter(Boolean);

    const checkedInnerStyles = [
        styles(theme).checked,
        colorStyle && { backgroundColor: colorStyle, borderColor: colorStyle },
    ].filter(Boolean);

    const checkedBoxViewStyles = [
        styles(theme).checkboxView,
        styles(theme).uncheckedBoxView,
        color && { borderColor: colorStyle },
        color && !colorStyle && { borderColor: color },
        checked && checkedInnerStyles,
        disabled && styles(theme).disabled,
        checkboxStyle,
    ].filter(Boolean);

    const defaultAccessibilityLabel = accessibilityLabel || 
        (label ? `${label} checkbox` : 'checkbox');

    const handlePress = () => {
        if (!isControlled) {
            // Uncontrolled mode: update internal state
            _onPress({ checked, onChange, setChecked: setInternalChecked });
        } else {
            // Controlled mode: just call onChange, parent handles state
            onChange(!checked);
        }
    };

    return (
        <Pressable
            onPress={handlePress}
            style={checkBoxContainerStyle}
            disabled={disabled}
            accessibilityRole="checkbox"
            accessibilityState={{ checked, disabled }}
            accessibilityLabel={defaultAccessibilityLabel}
            accessibilityHint={accessibilityHint}
        >
            <View style={checkedBoxViewStyles as unknown as ViewStyle}>
                {checked ? (
                    <Icon
                        name={iconProps.name || iconName}
                        family={iconProps.family || iconFamily}
                        color={iconProps.color || iconColor}
                        size={iconProps.size || iconSize}
                        {...iconProps}
                    />
                ) : null}
            </View>
            {renderLabel({
                image,
                label,
                disabled,
                labelStyle: ([{ color: resolvedLabelColor }, labelStyle].filter(Boolean)) as TextStyle[],
                imageStyle,
                flexDirection,
            })}
        </Pressable>
    );
}

const styles = (theme: ReturnType<typeof useTheme>) => {
  const colors = theme.colors; // Use semantic colors

  return StyleSheet.create({
    container: {
      flexDirection: 'row',
      alignItems: 'center',
      justifyContent: 'flex-start',
    },
    checkboxView: {
      width: theme.sizes.CHECKBOX_WIDTH,
      height: theme.sizes.CHECKBOX_HEIGHT,
      borderWidth: theme.sizes.BORDER_WIDTH,
      alignItems: 'center',
      justifyContent: 'center',
      borderRadius: theme.sizes.BORDER_RADIUS,
    },
    uncheckedBoxView: {
      backgroundColor: colors.transparent,
      borderColor: colors.border,
    },
    checked: {
      backgroundColor: colors.primary,
      borderColor: colors.primary,
    },
    disabled: {
      borderColor: colors.disabled,
    },
    textStyles: {
      color: colors.text,
    },
    disabledLabel: {
      color: colors.disabledText,
      opacity: theme.sizes.OPACITY,
    },
  });
};

export default Checkbox;

import { JSX, useEffect, useState, useMemo, useCallback } from "react";
import { Animated, Dimensions, PanResponder, StyleSheet, ViewStyle, StyleProp } from "react-native";
import { useTheme, useColors } from "./theme";
import Block from "./Block";

const { width: SCREEN_WIDTH } = Dimensions.get('screen');

interface DeckSwiperProps {
    onSwipeRight?: () => void;
    onSwipeLeft?: () => void;
    focusedElementStyle?: StyleProp<ViewStyle>;
    nextElementStyle?: StyleProp<ViewStyle>;
    components: React.ReactNode[];
    style?: StyleProp<ViewStyle>;
    swipeThreshold?: number;
    cardWidth?: number;
    cardContainerStyle?: StyleProp<ViewStyle>;
    cardShadow?: keyof ReturnType<typeof useTheme>["shadows"] | ViewStyle;
    cardBackgroundColor?: string;
    nextCardBackgroundColor?: string;
    nextCardShadow?: keyof ReturnType<typeof useTheme>["shadows"] | ViewStyle;
    borderRadius?: number;
    showNextCard?: boolean;
}

function DeckSwiper({
    onSwipeRight,
    onSwipeLeft,
    focusedElementStyle = {},
    nextElementStyle = {},
    components,
    style,
    swipeThreshold = 110,
    cardWidth = SCREEN_WIDTH * 0.7,
    cardContainerStyle = {},
    cardShadow = 'md',
    cardBackgroundColor,
    nextCardBackgroundColor,
    nextCardShadow = 'sm',
    borderRadius,
    showNextCard = true,
}: DeckSwiperProps): JSX.Element {
    const theme = useTheme();
    const colors = useColors();
    const [currentIndex, setCurrentIndex] = useState(0);
    const position = useMemo(() => new Animated.ValueXY(), []);

    const rotate = useMemo(() => position.x.interpolate({
        inputRange: [-cardWidth / 2, 0, cardWidth / 2],
        outputRange: ["-10deg", "0deg", "10deg"],
        extrapolate: "clamp"
    }), [position.x, cardWidth]);

    const rotateAndTranslate = useMemo(() => ({
        transform: [
            { rotate },
            ...position.getTranslateTransform()
        ]
    }), [rotate, position]);

    const nextCardOpacity = useMemo(() => position.x.interpolate({
        inputRange: [-cardWidth / 2, 0, cardWidth / 2],
        outputRange: [1, 0, 1],
        extrapolate: "clamp"
    }), [position.x, cardWidth]);

    const nextCardScale = useMemo(() => position.x.interpolate({
        inputRange: [-cardWidth / 2, 0, cardWidth / 2],
        outputRange: [1, 0.8, 1],
        extrapolate: "clamp"
    }), [position.x, cardWidth]);

    const nextCardAnimatedStyle = useMemo(() => ({
        opacity: nextCardOpacity,
        transform: [{ scale: nextCardScale }],
        ...StyleSheet.absoluteFillObject
    }), [nextCardOpacity, nextCardScale]);

    const handleSwipeRight = useCallback(() => {
        if (currentIndex < components.length - 1) {
            setCurrentIndex(prev => prev + 1);
            onSwipeRight?.();
        }
    }, [currentIndex, components.length, onSwipeRight]);

    const handleSwipeLeft = useCallback(() => {
        if (currentIndex < components.length - 1) {
            setCurrentIndex(prev => prev + 1);
            onSwipeLeft?.();
        }
    }, [currentIndex, components.length, onSwipeLeft]);

    const panResponder = useMemo(() => PanResponder.create({
        onStartShouldSetPanResponder: () => true,
        onPanResponderMove: (_, gestureState) => {
            position.setValue({ x: gestureState.dx, y: gestureState.dy });
        },
        onPanResponderRelease: (_, gestureState) => {
            if (gestureState.dx > swipeThreshold) {
                Animated.spring(position, {
                    toValue: { x: cardWidth + 100, y: gestureState.dy },
                    useNativeDriver: false
                }).start(handleSwipeRight);
            } else if (gestureState.dx < -swipeThreshold) {
                Animated.spring(position, {
                    toValue: { x: -cardWidth - 100, y: gestureState.dy },
                    useNativeDriver: false
                }).start(handleSwipeLeft);
            } else {
                Animated.spring(position, {
                    toValue: { x: 0, y: 0 },
                    friction: 4,
                    useNativeDriver: false
                }).start();
            }
        },
    }), [position, swipeThreshold, cardWidth, handleSwipeRight, handleSwipeLeft]);

    useEffect(() => {
        position.setValue({ x: 0, y: 0 });
    }, [currentIndex, position]);

    const renderComponents = useCallback((componentsArray: React.ReactNode[]) => {
        return componentsArray.map((item, i) => {
            if (i < currentIndex) {
                return null;
            } else if (i === currentIndex) {
                return (
                    <Animated.View
                        key={i}
                        style={[
                            rotateAndTranslate,
                            StyleSheet.absoluteFillObject,
                            {
                                backgroundColor: cardBackgroundColor || colors.surface,
                                borderRadius: borderRadius ?? theme.sizes.CARD_BORDER_RADIUS,
                                ...(typeof cardShadow === 'string' ? theme.shadows[cardShadow] : cardShadow),
                            },
                            cardContainerStyle,
                            focusedElementStyle,
                        ]}
                        {...panResponder.panHandlers}
                    >
                        {item}
                    </Animated.View>
                );
            } else if (showNextCard && i === currentIndex + 1) {
                return (
                    <Animated.View
                        key={i}
                        style={[
                            nextCardAnimatedStyle,
                            {
                                backgroundColor: nextCardBackgroundColor || colors.background,
                                borderRadius: borderRadius ?? theme.sizes.CARD_BORDER_RADIUS,
                                ...(typeof nextCardShadow === 'string' ? theme.shadows[nextCardShadow] : nextCardShadow),
                            },
                            nextElementStyle,
                        ]}
                    >
                        {item}
                    </Animated.View>
                );
            } else {
                return null;
            }
        }).reverse();
    }, [currentIndex, rotateAndTranslate, focusedElementStyle, nextCardAnimatedStyle, cardBackgroundColor, nextCardBackgroundColor, cardShadow, nextCardShadow, cardContainerStyle, nextElementStyle, borderRadius, theme, colors, showNextCard, panResponder.panHandlers]);

    useEffect(() => {
        setCurrentIndex(0);
    }, [components.length]);

    const blockStyle: ViewStyle = {
        width: cardWidth,
        ...(Array.isArray(style) ? Object.assign({}, ...style) : (style || {})),
    };

    if (components.length === 0) {
        return <Block flex center style={blockStyle} />;
    }

    return (
        <Block flex center style={blockStyle}>
            {renderComponents(components)}
        </Block>
    );
}

export default DeckSwiper;

import React,{forwardRef, useImperativeHandle, useRef, useState, useEffect} from 'react';
import { View, Text, TextInput, StyleSheet, Pressable, KeyboardTypeOptions, ViewStyle, TextStyle, Platform } from 'react-native';
import Icon from './Icon';
import  { useTheme, useColors } from './theme';

export interface InputProps {
  style?: ViewStyle;
  textInputStyle?: TextStyle;
  type?: KeyboardTypeOptions;
  placeholderTextColor?: string;
  label?: string;
  labelStyles?: TextStyle;
  color?: string;
  help?: string;
  helpStyles?: TextStyle;
  bgColor?: string;
  borderless?: boolean;
  viewPass?: boolean;
  rounded?: boolean;
  icon?: string | boolean;
  family?: string;
  left?: boolean;
  right?: boolean;
  /**
   * @deprecated Use iconProps.color instead. Will be removed in a future version.
   */
  iconColor?: string;
  /**
   * @deprecated Use iconProps.size instead. Will be removed in a future version.
   */
  iconSize?: number;
  iconProps?: {
    color?: string;
    size?: number | 'xs' | 'sm' | 'md' | 'lg' | 'xl';
    style?: any;
    family?: string;
    [key: string]: any;
  };
  topHelp?: boolean;
  bottomHelp?: boolean;
  iconContent?: React.ReactNode;
  password?: boolean;
  error?: boolean;
  onRef?: (ref: TextInput) => void;
  // TextInput props
  placeholder?: string;
  value?: string;
  onChangeText?: (text: string) => void;
  onFocus?: () => void;
  onBlur?: () => void;
  onSubmitEditing?: () => void;
  returnKeyType?: 'done' | 'go' | 'next' | 'search' | 'send';
  autoCapitalize?: 'none' | 'sentences' | 'words' | 'characters';
  autoCorrect?: boolean;
  multiline?: boolean;
  numberOfLines?: number;
  maxLength?: number;
  editable?: boolean;
  selectTextOnFocus?: boolean;
  clearButtonMode?: 'never' | 'while-editing' | 'unless-editing' | 'always';
  keyboardType?: KeyboardTypeOptions;
  textContentType?: any;
  autoComplete?: any;
}

export interface InputRef {
  focus: () => void;
  blur: () => void;
  clear: () => void;
  isFocused: () => boolean;
}

const Input = forwardRef<InputRef, InputProps>(({
  style,
  textInputStyle,
  type = 'default',
  placeholderTextColor,
  label,
  labelStyles,
  color = 'primary',
  help,
  helpStyles,
  bgColor,
  borderless = false,
  viewPass = false,
  rounded = false,
  icon = false,
  family,
  left = true,
  right = false,
  iconColor = 'primary', // legacy
  iconSize = 16, // legacy
  iconProps = {},
  topHelp = true,
  bottomHelp = false,
  iconContent,
  password = false,
  error,
  onRef,
  ...rest
}, ref)=> {
  const theme = useTheme();
  const colors = useColors();
  const [isPassword, setIsPassword] = useState(password);
  const inputRef = useRef<TextInput>(null)

  useImperativeHandle(ref, ()=> ({
    focus: () => inputRef.current?.focus(),
    blur: () => inputRef.current?.blur(),
    clear: () => inputRef.current?.clear(),
    isFocused: () => inputRef.current?.isFocused() || false,
  }));

  useEffect(()=> {
    setIsPassword(password);
  },[password]);

  // Use theme color for bgColor if it's a theme key
  let resolvedBgColor = bgColor;
  if (resolvedBgColor && colors[resolvedBgColor as keyof typeof colors]) {
    resolvedBgColor = colors[resolvedBgColor as keyof typeof colors];
  }
  const inputViewStyles = [
    styles(theme, colors).inputStyle,
    styles(theme, colors).inputContainer,
    resolvedBgColor && { backgroundColor: resolvedBgColor },
    rounded && styles(theme, colors).rounded,
    borderless && styles(theme, colors).borderless,
    error && { borderColor: colors.error },
    rest.multiline && { minHeight: theme.sizes.INPUT_HEIGHT, height: 'auto' as any },
    style,
  ].filter(Boolean) as ViewStyle[];

  // Use theme color for text color if it's a theme key
  let resolvedTextColor = color;
  if (resolvedTextColor && colors[resolvedTextColor as keyof typeof colors]) {
    resolvedTextColor = colors[resolvedTextColor as keyof typeof colors];
  }
  const inputStyles = [
    styles(theme, colors).inputView,
    borderless && icon && styles(theme, colors).inputIcon,
    styles(theme, colors).inputText,
    resolvedTextColor && { color: resolvedTextColor },
    rest.multiline && { textAlignVertical: 'top' as const },
    textInputStyle || {}
  ].filter(Boolean);

  // Prefer new iconProps API, fallback to legacy iconColor/iconSize
  let resolvedIconColor = (error && colors.error)
    || iconProps.color
    || iconColor
    || placeholderTextColor
    || colors.placeholder;
  // If resolvedIconColor matches a theme color, use it
  if (resolvedIconColor && colors[resolvedIconColor as keyof typeof colors]) {
    resolvedIconColor = colors[resolvedIconColor as keyof typeof colors];
  }
  let resolvedIconSize = iconProps.size || iconSize || theme.sizes.BASE * 1.0625;
  // Warn if using legacy props
  useEffect(() => {
    if (iconColor !== undefined && iconProps.color === undefined) {
      // eslint-disable-next-line no-console
      console.warn('[Input] iconColor is deprecated. Use iconProps.color instead.');
    }
    if (iconSize !== undefined && iconProps.size === undefined) {
      // eslint-disable-next-line no-console
      console.warn('[Input] iconSize is deprecated. Use iconProps.size instead.');
    }
  }, [iconColor, iconSize, iconProps.color, iconProps.size]);

  // Use theme color for icon if it's a theme key
  let iconThemeColor = resolvedIconColor;
  if (iconThemeColor && colors[iconThemeColor as keyof typeof colors]) {
    iconThemeColor = colors[iconThemeColor as keyof typeof colors];
  }
  const iconInstance = icon ? (
    <Icon
      name={icon as string}
      family={iconProps.family || (family as string)}
      size={resolvedIconSize}
      style={{ marginRight: left && !right ? 4 : 0, ...(iconProps.style || {}) }}
      color={iconThemeColor}
      {...iconProps}
    />
  ) : (
    iconContent
  );

  // Use theme color for viewPass icon if it's a theme key
  let viewPassColor = iconProps.color || iconColor || colors.text;
  if (viewPassColor && colors[viewPassColor as keyof typeof colors]) {
    viewPassColor = colors[viewPassColor as keyof typeof colors];
  }
  const viewPassElement = password && viewPass && (
    <Pressable style={{ marginLeft: 2 }} onPress={() => setIsPassword(!isPassword)}>
      <Icon
        size={iconProps.size || iconSize || theme.sizes.BASE * 1.0625}
        color={viewPassColor}
        name="eye"
        family="entypo"
      />
    </Pressable>
  );

  // Use theme color for label if it's a theme key
  let resolvedLabelColor = labelStyles && (labelStyles as any).color;
  if (resolvedLabelColor && colors[resolvedLabelColor as keyof typeof colors]) {
    resolvedLabelColor = colors[resolvedLabelColor as keyof typeof colors];
  }
  const labelContent = label && label.length > 0 && (
    <Text style={[styles(theme, colors).label, labelStyles, resolvedLabelColor ? { color: resolvedLabelColor } : {}]}>{label}</Text>
  );

  // Use theme color for help text if it's a theme key
  let resolvedHelpColor = helpStyles && (helpStyles as any).color;
  if (resolvedHelpColor && colors[resolvedHelpColor as keyof typeof colors]) {
    resolvedHelpColor = colors[resolvedHelpColor as keyof typeof colors];
  }
  const helpContent = help && help.length > 0 && (
    <Text style={[styles(theme, colors).helpText, helpStyles, resolvedHelpColor ? { color: resolvedHelpColor } : {}]}>{help}</Text>
  );

  return(
    <View
      style ={{
        marginVertical: theme.sizes.BASE /2,
        alignContent: 'center',
      }}
    >
      {labelContent}
      {topHelp && !bottomHelp && helpContent}
      <View style={inputViewStyles}>
        {left && !right && iconInstance}
        <TextInput
          ref={(r) => {
            if (r) {
              (inputRef as any).current = r;
              onRef?.(r);
            }
          }}
          style={inputStyles}
          keyboardType={type}
          secureTextEntry={isPassword}
          placeholderTextColor={
            placeholderTextColor && colors[placeholderTextColor as keyof typeof colors]
              ? colors[placeholderTextColor as keyof typeof colors]
              : placeholderTextColor || colors.placeholder
          }
          underlineColorAndroid="transparent"
          {...rest}
        />
        {right && iconInstance}
        {viewPassElement}
      </View>
      {bottomHelp && helpContent}
    </View>
  );
});

Input.displayName = 'Input';

