import React, { forwardRef, useImperativeHandle} from 'react';
import type { JSX } from 'react';
import Typography from './Text';
import { useColors } from './theme';
import { TextStyle, Pressable, ViewStyle, Platform } from 'react-native';

export interface LinkProps {
    children?: React.ReactNode;
    onPress: () => void;
    style?: ViewStyle;
    textStyle?: TextStyle;
    color?: string;
    disabled?: boolean;
    activeOpacity?: number;
}

export interface linkRef {
    press: () => void;
}

const Link = forwardRef<linkRef, LinkProps>(({
    children,
    onPress,
    style,
    textStyle,
    color,
    disabled = false,
    activeOpacity = 0.7,
    ...rest
}, ref): JSX.Element => {
    const colors = useColors();

    const handlePress = () => {
        if (!disabled && onPress) {
            onPress();
        }
    };

    useImperativeHandle(ref, ()=> ({
        press: handlePress,
    }));

    const pressableStyle = [
        style,
        Platform.OS === 'web' && {
            cursor: disabled ? 'not-allowed' : 'pointer',
            userSelect: 'none',
        } as any,
    ];

    // Support theme palette keys for color and textStyle.color
    let resolvedColor = color;
    if (resolvedColor && colors[resolvedColor as keyof typeof colors]) {
        resolvedColor = colors[resolvedColor as keyof typeof colors];
    }
    let resolvedTextColor = textStyle && (textStyle as any).color;
    if (resolvedTextColor && colors[resolvedTextColor as keyof typeof colors]) {
        resolvedTextColor = colors[resolvedTextColor as keyof typeof colors];
    }

    return (
        <Pressable
            onPress={handlePress}
            style={pressableStyle}
            disabled={disabled}
            android_ripple={{ color: 'rgba(0,0,0,0.1)' }}
            accessibilityRole="link"
            accessibilityState={{ disabled }}
        >
            <Typography
                color={resolvedTextColor || resolvedColor || colors.primary}
                style={[
                    {
                        textDecorationLine: 'underline',
                        opacity: disabled ? 0.5 : 1,
                    },
                    textStyle,
                ]}
            >
                {children}
            </Typography>
        </Pressable>
    );
});

export default Link;

import React, { JSX, useMemo, useCallback } from "react";
import {
  TextProps,
  TextStyle,
  View,
  StyleSheet,
  Pressable,
  Platform,
  Dimensions,
  ViewStyle,
} from "react-native";

import { useTheme, useColors } from "./theme";
import Text from "./Text";
import Icon from "./Icon";
import Block from "./Block";

const { height } = Dimensions.get("screen");

interface NavBarProps {
  back?: boolean;
  hideLeft?: boolean;
  hideRight?: boolean;
  left?: React.ReactNode;
  leftStyle?: ViewStyle;
  leftIconColor?: string;
  leftHitSlop?: number;
  leftIconSize?: number;
  leftIconName?: string;
  leftIconFamily?: string;
  onLeftPress?: () => void;
  right?: React.ReactNode;
  rightStyle?: ViewStyle;
  style?: ViewStyle;
  transparent?: boolean;
  title?: React.ReactNode;
  titleStyle?: TextStyle;
  titleNumberOfLines?: number;
  titleTextProps?: TextProps;
  accessibilityLabel?: string;
}

function NavBar({
  back = false,
  hideLeft,
  hideRight,
  left,
  leftIconColor,
  leftHitSlop,
  leftIconSize,
  leftIconName,
  leftStyle,
  leftIconFamily,
  onLeftPress = () => {},
  right,
  rightStyle,
  style,
  transparent = false,
  title,
  titleStyle,
  titleNumberOfLines,
  titleTextProps,
  accessibilityLabel,
}: NavBarProps): JSX.Element {
  const theme = useTheme();
  const colors = useColors();

  const renderTitle = useCallback(() => {
    if (typeof title === "string") {
      return (
        <View style={styles(theme, colors).title}>
          <Text
            numberOfLines={titleNumberOfLines || 1}
            style={[styles(theme, colors).titleTextStyle, titleStyle]}
            {...titleTextProps}
          >
            {title}
          </Text>
        </View>
      );
    }
    if (!title) return null;
    return title;
  }, [title, titleStyle, titleNumberOfLines, titleTextProps, theme, colors]);

  const renderLeft = useCallback(() => {
    if (!hideLeft) {
      if (leftIconName || (back && !left)) {
        return (
          <View style={[styles(theme, colors).left, leftStyle]}>
            <Pressable
              onPress={onLeftPress}
              hitSlop={leftHitSlop}
              accessibilityRole="button"
              accessibilityLabel={accessibilityLabel || "Back button"}
            >
              <Icon
                name={leftIconName || (back ? "chevron-left" : "navicon")}
                family={leftIconFamily || "material"}
                color={leftIconColor || colors.text}
                size={leftIconSize || theme.sizes.BASE * 2.2} 
              />
            </Pressable>
          </View>
        );
      }
      return <View style={[styles(theme, colors).left, leftStyle]}>{left}</View>;
    }
    return <View style={styles(theme, colors).left} />;
  }, [
    hideLeft,
    leftIconName,
    back,
    left,
    leftStyle,
    onLeftPress,
    leftHitSlop,
    accessibilityLabel,
    leftIconFamily,
    leftIconColor,
    leftIconSize,
    theme,
    colors,
  ]);

  const renderRight = useCallback(() => {
    const hasIcons = React.Children.count(right) > 1;
    const rightStyles = { ...styles(theme, colors).right, ...rightStyle };

    if (!hideRight) {
      return (
        <View style={rightStyles}>
          {hasIcons ? (
            <View style={styles(theme, colors).rightIconsContainer}>{right}</View>
          ) : (
            right
          )}
        </View>
      );
    }
    return <View style={styles(theme, colors).right} />;
  }, [hideRight, right, rightStyle, theme, colors]);

  const navStyles = useMemo((): ViewStyle => {
    const defaultStyles = styles(theme, colors).navBar;
    const transparentStyles = transparent ? styles(theme, colors).transparent : {};
    const merged = StyleSheet.flatten([
      defaultStyles,
      transparentStyles,
      style ? style : [],
    ]) as ViewStyle;

    if (!merged.height || (typeof merged.height === "number" && merged.height <= 0)) {
      merged.height = defaultStyles.height;
    }
    return merged;
  }, [theme, colors, transparent, style]);

  return (
    <Block style={navStyles}>
      {renderLeft()}
      {renderTitle()}
      {renderRight()}
    </Block>
  );
}

const styles = (theme: ReturnType<typeof useTheme>, colors: ReturnType<typeof useColors>) =>
