import React, { useRef, useEffect, useState } from 'react';
import {
  View,
  Animated,
  PanResponder,
  StyleSheet,
  LayoutChangeEvent,
  ViewStyle,
} from 'react-native';
import { useTheme, useColors } from './theme';

interface SliderProps {
  value?: number;
  minimumValue?: number;
  maximumValue?: number;
  step?: number;
  disabled?: boolean;
  trackStyle?: ViewStyle;
  activeColor?: keyof ReturnType<typeof useColors> | string;
  thumbStyle?: ViewStyle;
  containerStyle?: ViewStyle;
  onValueChange?: (value: number) => void;
  accessibilityLabel?: string;
  accessibilityHint?: string;
}

const Slider: React.FC<SliderProps> = ({
  value = 0,
  minimumValue = 0,
  maximumValue = 1,
  step = 0.01,
  onValueChange,
  disabled = false,
  trackStyle,
  activeColor,
  containerStyle,
  thumbStyle,
  accessibilityLabel,
  accessibilityHint,
}) => {
  const theme = useTheme();
  const colors = useColors();
  const [containerWidth, setContainerWidth] = useState(0);
  const trackWidth = useRef(0);
  const thumbX = useRef(new Animated.Value(0)).current;
  const currentValue = useRef(value);
  const currentThumbPosition = useRef(0);
  const trackLayout = useRef({ x: 0, y: 0, width: 0, height: 0 });

  const valueToPosition = (val: number) => {
    const clamped = Math.max(minimumValue, Math.min(val, maximumValue));
    const ratio = (clamped - minimumValue) / (maximumValue - minimumValue);
    return ratio * trackWidth.current;
  };

  const positionToValue = (pos: number) => {
    const ratio = pos / trackWidth.current;
    const rawValue = ratio * (maximumValue - minimumValue) + minimumValue;
    const steppedValue = step > 0 ? Math.round(rawValue / step) * step : rawValue;
    return Math.max(minimumValue, Math.min(steppedValue, maximumValue));
  };

  useEffect(() => {
    const pos = valueToPosition(value);
    Animated.timing(thumbX, {
      toValue: pos,
      duration: 150,
      useNativeDriver: false,
    }).start();
    currentThumbPosition.current = pos;
  }, [value]);

  const panResponder = useRef(
    PanResponder.create({
      onStartShouldSetPanResponder: () => !disabled,
      onMoveShouldSetPanResponder: () => !disabled,
      onPanResponderGrant: (_, gestureState) => {
        if (disabled) return;
        const relativeX = gestureState.x0 - trackLayout.current.x;
        const thumbRadius = (theme?.sizes?.THUMB_SIZE || 25) / 2;
        const clampedX = Math.max(thumbRadius, Math.min(relativeX, trackWidth.current - thumbRadius));
        currentThumbPosition.current = clampedX;
        thumbX.setValue(clampedX);
      },
      onPanResponderMove: (_, gestureState) => {
        if (disabled) return;
        const relativeX = gestureState.moveX - trackLayout.current.x;
        const thumbRadius = (theme?.sizes?.THUMB_SIZE || 25) / 2;
        const clampedX = Math.max(thumbRadius, Math.min(relativeX, trackWidth.current - thumbRadius));
        currentThumbPosition.current = clampedX;
        thumbX.setValue(clampedX);
        const newValue = positionToValue(clampedX);
        if (newValue !== currentValue.current) {
          currentValue.current = newValue;
          onValueChange?.(newValue);
        }
      },
      onPanResponderRelease: () => {},
    })
  ).current;

  const onTrackLayout = (e: LayoutChangeEvent) => {
    const { width, x, y } = e.nativeEvent.layout;
    trackWidth.current = width;
    trackLayout.current = { x, y, width, height: e.nativeEvent.layout.height };
    thumbX.setValue(valueToPosition(currentValue.current));
  };

  const handleContainerLayout = (event: LayoutChangeEvent) => {
    const { width } = event.nativeEvent.layout;
    setContainerWidth(Math.round(width));
  };

  // Resolve theme palette key for activeColor
  const resolvedActiveColor = activeColor
    ? colors[activeColor as keyof typeof colors] || activeColor
    : colors.primary;

  return (
    <View
      style={[styles(theme, colors).container, containerStyle]}
      onLayout={handleContainerLayout}
    >
      <View
        onLayout={onTrackLayout}
        style={[styles(theme, colors).track, trackStyle]}
      />
      <View
        style={[styles(theme, colors).activeTrack, { width: trackWidth.current, backgroundColor: resolvedActiveColor }]}
      >
        <Animated.View
          style={[
            styles(theme, colors).thumb,
            thumbStyle,
            disabled && styles(theme, colors).disabled,
            { transform: [{ translateX: thumbX }] },
          ]}
          {...panResponder.panHandlers}
        />
      </View>
    </View>
  );
};

const styles = (theme: ReturnType<typeof useTheme>, colors: ReturnType<typeof useColors>) =>
  StyleSheet.create({
    container: {
      height: 40,
      justifyContent: 'center',
    },
    track: {
      height: theme?.sizes?.TRACK_SIZE || 4,
      width: '100%',
      borderRadius: (theme?.sizes?.TRACK_SIZE || 4) / 2,
      position: 'absolute',
      backgroundColor: colors.surface || colors.background || '#E0E0E0',
    },
    activeTrack: {
      height: theme?.sizes?.TRACK_SIZE || 4,
      position: 'absolute',
      borderRadius: (theme?.sizes?.TRACK_SIZE || 4) / 2,
    },
    thumb: {
      width: theme?.sizes?.THUMB_SIZE || 25,
      height: theme?.sizes?.THUMB_SIZE || 25,
      borderRadius: (theme?.sizes?.THUMB_SIZE || 25) / 2,
      borderWidth: 2,
      borderColor: colors.primary,
      backgroundColor: colors.white,
      position: 'absolute',
      marginTop: -10,
    },
    disabled: {
      backgroundColor: colors.surfaceVariant || colors.background || '#999999',
      borderColor: colors.surfaceVariant || colors.background || '#999999',
    },
  });

export default Slider;

import React, { useCallback, useEffect, useState, JSX } from 'react';
import { Switch as RNSwitch, ViewStyle } from 'react-native';
import { useColors } from './theme';

interface SwitchProps {
    value?: boolean;
    onValueChange?: (value: boolean) => void;
    color?: keyof ReturnType<typeof useColors> | string;
    disabled?: boolean;
    trackColor?: { false?: string; true?: string };
    iosBackgroundColor?: string;
    containerStyle?: ViewStyle;
    accessibilityLabel?: string;
    accessibilityHint?: string;
}

const Switch: React.FC<SwitchProps> = ({
    value,
    onValueChange,
    color = 'primary',
    disabled = false,
    trackColor,
    iosBackgroundColor,
    containerStyle,
    accessibilityLabel,
    accessibilityHint,
}) => {
    const colors = useColors();
    const [internalValue, setInternalValue] = useState(value ?? false);
    const isControlled = value !== undefined;
    const currentValue = isControlled ? value : internalValue;

    useEffect(() => {
        if (isControlled) setInternalValue(value!);
    }, [value, isControlled]);

    const handleValueChange = useCallback((newValue: boolean) => {
        if (!isControlled) setInternalValue(newValue);
        onValueChange?.(newValue);
    }, [isControlled, onValueChange]);

    // Resolve theme palette key or custom color
    const resolveColor = (c?: keyof typeof colors | string, fallback?: string) => {
        if (!c) return fallback || colors.primary;
        if (typeof c === 'string' && c.startsWith('#')) return c;
        return colors[c as keyof typeof colors] || fallback || colors.primary;
    };

    const defaultTrackColor = {
        false: resolveColor(trackColor?.false || 'surfaceVariant', colors.surfaceVariant),
        true: resolveColor(trackColor?.true || color, colors.primary),
    };
    const finalTrackColor = {
        false: defaultTrackColor.false,
        true: defaultTrackColor.true,
    };
    const finalIosBackgroundColor = resolveColor(iosBackgroundColor || 'surfaceVariant', colors.surfaceVariant);

    return (
        <RNSwitch
            value={currentValue}
            onValueChange={handleValueChange}
            disabled={disabled}
            trackColor={finalTrackColor}
            ios_backgroundColor={finalIosBackgroundColor}
            style={containerStyle}
            accessibilityRole="switch"
            accessibilityLabel={accessibilityLabel || 'Switch'}
            accessibilityHint={accessibilityHint || 'Toggle switch on or off'}
            accessibilityState={{ checked: currentValue }}
        />
    );
};

export default Switch;

import React, { memo, useMemo } from 'react';
import type { JSX } from 'react';
import { Platform, StyleProp, StyleSheet, Text, TextStyle, ViewStyle } from 'react-native';
import { normalize } from './helpers/normalize';
import GalioTheme, { useTheme, useColors } from './theme';

interface TypographyProps {
    style?: StyleProp<TextStyle>;
    h1?: boolean;
    h2?: boolean;
    h3?: boolean;
    h4?: boolean;
    h5?: boolean;
    h6?: boolean;
    p?: boolean;
    body?: boolean;
    small?: boolean;
    muted?: boolean;
    neutral?: boolean;
    size?: number;
    color?: string;
    bold?: boolean;
    italic?: boolean;
    center?: boolean;
    children?: React.ReactNode;
    theme?: any;
    shadow?: boolean;
    [key: string]: any;
}

function Typography({
    style,
    h1 = false,
    h2 = false,
    h3 = false,
    h4 = false,
    h5 = false,
    h6 = false,
    p = false,
    body = false,
    small = false,
    muted = false,
    neutral = false,
    size,
    color,
    bold = false,
    italic = false,
    center = false,
    children,
    theme: propTheme,
    shadow = false,
    ...rest
}: TypographyProps): JSX.Element {
    const theme = useTheme?.() || propTheme || GalioTheme;
    const colors = useColors?.() || theme?.colors || {};
    // Map font sizes to theme.sizes keys
    const fontSizes = {
        h1: theme?.sizes?.H1,
        h2: theme?.sizes?.H2,
        h3: theme?.sizes?.H3,
        h4: theme?.sizes?.H4,
        h5: theme?.sizes?.H5,
        h6: theme?.sizes?.H6,
        p: theme?.sizes?.BODY,
        body: theme?.sizes?.BODY,
        small: theme?.sizes?.SMALL,
    };
    const fontWeights = theme?.fontWeights || { bold: 'bold', normal: 'normal' };

    const getShadowStyle = (): TextStyle | undefined => {
        if (!shadow) return undefined;
        if (Platform.OS === 'web' || Platform.OS === 'ios' || Platform.OS === 'android') {
            return { textShadow: '0px 2px 8px rgba(0, 0, 0, 0.15)' } as any;
        }
        return undefined;
    };

    const dynamicStyles = useMemo(() => [
        h1 && { fontSize: normalize(fontSizes.h1 || 44) },
        h2 && { fontSize: normalize(fontSizes.h2 || 38) },
        h3 && { fontSize: normalize(fontSizes.h3 || 30) },
        h4 && { fontSize: normalize(fontSizes.h4 || 24) },
        h5 && { fontSize: normalize(fontSizes.h5 || 21) },
        h6 && { fontSize: normalize(fontSizes.h6 || 18) },
        p && { fontSize: normalize(fontSizes.p || 16) },
        body && { fontSize: normalize(fontSizes.body || 14) },
        small && { fontSize: normalize(fontSizes.small || 12) },
        muted && { color: colors.textTertiary || '#888' },
        neutral && { color: colors.textSecondary || '#555' },
        size && typeof size === 'number' ? { fontSize: normalize(size) } : undefined,
        color && { color },
        italic && { fontStyle: 'italic' as TextStyle['fontStyle'] },
        bold && { fontWeight: fontWeights.bold as TextStyle['fontWeight'] },
        center && { textAlign: 'center' as TextStyle['textAlign'] },
        getShadowStyle(),
        style,
    ], [h1, h2, h3, h4, h5, h6, p, body, small, muted, neutral, size, color, italic, bold, center, style, theme, shadow, fontSizes, fontWeights, colors]);

    return (
        <Text style={[styles(colors).base, ...dynamicStyles] as unknown as TextStyle} {...rest}>
            {children}
        </Text>
    );
}

const styles = (colors: ReturnType<typeof useColors> | undefined) => StyleSheet.create({
    base: {
        color: colors?.text || '#000',
    }
});
export default memo(Typography);

import React, { useEffect, useRef, useState } from 'react';
import { Dimensions, StyleSheet, Animated, View } from 'react-native';
import { useTheme, useColors } from './theme';
import Text from './Text';

const { height, width } = Dimensions.get('screen');

interface ToastProps {
    children: React.ReactNode;
    isShow: boolean;
    positionIndicator?: 'top' | 'center' | 'bottom';
    positionOffset?: number;
    fadeInDuration?: number;
    fadeOutDuration?: number;
    color?: string;
    round?: boolean;
    style?: any;
    textStyle?: any;
}

function Toast({
    children,
    isShow,
    positionIndicator = 'top',
    positionOffset = 120,
    fadeInDuration = 300,
    fadeOutDuration = 300,
    color = 'primary',
    round = false,
    style,
    textStyle,
}: ToastProps) {
    const theme = useTheme();
    const colors = useColors();
    const [internalIsShow, setInternalIsShow] = useState(isShow);
    const [opacity, setOpacity] = useState(0);
    const fadeAnim = useRef(new Animated.Value(0)).current;
    const animationRef = useRef<Animated.CompositeAnimation | null>(null);
    const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

    const getThemeColor = (colorName?: string) => {
        if (!colorName) return colors.primary;
        if (typeof colorName === 'string' && colorName.startsWith('#')) {
            return colorName;
        }
        // Explicit color map for theme safety
        const colorMap: { [key: string]: string } = {
            primary: colors.primary,
            success: colors.success,
            warning: colors.warning,
            error: colors.error,
            danger: colors.error,
            info: colors.info,
            white: colors.white,
            black: colors.black,
            onPrimary: colors.onPrimary,
        };
        return colorMap[colorName] || colors.primary;
    };

    const getTopPosition = () => {
        if (positionIndicator === 'top') {
            return positionOffset;
        }
        if (positionIndicator === 'bottom') {
            return height - positionOffset - 100;
        }
        return height / 2 - 50;
    };

    useEffect(() => {

        if (isShow && !internalIsShow) {

            setInternalIsShow(true);
            setOpacity(1);
            animationRef.current = Animated.timing(fadeAnim, {
                toValue: 1,
                duration: fadeInDuration,
                useNativeDriver: false,
            });

        }

        if (!isShow && internalIsShow) {
            console.log('Hiding toast');
            setOpacity(0); // Set opacity immediately for fallback

            animationRef.current = Animated.timing(fadeAnim, {
                toValue: 0,
                duration: fadeOutDuration,
                useNativeDriver: false,
            });


            timeoutRef.current = setTimeout(() => {
                setInternalIsShow(false);
            }, fadeOutDuration);
        }

        return () => {
            if (timeoutRef.current) {
                clearTimeout(timeoutRef.current);
            }
            if (animationRef.current) {
                animationRef.current.stop();
            }
        };
    }, [isShow, internalIsShow, fadeInDuration, fadeOutDuration, fadeAnim]);

    const renderContent = () => {
        if (typeof children === 'string') {
            return <Text style={[styles(theme, colors).text, textStyle]}>{children}</Text>;
        }
        return children;
    };



    const backgroundColor = getThemeColor(color);
    const borderRadius = round ? theme.sizes.BASE * 2 : theme.sizes.BASE;
    const topPosition = getTopPosition();



    const toastStyles = [
        styles(theme, colors).toast,
        {
            backgroundColor,
            top: topPosition,
            opacity: opacity,
            borderRadius,
            borderColor: colors.border || 'rgba(255,255,255,0.3)',
            shadowColor: colors.black,
        },
        style,
    ];

    return (
        <View style={styles(theme, colors).overlay} pointerEvents="none">
            <Animated.View style={toastStyles}>
                {renderContent()}
            </Animated.View>
        </View>
    );
}

const styles = (theme: ReturnType<typeof useTheme>, colors: ReturnType<typeof useColors>) =>
    StyleSheet.create({
        overlay: {
            position: 'absolute',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            zIndex: 99999,
            pointerEvents: 'none',
        },
        toast: {
            padding: theme.sizes.BASE * 1.5,
            position: 'absolute',
            left: theme.sizes.BASE,
            right: theme.sizes.BASE,
            shadowOffset: { width: 0, height: 4 },
            shadowOpacity: 0.3,
            shadowRadius: 8,
            elevation: 15,
            minHeight: 60,
            borderWidth: 1,
        },
        text: {
            fontSize: theme.sizes.FONT,
            color: colors.onPrimary || colors.white,
            textAlign: 'center',
            fontWeight: theme.fontWeights?.bold || '600',
        },
    });

export default Toast;

import { Dimensions, PixelRatio } from 'react-native';

const { width: SCREEN_WIDTH, height: SCREEN_HEIGHT } = Dimensions.get('window');

const BASE_WIDTH = 375;
const BASE_HEIGHT = 667;

export function normalize(size: number) {
    return (SCREEN_WIDTH / BASE_WIDTH) *  size;
}

export function verticalScale(size: number) {
    return (SCREEN_HEIGHT / BASE_HEIGHT) * size;
}

export function moderateScale(size: number, factor = 0.5) {
    return size + (normalize(size) - size) * factor;
}

export function scaleFont(size: number) {
    const newSize = normalize(size);
    return Math.round(PixelRatio.roundToNearestPixel(newSize));
}

