const variants = {
    enter: (delta: number) => ({
        x: delta > 0 ? 1000 : -1000,
        opacity: 0,
    }),
    center: {
        zIndex: 1,
        x: 0,
        opacity: 1,
    },
    exit: (delta: number) => ({
        zIndex: 0,
        x: delta < 0 ? 1000 : -1000,
        opacity: 0,
    }),
}

const Image = ({ src, paginate, delta }) => (
    <motion.img
        src={src}
        custom={delta}
        variants={variants}
        initial="enter"
        animate="center"
        exit="exit"
        drag="x"
        dragConstraints={{ left: 0, right: 0 }}
        dragElastic={1}
        transition={{
            duration: 2,
        }}
        onDragEnd={(e, { offset, velocity }) => {
            const swipe = Math.abs(offset.x) * velocity.x

            if (swipe < -10000) {
                paginate(1)
            } else if (swipe > 10000) {
                paginate(-1)
            }
        }}
    />
)

