const maxChildren = 4
const maxDepth = 2
function layoutChildren(currentDepth: number) {
    const children = []

    for (let i = 0; i < maxChildren; i++) {
        children.push(
            <motion.div
                layout
                key={i}
                style={{
                    display: "flex",
                    alignItems: "stretch",
