                    backgroundColor:
                        currentDepth === 0
                            ? "red"
                            : currentDepth === 1
                            ? "blue"
                            : "green",
                    width: "25%",
                    height: "25%",
                }}
            >
                {currentDepth < maxDepth && layoutChildren(currentDepth + 1)}
            </motion.div>
        )
    }

    return children
}

