function DragDrop() {
    const viewportWidth = useRef(0)
    const [is, setIs] = useState(true)

    useEffect(() => {
        viewportWidth.current = window.innerWidth
    }, [])

    return (
        <>
            <div
                style={{
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    width: "50%",
                    height: "100%",
                }}
            >
                {is && (
                    <Target
                        onProjectionUpdate={(box: Box) => {
                            if (box.x.min > viewportWidth.current / 2 + 100) {
                                setIs(false)
                            }
                        }}
                    />
                )}
            </div>
            <div
                style={{
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    width: "50%",
                    height: "100%",
                }}
            >
                {!is && (
                    <Target
                        onProjectionUpdate={(box: Box) => {
                            if (box.x.min < viewportWidth.current / 2 - 100) {
                                setIs(true)
                            }
                        }}
                    />
                )}
            </div>
        </>
    )
}

