    const handleAnimationComplete = useCallback(() => {
        controls.start(animation)
    }, [controls])

    useEffect(() => {
        controls.start(animation)
    }, [controls])

    return (
        <motion.svg viewBox="22 22 44 44" width="44" height="44">
            <motion.circle
                animate={controls}
                onAnimationComplete={handleAnimationComplete}
                r="20.2"
                fill="none"
                stroke="white"
                strokeWidth="3.6"
            />
        </motion.svg>
    )
}

